def _schema_with_legacy_action_path_for_http(schema: Dict[str, Any]) -> Dict[str, Any]:
    http_schema = json.loads(json.dumps(schema))
    paths = http_schema.setdefault("paths", {})
    canonical = paths.get("/bff/actions/{type}/{id}/{action}")
    if not isinstance(canonical, dict):
        return http_schema
    legacy_path = "/bff/actions/{entityType}/{entityId}/{actionId}"
    if legacy_path in paths:
        return http_schema
    legacy = json.loads(json.dumps(canonical))
    rename = {"type": "entityType", "id": "entityId", "action": "actionId"}
    for operation in legacy.values():
        if not isinstance(operation, dict):
            continue
        if operation.get("operationId"):
            operation["operationId"] = f"{operation['operationId']}_legacy_named"
        for parameter in operation.get("parameters") or []:
            if isinstance(parameter, dict) and parameter.get("in") == "path":
                name = str(parameter.get("name") or "")
                if name in rename:
                    parameter["name"] = rename[name]
    paths[legacy_path] = legacy
    return http_schema


def _custom_openapi() -> Dict[str, Any]:
    if app.openapi_schema is None:
        app.openapi_schema = get_openapi(
            title=app.title,
            version=app.version,
            routes=app.routes,
        )
    if _OPENAPI_HTTP_CONTEXT.get():
        return _schema_with_legacy_action_path_for_http(app.openapi_schema)
    return app.openapi_schema


app.openapi = _custom_openapi  # type: ignore[method-assign]


@app.middleware("http")
async def _openapi_http_schema_context(request: Request, call_next):
    token = None
    if request.url.path == app.openapi_url:
        token = _OPENAPI_HTTP_CONTEXT.set(True)
    try:
        return await call_next(request)
    finally:
        if token is not None:
            _OPENAPI_HTTP_CONTEXT.reset(token)


@app.middleware("http")
async def _request_dry_run_context(request: Request, call_next):
    token = _REQUEST_DRY_RUN_CONTEXT.set(_truthy_header(request.headers.get("X-Dry-Run")))
    try:
        return await call_next(request)
    finally:
        _REQUEST_DRY_RUN_CONTEXT.reset(token)


def _explicit_token_capabilities(identity: OperatorIdentity) -> List[str]:
    claims = getattr(identity, "claims", {}) or {}
    if not isinstance(claims, dict):
        return []
    raw = (
        claims.get("capabilities")
        or claims.get("capability")
        or claims.get("scp")
        or claims.get("scope")
        or []
    )
    if isinstance(raw, str):
        values = re.split(r"[\s,]+", raw)
    elif isinstance(raw, (list, tuple, set)):
        values = list(raw)
    else:
        values = []
    deduped: List[str] = []
    seen = set()
    for value in values:
        clean = str(value or "").strip()
        if clean and clean not in seen:
            deduped.append(clean)
            seen.add(clean)
    return deduped


def _is_agora_only_token(identity: OperatorIdentity) -> bool:
    capabilities = _explicit_token_capabilities(identity)
    return bool(capabilities) and all(capability.startswith("agora.") for capability in capabilities)


@app.middleware("http")
async def _management_rejects_agora_scope(request: Request, call_next):
    path = request.url.path
    if request.method == "OPTIONS" or not (path == "/bff/management" or path.startswith("/bff/management/")):
        return await call_next(request)

    authorization = request.headers.get("authorization")
    if not authorization:
        return await call_next(request)
    try:
        identity = _extract_identity(authorization)
    except HTTPException:
        return await call_next(request)

    if not _is_agora_only_token(identity):
        return await call_next(request)

    correlation_id = _error_response_correlation_id(request)
    return _pack_d_error_response(
        status_code=403,
        code=ErrorCode.FORBIDDEN,
        message="Agora-scoped token cannot access Management routes",
        correlation_id=correlation_id,
        details={
            "reason": "AGORA_SCOPE_VIOLATION",
            "precondition_failed": "agora_scope",
            "route": path,
        },
    )


def _bff_session_contract_exempt(path: str) -> bool:
    return path in {"/bff/auth/dev-login", "/bff/auth/refresh", "/bff/logout"}


@app.middleware("http")
async def _cookie_session_mutation_origin_guard(request: Request, call_next):
    """Reject ambient cookie mutations that do not come from an allowed FE.

    Bearer sessions are not ambient browser credentials and are unaffected.
    A ``pantheon_session`` cookie, however, is sent by the browser implicitly;
    accepting a mutating request without an allowed ``Origin`` would turn the
    cookie compatibility path into a CSRF bypass.  The guard deliberately runs
    before route handlers, including refresh/logout, and uses the same exact
    allowlist as credentialed CORS.
    """
    if request.method in {"POST", "PUT", "PATCH", "DELETE"}:
        authorization = request.headers.get("authorization")
        pantheon_session = request.cookies.get("pantheon_session")
        if pantheon_session and not authorization:
            origin = request.headers.get("origin")
            if not origin or not _cors_origin_allowed(origin):
                correlation_id = _error_response_correlation_id(request)
                return _pack_d_error_response(
                    status_code=403,
                    code=ErrorCode.FORBIDDEN,
                    message="Cookie session mutation origin is not allowed",
                    correlation_id=correlation_id,
                    details={
                        "reason": "COOKIE_SESSION_ORIGIN_DENIED",
                        "precondition_failed": "origin",
                    },
                )
    return await call_next(request)


@app.middleware("http")
async def _bff_session_rbac_contract(request: Request, call_next):
    path = request.url.path
    if request.method == "OPTIONS" or not path.startswith("/bff/") or _bff_session_contract_exempt(path):
        return await call_next(request)

    authorization = request.headers.get("authorization")
    pantheon_session = request.cookies.get("pantheon_session")
    if not authorization and not pantheon_session:
        return await call_next(request)

    try:
        identity = _extract_identity(
            authorization,
            mfa_token=request.headers.get("x-mfa-token"),
            session_cookie=pantheon_session,
        )
        _require_read_role(identity)
        _raise_if_session_logged_out(identity)
        requested_tenant = _first_nonblank(
            request.headers.get("x-tenant-id"),
            request.headers.get("x-pantheon-tenant"),
        )
        if requested_tenant:
            _bff_me_tenant_payload(identity, requested_tenant=requested_tenant)
    except HTTPException as exc:
        return _pack_d_http_exception_response(request, exc)

    return await call_next(request)


