    meta: Dict[str, Any] = {
        "snapshot_at": snapshot_at,
        "surfaces": {
            "audit_trail": audit_surface,
        },
    }

    return {
        "entries": entries,
        "page_info": {
            "next_page_token": next_page_token,
        },
        "meta": meta,
    }


