@app.post("/bff/agora/feedback", status_code=201)
async def bff_create_agora_feedback(
    payload: Dict[str, Any] = Body(...),
    authorization: Optional[str] = Header(default=None),
    idempotency_key: Optional[str] = Header(default=None, alias="Idempotency-Key"),
    x_idempotency_key: Optional[str] = Header(default=None, alias="X-Idempotency-Key"),
    x_dry_run: Optional[str] = Header(default=None, alias="X-Dry-Run"),
    x_correlation_id: Optional[str] = Header(default=None, alias="X-Correlation-Id"),
):
    """BFF: canonical bulk feedback write for Agora signals."""
    identity = _extract_identity(authorization)
    _require_agora_bulk_feedback_role(identity)
    _reject_body_idempotency_key(payload)
    resolved_key = _resolve_final_idempotency_key(idempotency_key, x_idempotency_key)
    feedback_payload = _agora_bulk_feedback_payload(payload)
    dry_run = _request_dry_run_requested(x_dry_run)
    request_hash = _stable_json_hash({
        "route": "POST /bff/agora/feedback",
        "payload": feedback_payload,
    })
    if not dry_run:
        cached = _agora_core_idempotency_check(resolved_key, request_hash)
        if cached is not None:
            return JSONResponse(status_code=201, content=jsonable_encoder(cached))

    signal_id = feedback_payload["signal_id"]
    snapshot_at = utc_now()
    if not read_store.get_agora_signal(signal_id):
        raise _bff_error(
            404,
            ErrorCode.RESOURCE_NOT_FOUND,
            "Agora signal not found",
            f"Agora signal {signal_id} does not exist",
            precondition_failed="agora_feedback.signal_id",
        )

    feedback_id = f"agfb-{uuid.uuid4().hex[:12]}"
    if dry_run:
        feedback = {
            "id": feedback_id,
            "feedbackId": feedback_id,
            "signalId": signal_id,
            "decision": feedback_payload["verdict"],
            "reason": feedback_payload["memo"],
            "actorId": identity.operator_id,
            "createdAt": snapshot_at,
        }
        audit = None
        event_id = None
    else:
        feedback = read_store.create_agora_feedback(
            signal_id,
            verdict=feedback_payload["verdict"],
            memo=feedback_payload["memo"],
            actor_id=identity.operator_id,
            created_at=snapshot_at,
        )
        if feedback is None:
            raise _bff_error(
                404,
                ErrorCode.RESOURCE_NOT_FOUND,
                "Agora signal not found",
                f"Agora signal {signal_id} does not exist",
                precondition_failed="agora_feedback.signal_id",
            )
        feedback_id = str(feedback.get("feedbackId") or feedback.get("id") or feedback_id)
        audit = read_store.record_agora_audit_event({
            "action": "agora.feedback.create",
            "evidenceKind": "agora.feedback.create",
            "targetType": ObjectType.AGORA_SIGNAL.value,
            "targetId": signal_id,
            "feedbackId": feedback_id,
            "actorId": identity.operator_id,
            "recordedAt": snapshot_at,
            "idempotencyKey": resolved_key,
        })
        event_id = _publish_event(
            _sse_buffers["signal"],
            _sse_subscribers["signal"],
            "agora.feedback.created",
            {
                "channel": f"agora.signals:{signal_id}",
                "signalId": signal_id,
                "feedbackId": feedback_id,
                "verdict": feedback_payload["verdict"],
            },
        )

    result = {
        "data": {
            "id": feedback_id,
            "signal_id": signal_id,
            "signalId": signal_id,
            "verdict": feedback_payload["verdict"],
            "memo": feedback_payload["memo"],
            "author_id": identity.operator_id,
            "authorId": identity.operator_id,
            "created_at": str(feedback.get("created_at") or feedback.get("createdAt") or snapshot_at),
            "createdAt": str(feedback.get("createdAt") or feedback.get("created_at") or snapshot_at),
        },
        "meta": {
            "snapshot_at": snapshot_at,
            "dryRun": dry_run,
            "idempotency": {"idempotencyKey": resolved_key, "replayed": False},
            "audit": audit,
            "sse": {
                "channel": f"agora.signals:{signal_id}",
                "eventId": event_id,
            },
        },
    }
    result["meta"]["correlationId"] = str(x_correlation_id or "").strip() or str(uuid.uuid4())
    if not dry_run:
        _AGORA_CORE_BFF_IDEMPOTENCY[resolved_key] = {"request_hash": request_hash, "result": result}
    return JSONResponse(status_code=200 if dry_run else 201, content=jsonable_encoder(result))


@app.post("/bff/agora/signals/{signalId}/feedback")
async def bff_agora_signal_feedback(
    signalId: str,
    payload: Dict[str, Any] = Body(...),
    authorization: Optional[str] = Header(default=None),
    idempotency_key: Optional[str] = Header(default=None, alias="Idempotency-Key"),
    x_idempotency_key: Optional[str] = Header(default=None, alias="X-Idempotency-Key"),
):
    """BFF: record trader feedback for an Agora signal."""
    identity = _extract_identity(authorization)
    _require_operator_role(identity)
    _reject_body_idempotency_key(payload)
    resolved_key = _resolve_final_idempotency_key(idempotency_key, x_idempotency_key)
    feedback_payload = _agora_signal_feedback_payload(payload)
    request_hash = _stable_json_hash({
        "route": "POST /bff/agora/signals/{signalId}/feedback",
        "signalId": signalId,
        "payload": feedback_payload,
    })
    dry_run = _request_dry_run_requested()
    if not dry_run:
        cached = _agora_core_idempotency_check(resolved_key, request_hash)
        if cached is not None:
            return cached
    if dry_run:
        signal = read_store.get_agora_signal(signalId)
        if signal is None:
            raise _bff_error(
                404,
                ErrorCode.RESOURCE_NOT_FOUND,
                "Agora signal not found",
                f"Agora signal {signalId} does not exist",
                precondition_failed="signal_id",
            )
        snapshot_at = utc_now()
        feedback_id = f"agfb-dryrun-{uuid.uuid4().hex[:8]}"
        return _dry_run_success_response(
            {
                "status": "completed",
                "signal": {**signal, "reviewStatus": feedback_payload["decision"], "latestFeedbackId": feedback_id},
                "feedback": {
                    "id": feedback_id,
                    "feedbackId": feedback_id,
                    "signalId": signalId,
                    "decision": feedback_payload["decision"],
                    "confidence": feedback_payload["confidence"],
                    "reason": feedback_payload["reason"],
                    "actorId": identity.operator_id,
                    "createdAt": snapshot_at,
                },
            },
            snapshot_at=snapshot_at,
            idempotency_key=resolved_key,
            evidence_kind="agora.signal.feedback",
        )
    feedback = read_store.record_agora_signal_feedback(
        signalId,
        decision=feedback_payload["decision"],
        confidence=feedback_payload["confidence"],
        reason=feedback_payload["reason"],
        actor_id=identity.operator_id,
        edit_window_seconds=feedback_payload["edit_window_seconds"],
        recorded_at=utc_now(),
    )
    if feedback is None:
        raise _bff_error(
            404,
            ErrorCode.RESOURCE_NOT_FOUND,
            "Agora signal not found",
            f"Agora signal {signalId} does not exist",
            precondition_failed="signal_id",
        )
    command = _agora_submit_command(
        entity_type=ObjectType.AGORA_SIGNAL,
        entity_id=signalId,
        action_id="feedback",
        resolved_key=resolved_key,
        identity=identity,
        payload=feedback_payload,
        command_type=CommandType.AGORA_SIGNAL_FEEDBACK,
    )
    _publish_event(
        _sse_buffers["signal"],
        _sse_subscribers["signal"],
        "agora.signal.feedback_recorded",
        {"signalId": signalId, "feedbackId": feedback.get("feedbackId"), "decision": feedback.get("decision")},
    )
    result = {
        "status": ActionCommandStatus.COMPLETED.value,
        "data": {
            "feedback": feedback,
            "signal": read_store.get_agora_signal(signalId),
        },
        "meta": {
            "command": command.get("data"),
            "audit": (command.get("meta") or {}).get("audit"),
            "idempotency": {"idempotencyKey": resolved_key, "replayed": False},
        },
    }
    _AGORA_CORE_BFF_IDEMPOTENCY[resolved_key] = {"request_hash": request_hash, "result": result}
    return result


