def _persona_provisioning_store():
    """Lazily bootstrap the durable cross-replica coordination ledger."""
    global _PERSONA_PROVISIONING_STORE
    if _PERSONA_PROVISIONING_STORE is not None:
        return _PERSONA_PROVISIONING_STORE
    with _PERSONA_PROVISIONING_STORE_LOCK:
        if _PERSONA_PROVISIONING_STORE is None:
            _PERSONA_PROVISIONING_STORE = make_persona_provisioning_store()
    return _PERSONA_PROVISIONING_STORE


class _PersonaOwnerHttpTransport:
    """Strict synchronous transport to canonical provisioning owner APIs."""

    _OWNER_ENVIRONMENTS = {
        "capital": ("PANTHEON_CAPITAL_API_URL", "PANTHEON_CAPITAL_SERVICE_URL"),
        "registry": ("PANTHEON_REGISTRY_API_URL", "PANTHEON_REGISTRY_URL"),
        "governance": (
            "PANTHEON_GOVERNANCE_APPROVAL_API_URL",
            "PANTHEON_GOVERNANCE_SERVICE_URL",
        ),
        "deployment": ("PANTHEON_DEPLOYMENT_API_URL", "PANTHEON_DEPLOYMENT_SERVICE_URL"),
    }

    @classmethod
    def _url(cls, owner: str, path: str) -> str:
        env_names = cls._OWNER_ENVIRONMENTS.get(owner)
        if env_names is None:
            raise RuntimeError(f"Unknown Persona provisioning owner: {owner}")
        for env_name in env_names:
            base = os.getenv(env_name, "").strip().rstrip("/")
            if base:
                return f"{base}{path}"
        raise RuntimeError(
            f"Persona provisioning owner {owner} is unconfigured; set {env_names[0]}"
        )

    def get(self, owner: str, path: str) -> Optional[Dict[str, Any]]:
        try:
            value = _get_json(self._url(owner, path))
        except urllib_error.HTTPError as exc:
            if exc.code == 404:
                return None
            raise
        if not isinstance(value, dict):
            raise RuntimeError(f"{owner} GET {path} returned a non-object receipt")
        return value

    def post(self, owner: str, path: str, payload: Mapping[str, Any]) -> Dict[str, Any]:
        value = _post_json(self._url(owner, path), dict(payload))
        if not isinstance(value, dict):
            raise RuntimeError(f"{owner} POST {path} returned a non-object receipt")
        return value

    def patch(self, owner: str, path: str, payload: Mapping[str, Any]) -> Dict[str, Any]:
        request = urllib_request.Request(
            self._url(owner, path),
            data=json.dumps(dict(payload)).encode("utf-8"),
            headers={"Accept": "application/json", "Content-Type": "application/json"},
            method="PATCH",
        )
        timeout = max(1, int(os.getenv("PANTHEON_COMMAND_TIMEOUT_SECONDS", "30")))
        with urllib_request.urlopen(request, timeout=timeout) as response:
            value = json.loads(response.read().decode("utf-8"))
        if not isinstance(value, dict):
            raise RuntimeError(f"{owner} PATCH {path} returned a non-object receipt")
        return value


def _strategy_persona_idempotency_check(
    resolved_key: str,
    request_hash: str,
) -> Optional[Dict[str, Any]]:
    existing = _STRATEGY_PERSONA_BFF_IDEMPOTENCY.get(resolved_key)
    if existing is None:
        return None
    if existing.get("request_hash") != request_hash:
        raise _bff_error(
            409,
            ErrorCode.IDEMPOTENCY_CONFLICT,
            "Idempotency key was already used with a different payload",
            f"Key {resolved_key!r} is bound to a different request hash",
            precondition_failed="idempotency_conflict",
            suggestion="Use a new Idempotency-Key or resubmit the original payload unchanged",
        )
    return deepcopy(existing.get("result"))


def _strategy_seed_replication_idempotency_check(
    resolved_key: str,
    request_hash: str,
) -> Optional[Dict[str, Any]]:
    existing = _STRATEGY_SEED_REPLICATION_BFF_IDEMPOTENCY.get(resolved_key)
    if existing is None:
        return None
    if existing.get("request_hash") != request_hash:
        raise _bff_error(
            409,
            ErrorCode.IDEMPOTENCY_CONFLICT,
            "Idempotency key was already used with a different payload",
            f"Key {resolved_key!r} is bound to a different request hash",
            precondition_failed="idempotency_conflict",
            suggestion="Use a new Idempotency-Key or resubmit the original payload unchanged",
        )
    result = json.loads(json.dumps(existing.get("result") or {}))
    meta = result.setdefault("meta", {})
    idempotency = meta.setdefault("idempotency", {})
    idempotency["replayed"] = True
    return result


def _require_strategy_seed_submit_role(identity: OperatorIdentity) -> None:
    if {"operator", "admin"}.intersection(identity.roles):
        return
    raise _bff_error(
        403,
        ErrorCode.FORBIDDEN,
        "Strategy seed replication submit requires operator role",
        "Read-role users cannot submit StrategySpecSeed replication tasks.",
        precondition_failed="role_check",
        suggestion="Escalate to a user with operator or admin role",
    )


def _strategy_seed_replication_error(exc: StrategySeedReplicationBridgeError) -> HTTPException:
    if exc.code == "seed_not_found":
        return _bff_error(
            404,
            ErrorCode.RESOURCE_NOT_FOUND,
            "StrategySpecSeed not found",
            str(exc),
            precondition_failed="seed_id",
        )
    if exc.code == "invalid_seed_status":
        return _bff_error(
            409,
            ErrorCode.OPERATION_NOT_ALLOWED,
            "StrategySpecSeed is not eligible for replication",
            str(exc),
            precondition_failed="status",
            suggestion="Promote the seed to StrategySpec before submitting replication.",
        )
    return _bff_error(
        422,
        ErrorCode.VALIDATION_FAILED,
        "StrategySpecSeed replication request is invalid",
        str(exc),
        precondition_failed=exc.code or "replication_request",
    )


def _strategy_seed_replication_response(
    *,
    seed_id: str,
    payload: Dict[str, Any],
    identity: OperatorIdentity,
    resolved_key: str,
) -> Dict[str, Any]:
    request_hash = _stable_json_hash(
        {
            "route": "POST /bff/management/strategy-seeds/{seed_id}/submit-replication",
            "seed_id": seed_id,
            "payload": payload,
        }
    )
    cached = _strategy_seed_replication_idempotency_check(resolved_key, request_hash)
    if cached is not None:
        return cached

    try:
        submission = StrategySeedReplicationBridge().submit_seed_to_replication(
            seed_id,
            requested_by=identity.operator_id,
            idempotency_key=resolved_key,
            created_at=payload.get("created_at") or None,
            strategy_spec_version=str(payload.get("strategy_spec_version") or "1.0.0"),
        )
    except StrategySeedReplicationBridgeError as exc:
        raise _strategy_seed_replication_error(exc) from exc

    snapshot_at = submission.created_at or utc_now()
    result = {
        "data": {
            "seed_id": submission.seed_id,
            "replication_ref": submission.replication_ref,
            "experiment_task_id": submission.experiment_task_id,
            "strategy_id": submission.strategy_id,
            "strategy_spec_version": submission.strategy_spec_version,
            "research_task_id": submission.research_task.get("task_id"),
            "status": submission.research_task.get("status") or "queued",
            "experiment_task": dict(submission.experiment_task),
            "registry_write_performed": False,
            "execution_route": "none",
            "deployment_authority": "none",
            "approved_artifact_created": False,
            "deployment_plan_created": False,
            "runtime_binding_created": False,
            "idempotent_replay": submission.idempotent_replay,
        },
        "meta": {
            "snapshot_at": snapshot_at,
            "research_only": True,
            "execution_route": "none",
            "idempotency": {
                "idempotencyKey": resolved_key,
                "replayed": False,
            },
        },
    }
    _STRATEGY_SEED_REPLICATION_BFF_IDEMPOTENCY[resolved_key] = {
        "request_hash": request_hash,
        "result": result,
    }
    return result


