def _require_strategy_seed_review_role(identity: OperatorIdentity) -> None:
    if {"operator", "admin"}.intersection(identity.roles):
        return
    raise _bff_error(
        403,
        ErrorCode.FORBIDDEN,
        "Strategy seed review command requires operator role",
        "Read-role users cannot execute StrategySpecSeed review actions.",
        precondition_failed="role_check",
        suggestion="Escalate to a user with operator or admin role",
    )


def _strategy_seed_review_error(exc: Exception) -> HTTPException:
    code = getattr(exc, "code", "")
    if code == "idempotency_conflict":
        return _bff_error(
            409,
            ErrorCode.IDEMPOTENCY_CONFLICT,
            "Idempotency key was already used with a different payload",
            str(exc),
            precondition_failed="idempotency_conflict",
            suggestion="Use a new Idempotency-Key or resubmit the original payload unchanged",
        )
    if code in {"seed_not_found", "merge_target_not_found"}:
        return _bff_error(
            404,
            ErrorCode.RESOURCE_NOT_FOUND,
            "StrategySpecSeed not found",
            str(exc),
            precondition_failed="seed_id",
        )
    if code in {"terminal_seed_status", "invalid_status_transition", "invalid_merge_target"}:
        return _bff_error(
            409,
            ErrorCode.OPERATION_NOT_ALLOWED,
            "StrategySpecSeed review action is not allowed",
            str(exc),
            precondition_failed="status",
        )
    return _bff_error(
        422,
        ErrorCode.VALIDATION_FAILED,
        "StrategySpecSeed review request is invalid",
        str(exc),
        precondition_failed=code or "review_request",
    )


def _strategy_seed_status_value(seed: Any) -> str:
    status = getattr(seed, "status", "")
    return status.value if hasattr(status, "value") else str(status or "")


def _strategy_seed_source_kind(seed: Any) -> str:
    metadata = dict(getattr(seed, "metadata", {}) or {})
    return str(
        metadata.get("source_kind")
        or metadata.get("source_type")
        or metadata.get("source_connector_kind")
        or "strategy_spec_seed"
    )


def _strategy_seed_strategy_family(seed: Any) -> str:
    metadata = dict(getattr(seed, "metadata", {}) or {})
    family = (
        metadata.get("strategy_family")
        or metadata.get("strategy_kind")
        or metadata.get("archetype")
    )
    if family:
        return str(family)
    hints = list(getattr(seed, "feature_hints", []) or [])
    return str(hints[0]) if hints else ""


_SEED_KINDS_RISK = frozenset({"risk_constraint", "execution_constraint"})
_SEED_KINDS_NEGATIVE = frozenset({"negative", "negative_memory"})


def _strategy_seed_allowed_actions(status: str, seed_kind: str = "") -> List[str]:
    actions_by_status = {
        "draft": ["accept", "reject", "request-evidence", "archive", "merge"],
        "needs_more_evidence": ["accept", "reject", "request-evidence", "archive", "merge"],
        "accepted": ["convert-to-spec-seed", "reject", "request-evidence", "archive", "merge"],
        "promoted_to_strategy_spec": ["submit-replication"],
        "rejected": [],
        "archived_as_insight": [],
        "merged": [],
        "converted_to_risk_constraint": [],
        "converted_to_negative": [],
    }
    actions = list(actions_by_status.get(status, []))
    if status in {"draft", "needs_more_evidence", "accepted"}:
        if seed_kind in _SEED_KINDS_RISK and "convert-to-risk" not in actions:
            actions.append("convert-to-risk")
        if seed_kind in _SEED_KINDS_NEGATIVE and "convert-to-negative" not in actions:
            actions.append("convert-to-negative")
    return actions


def _strategy_seed_metadata_suggestions(seed: Any) -> List[Dict[str, Any]]:
    metadata = dict(getattr(seed, "metadata", {}) or {})
    raw_items = metadata.get("suggested_actions") or metadata.get("suggestions") or []
    if isinstance(raw_items, dict):
        raw_items = [raw_items]
    if isinstance(raw_items, str):
        raw_items = [{"type": raw_items}]
    suggestions: List[Dict[str, Any]] = []
    iterable = raw_items if isinstance(raw_items, list) else []
    for raw in iterable:
        if not isinstance(raw, dict):
            continue
        action_type = str(raw.get("type") or raw.get("action") or "").strip()
        if not action_type:
            continue
        item = dict(raw)
        item["type"] = action_type
        item.setdefault("source", "seed_metadata")
        item.setdefault("mode", "suggestion")
        item.setdefault("requires_operator_review", True)
        item.setdefault("auto_promote", False)
        suggestions.append(item)

    recommended = metadata.get("recommended_action")
    if isinstance(recommended, str):
        recommended = {"type": recommended}
    if isinstance(recommended, dict):
        action_type = str(recommended.get("type") or recommended.get("action") or "").strip()
        if action_type:
            item = dict(recommended)
            item["type"] = action_type
            item.setdefault("source", "seed_metadata")
            item.setdefault("mode", "suggestion")
            item.setdefault("requires_operator_review", True)
            item.setdefault("auto_promote", False)
            suggestions.append(item)
    return suggestions


def _strategy_seed_persona_suggestions(seed: Any, *, snapshot_at: str) -> List[Dict[str, Any]]:
    suggestions: List[Dict[str, Any]] = []
    try:
        personas = _list_persona_records()
    except Exception as exc:  # pragma: no cover - defensive read surface fallback.
        log.warning("Persona read surface unavailable for seed inbox suggestions: %s", exc)
        return suggestions

    for persona in personas:
        persona_id = str(persona.get("persona_id") or persona.get("id") or "").strip()
        if not persona_id:
            continue
        try:
            route_policy = read_store.get_route_policy_for_persona(persona_id) or {}
            capability_snapshot = read_store.get_capability_snapshot_for_persona(persona_id) or {}
            profile = extract_persona_strategy_profile(
                persona,
                route_policy=route_policy,
                capability_snapshot=capability_snapshot,
            )
            matches = PersonaStrategyDiscoveryService().match_candidates(
                profile,
                strategy_seeds=[seed],
                strategy_specs=[],
                created_at=snapshot_at,
                include_blocked=True,
            )
        except Exception as exc:  # pragma: no cover - one bad persona should not break inbox.
            log.warning("Persona strategy suggestion failed for %s: %s", persona_id, exc)
            continue
        for match in matches:
            payload = match.to_dict()
            action = payload.get("recommended_action") or {}
            action_type = str(action.get("type") or "").strip()
            if (
                payload.get("matched_object_id") == getattr(seed, "seed_id", None)
                and action_type == "promote_seed_candidate"
            ):
                suggestions.append(
                    {
                        "type": "promote_seed_candidate",
                        "source": "persona_strategy_discovery",
                        "mode": "suggestion",
                        "requires_operator_review": True,
                        "auto_promote": False,
                        "persona_id": persona_id,
                        "match_id": payload.get("match_id"),
                        "score": payload.get("score"),
                        "blockers": (payload.get("metadata") or {}).get("blockers") or [],
                    }
                )
    return suggestions


def _strategy_seed_suggestions(seed: Any, *, snapshot_at: str) -> List[Dict[str, Any]]:
    seen: Set[Tuple[str, str, str]] = set()
    suggestions: List[Dict[str, Any]] = []
    for item in [
        *_strategy_seed_metadata_suggestions(seed),
        *_strategy_seed_persona_suggestions(seed, snapshot_at=snapshot_at),
    ]:
        key = (
            str(item.get("type") or ""),
            str(item.get("source") or ""),
            str(item.get("match_id") or item.get("persona_id") or ""),
        )
        if key in seen:
            continue
        seen.add(key)
        suggestions.append(item)
    return suggestions


def _strategy_seed_similar_existing_strategies(seed: Any) -> List[Dict[str, Any]]:
    metadata = dict(getattr(seed, "metadata", {}) or {})
    raw = metadata.get("similar_existing_strategies") or []
    if isinstance(raw, str):
        raw = [{"strategy_id": raw}]
    if isinstance(raw, list) and raw:
        return [
            dict(item) if isinstance(item, dict) else {"strategy_id": str(item)}
            for item in raw[:5]
        ]

    family = _strategy_seed_strategy_family(seed)
    if not family:
        return []
    try:
        candidates = _list_strategy_summaries()
    except Exception:  # pragma: no cover - read-store fallback.
        return []
    similar: List[Dict[str, Any]] = []
    for item in candidates:
        strategy_family = str(
            item.get("strategy_family")
            or (item.get("metadata") or {}).get("strategy_family")
            or item.get("archetype")
            or ""
        )
        if strategy_family != family:
            continue
        similar.append(
            {
                "strategy_id": item.get("strategy_id") or item.get("id"),
                "title": item.get("title") or item.get("name"),
                "strategy_family": strategy_family,
            }
        )
        if len(similar) >= 5:
            break
    return similar


def _strategy_seed_recommended_action(
    *,
    status: str,
    seed_kind: str = "",
    suggestions: List[Dict[str, Any]],
) -> Dict[str, Any]:
    for item in suggestions:
        if str(item.get("type") or "") == "promote_seed_candidate":
            return dict(item)
    if status == "accepted":
        if seed_kind in _SEED_KINDS_RISK:
            return {"type": "convert-to-risk", "mode": "operator_decision"}
        if seed_kind in _SEED_KINDS_NEGATIVE:
            return {"type": "convert-to-negative", "mode": "operator_decision"}
        return {"type": "convert-to-spec-seed", "mode": "operator_decision"}
    if status in {"draft", "needs_more_evidence"}:
        if seed_kind in _SEED_KINDS_RISK:
            return {"type": "accept", "mode": "operator_decision", "next": "convert-to-risk"}
        if seed_kind in _SEED_KINDS_NEGATIVE:
            return {"type": "accept", "mode": "operator_decision", "next": "convert-to-negative"}
        return {"type": "accept", "mode": "operator_decision"}
    if status == "promoted_to_strategy_spec":
        return {"type": "submit-replication", "mode": "operator_decision"}
    return {"type": "none", "mode": "terminal"}


def _strategy_seed_negative_memory_warning(seed: Any) -> Dict[str, Any]:
    raw = getattr(seed, "negative_memory_match", None)
    if not raw:
        return {"warning_level": "info", "similarity": 0.0, "reason": ""}
    match = dict(raw) if isinstance(raw, dict) else (raw.to_dict() if hasattr(raw, "to_dict") else {})
    return {
        "warning_level": str(match.get("warning_level") or "info"),
        "similarity": float(match.get("similarity") or 0.0),
        "reason": str(match.get("reason") or ""),
        "matched_memory_id": match.get("matched_memory_id"),
        "matched_memory_kind": match.get("matched_memory_kind"),
        "matched_terms": list(match.get("matched_terms") or []),
    }


def _strategy_seed_card(seed: Any, *, snapshot_at: str, include_audit: bool = False) -> Dict[str, Any]:
    status = _strategy_seed_status_value(seed)
    suggestions = _strategy_seed_suggestions(seed, snapshot_at=snapshot_at)
    lineage = dict(getattr(seed, "lineage", {}) or {})
    metadata = dict(getattr(seed, "metadata", {}) or {})
    evidence_refs = list(getattr(seed, "evidence_item_ids", []) or [])
    citation_refs = list(getattr(seed, "citation_refs", []) or [])
    seed_kind = str(metadata.get("seed_kind") or "strategy_spec_seed")
    source_surface = str(metadata.get("source_surface") or "")
    card = {
        "id": seed.seed_id,
        "seed_id": seed.seed_id,
        "source": {
            "source_id": seed.source_id,
            "source_ids": list(getattr(seed, "source_ids", []) or []),
            "source_kind": _strategy_seed_source_kind(seed),
            "source_surface": source_surface or None,
            "evidence_bundle_id": seed.evidence_bundle_id,
        },
        "seed_kind": seed_kind,
        "strategy_family": _strategy_seed_strategy_family(seed),
        "hypothesis": seed.hypothesis,
        "market": {
            "asset_class": list(getattr(seed, "asset_class", []) or []),
            "market_scope": list(getattr(seed, "market_scope", []) or []),
            "holding_period": getattr(seed, "holding_period", None),
        },
        "asset": list(getattr(seed, "asset_class", []) or []),
        "required_data": list(getattr(seed, "required_data", []) or []),
        "evidence_count": len(set([*evidence_refs, *citation_refs])),
        "confidence": getattr(seed, "confidence", None),
        "negative_memory_warning": _strategy_seed_negative_memory_warning(seed),
        "similar_existing_strategies": _strategy_seed_similar_existing_strategies(seed),
        "recommended_action": _strategy_seed_recommended_action(
            status=status,
            seed_kind=seed_kind,
            suggestions=suggestions,
        ),
        "suggested_actions": suggestions,
        "review_status": status,
        "status": status,
        "allowedActions": _strategy_seed_allowed_actions(status, seed_kind),
        "lineage_refs": {
            "evidence_bundle_id": seed.evidence_bundle_id,
            "source_ids": list(getattr(seed, "source_ids", []) or []),
            "evidence_item_ids": evidence_refs,
            "citation_refs": citation_refs,
            "trace_refs": list(getattr(seed, "trace_refs", []) or []),
            "registry_write_performed": lineage.get("registry_write_performed", False),
            "execution_route": lineage.get("execution_route") or "none",
        },
        "created_at": getattr(seed, "created_at", None),
    }
    if include_audit:
        card["review_decisions"] = list(lineage.get("review_decisions") or [])
        card["last_review_decision"] = lineage.get("last_review_decision")
    return card


def _strategy_seed_matches_filters(
    seed: Any,
    *,
    status: Optional[str],
    source_kind: Optional[str],
    strategy_family: Optional[str],
    seed_kind: Optional[str],
    min_confidence: Optional[float],
) -> bool:
    if status and _strategy_seed_status_value(seed) != status:
        return False
    if source_kind and _strategy_seed_source_kind(seed) != source_kind:
        return False
    if strategy_family and _strategy_seed_strategy_family(seed) != strategy_family:
        return False
    if seed_kind:
        metadata = dict(getattr(seed, "metadata", {}) or {})
        actual_seed_kind = str(metadata.get("seed_kind") or "strategy_spec_seed")
        if actual_seed_kind != seed_kind:
            return False
    if min_confidence is not None and float(getattr(seed, "confidence", 0.0) or 0.0) < min_confidence:
        return False
    return True


def _strategy_seed_list_response(
    *,
    status: Optional[str],
    source_kind: Optional[str],
    strategy_family: Optional[str],
    seed_kind: Optional[str],
    min_confidence: Optional[float],
    page_token: Optional[str],
    page_size: int,
) -> Dict[str, Any]:
    snapshot_at = utc_now()
    store = StrategySpecSeedStore()
    seeds = [
        seed
        for seed in store.list_all()
        if _strategy_seed_matches_filters(
            seed,
            status=status,
            source_kind=source_kind,
            strategy_family=strategy_family,
            seed_kind=seed_kind,
            min_confidence=min_confidence,
        )
    ]
    cards = [
        _strategy_seed_card(seed, snapshot_at=snapshot_at)
        for seed in seeds
    ]
    page_items, next_page_token = _page_slice(cards, page_token, page_size)
    return {
        "data": {
            "id": "management_strategy_seeds",
            "items": page_items,
            "summary": {
                "total_items": len(cards),
                "returned_items": len(page_items),
                "research_only": True,
                "execution_route": "none",
            },
        },
        "page_info": {
            "next_page_token": next_page_token,
            "total": len(cards),
            "page_size": page_size,
        },
        "meta": {
            "snapshot_at": snapshot_at,
            "store_path": str(store.path),
            "count": len(cards),
            "filters": {
                "status": status,
                "source_kind": source_kind,
                "strategy_family": strategy_family,
                "seed_kind": seed_kind,
                "min_confidence": min_confidence,
            },
            "research_only": True,
            "execution_route": "none",
        },
    }


def _strategy_seed_detail_response(seed_id: str) -> Dict[str, Any]:
    snapshot_at = utc_now()
    store = StrategySpecSeedStore()
    seed = store.get(seed_id)
    if seed is None:
        raise _bff_error(
            404,
            ErrorCode.RESOURCE_NOT_FOUND,
            "StrategySpecSeed not found",
            f"StrategySpecSeed not found: {seed_id}",
            precondition_failed="seed_id",
        )
    return {
        "data": _strategy_seed_card(seed, snapshot_at=snapshot_at, include_audit=True),
        "meta": {
            "snapshot_at": snapshot_at,
            "store_path": str(store.path),
            "research_only": True,
            "execution_route": "none",
        },
    }


def _strategy_seed_review_action(payload: Dict[str, Any]) -> str:
    action = str(
        payload.get("action")
        or payload.get("decision")
        or payload.get("type")
        or ""
    ).strip().lower().replace("-", "_")
    aliases = {
        "request_more_evidence": "request_evidence",
        "needs_more_evidence": "request_evidence",
        "convert": "convert_to_spec_seed",
        "convert_to_strategy_spec": "convert_to_spec_seed",
        "archive_as_insight": "archive",
        "archived_as_insight": "archive",
        "convert_risk": "convert_to_risk",
        "convert_negative": "convert_to_negative",
        "convert_to_risk_constraint": "convert_to_risk",
    }
    action = aliases.get(action, action)
    if not action:
        raise _bff_error(
            422,
            ErrorCode.VALIDATION_FAILED,
            "StrategySpecSeed review action is required",
            "Set action to accept, reject, request-evidence, convert-to-spec-seed, convert-to-risk, convert-to-negative, or archive.",
            precondition_failed="action",
        )
    if action == "merge":
        raise _bff_error(
            422,
            ErrorCode.VALIDATION_FAILED,
            "Use the merge endpoint for StrategySpecSeed merge actions",
            "POST /bff/management/strategy-seeds/{seed_id}/merge handles merge review decisions.",
            precondition_failed="action",
        )
    return action


def _strategy_seed_target_refs(payload: Dict[str, Any]) -> List[Dict[str, Any]]:
    raw = payload.get("target_refs") or payload.get("targetRefs") or []
    refs: List[Dict[str, Any]] = []
    if isinstance(raw, dict):
        raw = [raw]
    if isinstance(raw, list):
        refs.extend(dict(item) for item in raw if isinstance(item, dict))
    for key, ref_type in (
        ("strategy_spec_id", "strategy_spec"),
        ("strategySpecId", "strategy_spec"),
        ("target_strategy_id", "strategy_spec"),
        ("targetStrategyId", "strategy_spec"),
    ):
        value = str(payload.get(key) or "").strip()
        if value:
            refs.append({"type": ref_type, "id": value})
    return refs


def _strategy_seed_review_result(
    *,
    updated_seed: Any,
    decision: SeedReviewDecision,
    snapshot_at: str,
    resolved_key: str,
    replayed: bool = False,
) -> Dict[str, Any]:
    return {
        "data": {
            "seed_id": updated_seed.seed_id,
            "status": _strategy_seed_status_value(updated_seed),
            "review_status": _strategy_seed_status_value(updated_seed),
            "decision": decision.to_dict(),
            "seed": _strategy_seed_card(updated_seed, snapshot_at=snapshot_at, include_audit=True),
            "registry_write_performed": False,
            "execution_route": "none",
        },
        "meta": {
            "snapshot_at": snapshot_at,
            "research_only": True,
            "execution_route": "none",
            "idempotency": {
                "idempotencyKey": resolved_key,
                "replayed": replayed,
            },
        },
    }


def _strategy_seed_review_response(
    *,
    seed_id: str,
    payload: Dict[str, Any],
    identity: OperatorIdentity,
    resolved_key: str,
) -> Dict[str, Any]:
    action = _strategy_seed_review_action(payload)
    request_hash = _stable_json_hash(
        {
            "route": "POST /bff/management/strategy-seeds/{seed_id}/review",
            "seed_id": seed_id,
            "action": action,
            "payload": payload,
        }
    )
    cached = _strategy_seed_review_idempotency_check(resolved_key, request_hash)
    if cached is not None:
        return cached
    snapshot_at = utc_now()
    try:
        updated, decision = StrategySpecSeedStore().record_review_decision(
            seed_id,
            decision=action,
            reviewer_id=identity.operator_id,
            reason=str(payload.get("reason") or ""),
            target_refs=_strategy_seed_target_refs(payload),
            created_at=payload.get("created_at") or snapshot_at,
            idempotency_key=resolved_key,
            request_hash=request_hash,
        )
    except (StrategySpecSeedReviewError, StrategySpecSeedStoreError) as exc:
        raise _strategy_seed_review_error(exc) from exc
    result = _strategy_seed_review_result(
        updated_seed=updated,
        decision=decision,
        snapshot_at=snapshot_at,
        resolved_key=resolved_key,
        replayed=bool(getattr(decision, "idempotent_replay", False)),
    )
    _STRATEGY_SEED_REVIEW_BFF_IDEMPOTENCY[resolved_key] = {
        "request_hash": request_hash,
        "result": result,
    }
    return result


def _strategy_seed_merge_response(
    *,
    seed_id: str,
    payload: Dict[str, Any],
    identity: OperatorIdentity,
    resolved_key: str,
) -> Dict[str, Any]:
    target_seed_id = str(
        payload.get("target_seed_id")
        or payload.get("targetSeedId")
        or payload.get("target_id")
        or payload.get("targetId")
        or ""
    ).strip()
    if not target_seed_id:
        raise _bff_error(
            422,
            ErrorCode.VALIDATION_FAILED,
            "StrategySpecSeed merge target is required",
            "Set target_seed_id to the StrategySpecSeed that will absorb this candidate.",
            precondition_failed="target_seed_id",
        )
    request_hash = _stable_json_hash(
        {
            "route": "POST /bff/management/strategy-seeds/{seed_id}/merge",
            "seed_id": seed_id,
            "payload": payload,
        }
    )
    cached = _strategy_seed_review_idempotency_check(resolved_key, request_hash)
    if cached is not None:
        return cached
    snapshot_at = utc_now()
    try:
        updated, decision = StrategySpecSeedStore().merge_seed(
            seed_id,
            target_seed_id=target_seed_id,
            reviewer_id=identity.operator_id,
            reason=str(payload.get("reason") or ""),
            target_refs=_strategy_seed_target_refs(payload),
            created_at=payload.get("created_at") or snapshot_at,
            idempotency_key=resolved_key,
            request_hash=request_hash,
        )
    except (StrategySpecSeedReviewError, StrategySpecSeedStoreError) as exc:
        raise _strategy_seed_review_error(exc) from exc
    result = _strategy_seed_review_result(
        updated_seed=updated,
        decision=decision,
        snapshot_at=snapshot_at,
        resolved_key=resolved_key,
        replayed=bool(getattr(decision, "idempotent_replay", False)),
    )
    _STRATEGY_SEED_REVIEW_BFF_IDEMPOTENCY[resolved_key] = {
        "request_hash": request_hash,
        "result": result,
    }
    return result


def _strategy_persona_action_command(
    *,
    entity_type: ObjectType,
    entity_id: str,
    action_id: str,
    resolved_key: str,
    identity: OperatorIdentity,
    payload: Dict[str, Any],
    command_type: CommandType,
) -> Dict[str, Any]:
    """Submit a strategy / persona resource action through the command store
    and return the final command envelope.

    The /bff/strategies/{id}/actions/{actionId} and /bff/personas/{id}/actions/{actionId}
    endpoints accept action ids declared in the canonical action catalog
    (see action_catalog.py). Idempotency is enforced through the
    `_STRATEGY_PERSONA_BFF_IDEMPOTENCY` ledger so callers receive a stable
    receipt on safe retries.
    """
    request_hash = _stable_json_hash(
        {
            "route": f"POST /bff/{entity_type.value.lower()}/{{id}}/actions",
            "entity_type": entity_type.value,
            "entity_id": entity_id,
            "action_id": action_id,
            "payload": payload,
        }
    )
    cached = _strategy_persona_idempotency_check(resolved_key, request_hash)
    if cached is not None:
        return cached

    catalog_entry = get_catalog_entry(command_type.value)
    staleness_warning = _check_read_surface_state()
    command_id = str(uuid.uuid4())
    submitted_at = utc_now()
    target = TargetObject(type=entity_type, id=entity_id)
    audit_action = _foundation_audit_for_command_record(
        identity=identity,
        command_type=command_type,
        target_type=entity_type,
        target_id=entity_id,
        payload={"action_id": action_id, **payload},
        reason=str(payload.get("reason") or action_id or command_type.value),
        command_id=command_id,
        idempotency_key=resolved_key,
        route=f"POST /bff/{entity_type.value}/{entity_id}/actions/{action_id}",
        metadata={"action_id": action_id, "catalog_entry": catalog_entry.action_id if catalog_entry else None},
    )
    audit_record = {
        "operator_id": identity.operator_id,
        "roles_at_submission": identity.roles,
        "action_id": action_id,
        "preconditions_checked": ["authentication", "authorization", "idempotency"],
        "timestamp": submitted_at,
        "idempotency_key": resolved_key,
        "request_hash": request_hash,
        "catalog_entry": catalog_entry.action_id if catalog_entry else None,
    }
    foundation_ctx = {
        "idempotency_record": {
            "idempotency_key": resolved_key,
            "request_hash": request_hash,
            "operation_type": f"bff.{command_type.value}",
            "target_ref": f"{entity_type.value}:{entity_id}",
            "trace_id": audit_action.trace_id,
        },
        "audit_action": audit_action.to_dict(),
    }
    audit_record["foundation"] = foundation_ctx
    command_store.submit_command(
        command_id=command_id,
        command_type=command_type,
        target=target,
        submitted_at=submitted_at,
        params={"action_id": action_id, **payload},
        audit_context=audit_record,
        foundation_context=foundation_ctx,
    )
    result = _project_final_command_response(
        command_id=command_id,
        command=command_type,
        accepted_at=submitted_at,
        status=CommandStatus.SUBMITTED,
        staleness_warning=staleness_warning,
    )
    payload_dump: Dict[str, Any]
    if hasattr(result, "model_dump"):
        payload_dump = result.model_dump(mode="json")
    elif isinstance(result, dict):
        payload_dump = result
    else:
        payload_dump = {"data": result}
    _STRATEGY_PERSONA_BFF_IDEMPOTENCY[resolved_key] = {
        "request_hash": request_hash,
        "result": payload_dump,
    }
    return payload_dump


def _normalize_lifecycle_state(value: Any) -> str:
    text = str(value or "").strip().lower()
    return _STRATEGY_BFF_LIFECYCLE_MAP.get(text, "draft")


def _normalize_risk_level(value: Any) -> str:
    text = str(value or "").strip().lower()
    return _STRATEGY_BFF_RISK_MAP.get(text, "medium")


def _project_strategy_dto(
    summary: Dict[str, Any],
    *,
    detail: Optional[Dict[str, Any]] = None,
    overlay: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    """Project canonical strategy_spec data into execute-plans Strategy DTO."""
    strategy_id = str(summary.get("strategy_id") or summary.get("id") or "")
    title = summary.get("title") or summary.get("name") or strategy_id
    lifecycle_raw = (detail or summary).get("lifecycle_state") or summary.get("lifecycle_state")
    governance = (detail or {}).get("governance") if detail else {}
    governance = governance if isinstance(governance, dict) else {}
    market_scope = (detail or {}).get("market_scope") if detail else {}
    market_scope = market_scope if isinstance(market_scope, dict) else {}
    execution_profile = (detail or {}).get("execution_profile") if detail else {}
    execution_profile = execution_profile if isinstance(execution_profile, dict) else {}
    persona_ids: List[str] = []
    if detail and isinstance(detail.get("persona_ids"), list):
        persona_ids = [str(p) for p in detail.get("persona_ids") or [] if str(p).strip()]
    capital_pool_id = str(
        execution_profile.get("capital_pool_id")
        or governance.get("capital_pool_id")
        or summary.get("capital_pool_id")
        or ""
    )
    alpha = str(
        market_scope.get("alpha")
        or summary.get("source_kind")
        or summary.get("hypothesis_excerpt")
        or ""
    )
    allowed = (detail or {}).get("allowedActions") or {}
    available_actions: List[str] = []
    if isinstance(allowed, dict):
        available_actions = sorted([k for k, v in allowed.items() if v])
    dto: Dict[str, Any] = {
        "id": strategy_id,
        "name": title,
        "owner": summary.get("owner") or governance.get("owner") or "pantheon-bff",
        "updatedAt": summary.get("last_modified_at")
        or summary.get("updated_at")
        or (detail or {}).get("created_at")
        or utc_now(),
        "state": _normalize_lifecycle_state(lifecycle_raw),
        "risk": _normalize_risk_level(governance.get("risk_level")),
        "alpha": alpha,
        "capitalPoolId": capital_pool_id,
        "personaIds": persona_ids,
        "pnl30d": 0.0,
        "sharpe": 0.0,
        "drawdown": 0.0,
        "availableActions": available_actions,
        "labelKey": f"strategy.{strategy_id}" if strategy_id else None,
        "lifecycleStatus": str(lifecycle_raw or ""),
    }
    if overlay:
        for k, v in overlay.items():
            if v is not None:
                dto[k] = v
    return dto


def _deployment_url(path: str) -> str:
    base = os.getenv("PANTHEON_DEPLOYMENT_API_URL", "").strip().rstrip("/")
    if not base:
        base = "http://deployment:8095"
    return f"{base}{path}"


def _checkpoint_persona_provisioning_readback(
    *,
    persona_id: str,
    metadata: Dict[str, Any],
    state: str,
    runtime_binding_id: str,
    runtime_id: str,
    authoritative_readback: Optional[Mapping[str, Any]] = None,
    failure_reason: Optional[str] = None,
) -> Dict[str, Any]:
    """Persist one terminal decision and return its durable replay outcome."""
    tenant_id = str(metadata.get("tenant_id") or "").strip()
    idempotency_key = str(metadata.get("provisioning_idempotency_key") or "").strip()
    if not tenant_id or not idempotency_key:
        return {"committed": False, "ledger_state": None}
    lease_owner = f"persona-readback:{uuid.uuid4().hex}"
    store = None
    record = None
    try:
        store = _persona_provisioning_store()
        record = store.acquire(
            tenant_id,
            idempotency_key,
            lease_owner=lease_owner,
            lease_seconds=max(
                60,
                int(os.getenv("PANTHEON_PERSONA_PROVISIONING_LEASE_SECONDS", "180")),
            ),
        )
        if record is None:
            return {"committed": False, "ledger_state": None}
        desired_terminal_state = {
            "paper_running": "succeeded",
            "provisioning_failed": "failed",
        }.get(state)
        if desired_terminal_state is None:
            store.release(record, lease_owner=lease_owner)
            return {"committed": False, "ledger_state": None}
        if record.state in {"succeeded", "failed", "compensated"}:
            compatible = record.state == desired_terminal_state or (
                desired_terminal_state == "failed" and record.state == "compensated"
            )
            schedule_cleanup = None
            cleanup_error = None
            if record.state in {"failed", "compensated"}:
                try:
                    schedule_cleanup = _remove_persona_cron_required(persona_id)
                    record.references["first_evaluation_schedule_cleanup"] = deepcopy(
                        schedule_cleanup
                    )
                except Exception as exc:
                    cleanup_error = str(exc) or exc.__class__.__name__
                    record.references["first_evaluation_schedule_cleanup"] = {
                        "status": "pending",
                        "registered": None,
                        "terminal_reason": cleanup_error,
                    }
            # A terminal ledger release is atomic, so its references and
            # compensation already belong to that decision.  Preserve them
            # verbatim on replay; in particular, never turn a compensated
            # record back into failed or reverse an earlier outcome.
            store.release(record, lease_owner=lease_owner)
            return {
                "committed": compatible,
                "ledger_state": record.state,
                "terminal_replay": True,
                "failure_reason": str(
                    (record.error or {}).get("terminal_reason")
                    or (record.error or {}).get("reason")
                    or ""
                ),
                "schedule_cleanup": deepcopy(schedule_cleanup),
                "schedule_cleanup_error": cleanup_error,
                "references": deepcopy(record.references),
                "result": deepcopy(record.result),
            }
        if runtime_binding_id:
            record.references["runtime_binding_id"] = runtime_binding_id
        if runtime_id:
            record.references["runtime_id"] = runtime_id
        if state == "paper_running":
            if not isinstance(authoritative_readback, Mapping):
                store.release(record, lease_owner=lease_owner)
                return {"committed": False, "ledger_state": record.state}
            record.references["authoritative_readback"] = deepcopy(
                dict(authoritative_readback)
            )
        schedule_cleanup = None
        cleanup_error = None
        if state == "provisioning_failed":
            # Destructive cleanup happens while the terminal ledger lease is
            # held.  A concurrent success decision therefore cannot race with
            # removal of the schedule it just proved authoritative.  Cleanup
            # unavailability must not erase the durable terminal decision:
            # persist a retryable cleanup receipt and let later controller
            # passes finish the fail-closed removal.
            try:
                schedule_cleanup = _remove_persona_cron_required(persona_id)
                record.references["first_evaluation_schedule_cleanup"] = deepcopy(
                    schedule_cleanup
                )
            except Exception as exc:
                cleanup_error = str(exc) or exc.__class__.__name__
                record.references["first_evaluation_schedule_cleanup"] = {
                    "status": "pending",
                    "registered": None,
                    "terminal_reason": cleanup_error,
                }
        if state == "paper_running":
            record.state = "succeeded"
            record.current_step = "authoritative_readback_complete"
            record.error = None
            record.result = {
                "status": "paper_running",
                "paper_running": True,
                "authoritative_readback": deepcopy(dict(authoritative_readback or {})),
                "recorded_at": utc_now(),
            }
        elif state == "provisioning_failed":
            record.state = "failed"
            record.current_step = "authoritative_readback_failed"
            record.error = {
                "code": "PERSONA_PROVISIONING_READBACK_FAILED",
                "reason": failure_reason or "authoritative_readback_failed",
                "failed_step": "authoritative_readback",
                "terminal_reason": failure_reason or "authoritative_readback_failed",
                "terminal": True,
                "failed_at": utc_now(),
                "recorded_at": utc_now(),
            }
            record.result = {
                "status": "provisioning_failed",
                "paper_running": False,
                "failure_reason": failure_reason or "authoritative_readback_failed",
                "recorded_at": utc_now(),
            }
        released = store.release(record, lease_owner=lease_owner)
        committed = bool(
            released.state == record.state and released.current_step == record.current_step
        )
        return {
            "committed": committed,
            "ledger_state": released.state,
            "terminal_replay": False,
            "schedule_cleanup": deepcopy(schedule_cleanup),
            "schedule_cleanup_error": cleanup_error,
            "references": deepcopy(released.references),
            "result": deepcopy(released.result),
        }
    except Exception as exc:
        # Owner lifecycle remains fail-closed; inability to persist the mirror
        # is logged and never turns missing readback into success.
        log.warning("Failed to checkpoint Persona provisioning readback: %s", exc)
        if store is not None and record is not None:
            try:
                store.release(record, lease_owner=lease_owner)
            except Exception:
                pass
        return {
            "committed": False,
            "ledger_state": None,
            "terminal_replay": False,
            "error": str(exc) or exc.__class__.__name__,
        }


def _append_persona_reconcile_diagnostic(
    diagnostics: Optional[List[str]],
    dependency: str,
) -> None:
    if diagnostics is not None and dependency not in diagnostics:
        diagnostics.append(dependency)


def _materialize_terminal_persona_provisioning_ledger(
    persona_id: str,
    raw: Dict[str, Any],
    *,
    diagnostics: Optional[List[str]] = None,
) -> Optional[str]:
    """Replay a durable terminal decision before consulting mutable owners.

    The ledger release and Persona projection are separate durable writes.  A
    process crash between them must not leave the Persona in ``provisioning``
    or allow newer owner observations to reverse the released decision.
    ``None`` means the ledger is not terminal; a returned lifecycle is final
    for this controller pass.
    """

    metadata = raw.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    tenant_id = str(metadata.get("tenant_id") or "").strip()
    idempotency_key = str(metadata.get("provisioning_idempotency_key") or "").strip()
    if not tenant_id or not idempotency_key:
        return None
    try:
        record = _persona_provisioning_store().get(tenant_id, idempotency_key)
    except Exception as exc:
        log.warning("Failed to read Persona provisioning ledger for %s: %s", persona_id, exc)
        _append_persona_reconcile_diagnostic(diagnostics, "provisioning_ledger")
        return None
    if record is None or record.state not in {"succeeded", "failed", "compensated"}:
        return None

    references = record.references if isinstance(record.references, dict) else {}
    desired_state = (
        "paper_running" if record.state == "succeeded" else "provisioning_failed"
    )
    checkpoint = _checkpoint_persona_provisioning_readback(
        persona_id=persona_id,
        metadata=metadata,
        state=desired_state,
        runtime_binding_id=str(references.get("runtime_binding_id") or "").strip(),
        runtime_id=str(references.get("runtime_id") or "").strip(),
        authoritative_readback=(
            references.get("authoritative_readback")
            if isinstance(references.get("authoritative_readback"), Mapping)
            else None
        ),
        failure_reason=str(
            (record.error or {}).get("terminal_reason")
            or (record.error or {}).get("reason")
            or "durable_ledger_terminal_failure"
        ),
    )
    if not checkpoint.get("committed"):
        _append_persona_reconcile_diagnostic(diagnostics, "provisioning_ledger")
        return "provisioning"

    ledger_state = str(checkpoint.get("ledger_state") or "")
    durable_references = checkpoint.get("references")
    durable_references = (
        durable_references if isinstance(durable_references, Mapping) else {}
    )
    metadata_updates: Dict[str, Any] = {}
    runtime_binding_id = str(
        durable_references.get("runtime_binding_id") or ""
    ).strip()
    runtime_id = str(durable_references.get("runtime_id") or "").strip()

    if ledger_state == "succeeded":
        durable_readback = durable_references.get("authoritative_readback")
        durable_result = checkpoint.get("result")
        if (
            not runtime_binding_id
            or not runtime_id
            or not isinstance(durable_readback, Mapping)
            or not isinstance(durable_result, Mapping)
            or durable_result.get("paper_running") is not True
            or durable_result.get("status") != "paper_running"
        ):
            _append_persona_reconcile_diagnostic(diagnostics, "provisioning_ledger")
            return "provisioning"
        new_state = "paper_running"
        metadata_updates.update(
            {
                "paper_runtime_state": "running",
                "runtime_binding_id": runtime_binding_id,
                "runtime_id": runtime_id,
                "provisioning_authoritative_readback": deepcopy(
                    dict(durable_readback)
                ),
            }
        )
    elif ledger_state in {"failed", "compensated"}:
        new_state = "provisioning_failed"
        metadata_updates["provisioning_failure_reason"] = (
            checkpoint.get("failure_reason") or "durable_ledger_terminal_failure"
        )
        schedule_cleanup = checkpoint.get("schedule_cleanup")
        if isinstance(schedule_cleanup, Mapping):
            metadata_updates["first_evaluation_schedule_cleanup"] = deepcopy(
                dict(schedule_cleanup)
            )
        elif checkpoint.get("schedule_cleanup_error"):
            _append_persona_reconcile_diagnostic(diagnostics, "persona_cron")
            metadata_updates["first_evaluation_schedule_cleanup"] = {
                "status": "pending",
                "registered": None,
                "terminal_reason": checkpoint["schedule_cleanup_error"],
            }
        compensation = _reconcile_persona_provisioning_compensation(
            {**metadata, **metadata_updates}
        )
        if compensation is not None:
            metadata_updates["provisioning_compensation"] = compensation
            if compensation.get("status") in {"failed", "pending"}:
                _append_persona_reconcile_diagnostic(
                    diagnostics, "provisioning_compensation"
                )
    else:
        _append_persona_reconcile_diagnostic(diagnostics, "provisioning_ledger")
        return "provisioning"

    read_store.update_persona(
        persona_id,
        lifecycle_state=new_state,
        metadata=metadata_updates,
    )
    if persona_id in _PERSONA_BFF_OVERLAY:
        _PERSONA_BFF_OVERLAY[persona_id]["state"] = _normalize_lifecycle_state(new_state)
        _PERSONA_BFF_OVERLAY[persona_id]["lifecycleStatus"] = new_state
        if runtime_binding_id:
            _PERSONA_BFF_OVERLAY[persona_id]["runtimeBindingId"] = runtime_binding_id
        if runtime_id:
            _PERSONA_BFF_OVERLAY[persona_id]["runtimeId"] = runtime_id
    raw["lifecycle_state"] = new_state
    raw["status"] = new_state
    raw.setdefault("metadata", {}).update(metadata_updates)
    raw["metadata"]["lifecycle_state"] = new_state
    return new_state


def _reconcile_persona_provisioning_compensation(
    metadata: Mapping[str, Any],
) -> Optional[Dict[str, Any]]:
    """Resume fail-closed Deployment/Capital compensation from durable state."""

    tenant_id = str(metadata.get("tenant_id") or "").strip()
    idempotency_key = str(metadata.get("provisioning_idempotency_key") or "").strip()
    if not tenant_id or not idempotency_key:
        return None
    store = _persona_provisioning_store()
    record = store.get(tenant_id, idempotency_key)
    if record is None:
        return None
    coordinator = PersonaProvisioningCoordinator(
        store=store,
        transport=_PersonaOwnerHttpTransport(),
        schedule_registrar=_register_persona_cron_required,
        lease_owner=f"persona-compensation:{uuid.uuid4().hex}",
        lease_seconds=max(
            30,
            int(os.getenv("PANTHEON_PERSONA_PROVISIONING_LEASE_SECONDS", "180")),
        ),
    )
    try:
        reconciled = coordinator.reconcile_failure_compensation(record)
    except Exception as exc:
        log.warning("Failed to reconcile Persona provisioning compensation: %s", exc)
        return {
            "status": "pending",
            "terminal_reason": str(exc) or exc.__class__.__name__,
        }
    return {
        "ledger_state": reconciled.state,
        "current_step": reconciled.current_step,
        **deepcopy(reconciled.compensation or {"status": "not_required"}),
    }


def _evaluate_persona_provisioning_status(
    persona_id: str,
    raw: Dict[str, Any],
    *,
    all_bindings: Optional[Dict[str, Dict[str, Any]]] = None,
    all_cron_registrations: Optional[Set[Tuple[str, str]]] = None,
    all_monitoring_sessions: Optional[List[Dict[str, Any]]] = None,
    diagnostics: Optional[List[str]] = None,
) -> str:
    metadata = raw.get("metadata") or {}
    current_state = raw.get("lifecycle_state") or raw.get("state")
    if current_state == "provisioning_failed":
        terminal_updates: Dict[str, Any] = {}
        try:
            schedule_cleanup = _remove_persona_cron_required(persona_id)
            terminal_updates["first_evaluation_schedule_cleanup"] = schedule_cleanup
        except Exception as exc:
            log.warning(
                "Failed to reconcile terminal first-evaluation cleanup for %s: %s",
                persona_id,
                exc,
            )
            terminal_updates["first_evaluation_schedule_cleanup"] = {
                "status": "pending",
                "registered": None,
                "terminal_reason": str(exc) or exc.__class__.__name__,
            }
            _append_persona_reconcile_diagnostic(diagnostics, "persona_cron")
        compensation = _reconcile_persona_provisioning_compensation(metadata)
        if compensation is not None:
            terminal_updates["provisioning_compensation"] = compensation
        changed_updates = {
            key: value
            for key, value in terminal_updates.items()
            if metadata.get(key) != value
        }
        if changed_updates:
            read_store.update_persona(
                persona_id,
                lifecycle_state="provisioning_failed",
                metadata=changed_updates,
            )
            raw.setdefault("metadata", {}).update(changed_updates)
        return "provisioning_failed"
    if current_state not in ("provisioning", "draft", "paper_running"):
        return str(current_state or "")
    if current_state == "paper_running":
        return "paper_running"
    if current_state != "provisioning":
        return str(current_state or "")

    terminal_replay = _materialize_terminal_persona_provisioning_ledger(
        persona_id,
        raw,
        diagnostics=diagnostics,
    )
    if terminal_replay is not None:
        return terminal_replay

    # Deployment owns admission and the runtime identity.  Never infer a
    # RuntimeBinding id from the distinct PersonaCapitalBinding id.
    persona_capital_binding_id = str(
        metadata.get("persona_capital_binding_id") or metadata.get("binding_id") or ""
    ).strip()
    tenant_id = str(metadata.get("tenant_id") or "").strip()
    capital_pool_id = str(
        metadata.get("internal_paper_capital_pool_id")
        or metadata.get("legacy_paper_capital_pool_id")
        or ""
    ).strip()
    plan_id = str(metadata.get("deployment_plan_id") or "").strip()
    expected_saga_id = str(metadata.get("deployment_saga_id") or "").strip()
    binding_id = str(metadata.get("runtime_binding_id") or "").strip()
    runtime_id = str(metadata.get("runtime_id") or "").strip()
    projection: Dict[str, Any] = {}
    projection_failed = False
    if plan_id:
        try:
            candidate = _get_json(
                _deployment_url(f"/api/deployment/plans/{quote(plan_id, safe='')}/projection")
            )
            projection = candidate if isinstance(candidate, dict) else {}
        except Exception as exc:
            log.warning("Failed to query Deployment projection %s for %s: %s", plan_id, persona_id, exc)
            _append_persona_reconcile_diagnostic(diagnostics, "deployment")

    projection_saga = projection.get("deployment_saga")
    projection_saga = projection_saga if isinstance(projection_saga, dict) else {}
    projected_saga_id = str(
        projection.get("deployment_saga_id") or projection_saga.get("saga_id") or ""
    ).strip()
    projected_plan_id = str(projection.get("plan_id") or "").strip()
    projection_observed = bool(
        projection
        and projected_plan_id == plan_id
        and projected_saga_id
        and (not expected_saga_id or projected_saga_id == expected_saga_id)
    )
    projection_identity_failed = bool(projection) and bool(
        (projected_plan_id and projected_plan_id != plan_id)
        or (
            projected_saga_id
            and expected_saga_id
            and projected_saga_id != expected_saga_id
        )
    )

    saga_status = str(
        projection.get("deployment_saga_status")
        or projection_saga.get("status")
        or ""
    ).strip().lower()
    saga_progress = projection.get("deployment_saga_progress")
    saga_progress = saga_progress if isinstance(saga_progress, dict) else {}
    progress_status = str(saga_progress.get("progress_status") or "").strip().lower()
    projection_complete = (
        saga_status == "completed" and progress_status == "completed"
    )
    projection_failed = saga_status in {
        "failed",
        "aborted",
        "compensating",
        "compensated",
    } or progress_status in {
        "failed",
        "blocked",
        "compensating",
    }

    # Deployment projection proves saga admission, but Runtime Manager is the
    # sole RuntimeBinding authority. Embedded projection/file snapshots never
    # satisfy lifecycle readback.
    projected_binding = projection.get("runtime_binding")
    projected_binding = projected_binding if isinstance(projected_binding, dict) else {}
    projected_binding_id = str(
        projection.get("runtime_binding_id")
        or projected_binding.get("binding_id")
        or ""
    ).strip()
    projected_runtime_id = str(
        projection.get("runtime_id") or projected_binding.get("runtime_id") or ""
    ).strip()

    binding: Optional[Dict[str, Any]] = None
    binding_ok = False
    binding_failed = False
    authoritative_bindings: List[Dict[str, Any]] = []
    if plan_id:
        try:
            if all_bindings is not None:
                authoritative_bindings = [
                    value
                    for value in all_bindings.values()
                    if isinstance(value, dict)
                    and str(value.get("plan_id") or "") == plan_id
                ]
            else:
                client = _runtime_manager_client()
                authoritative_bindings = [
                    value
                    for value in client.list_by_plan(plan_id)
                    if isinstance(value, dict)
                ]
            active_bindings = [
                value
                for value in authoritative_bindings
                if str(value.get("state") or value.get("status") or "").lower()
                in {"active", "running", "ok"}
            ]
            if len(active_bindings) == 1:
                binding = active_bindings[0]
                authoritative_binding_id = str(
                    binding.get("binding_id") or binding.get("id") or ""
                ).strip()
                authoritative_runtime_id = str(binding.get("runtime_id") or "").strip()
                binding_metadata = binding.get("metadata")
                binding_metadata = binding_metadata if isinstance(binding_metadata, dict) else {}
                identity_matches = all((
                    bool(authoritative_binding_id),
                    authoritative_binding_id.startswith("rb-"),
                    bool(authoritative_runtime_id),
                    str(binding.get("plan_id") or "") == plan_id,
                    str(binding.get("persona_capital_binding_id") or "")
                    == persona_capital_binding_id,
                    str(binding.get("capital_pool_id") or "") == capital_pool_id,
                    str(
                        binding.get("deployment_mode")
                        or binding.get("deployment_stage")
                        or ""
                    ) == "paper",
                    str(binding_metadata.get("persona_id") or "") == persona_id,
                    str(binding_metadata.get("tenant_id") or "") == tenant_id,
                    not binding_id or binding_id == authoritative_binding_id,
                    not runtime_id or runtime_id == authoritative_runtime_id,
                    not projected_binding_id
                    or projected_binding_id == authoritative_binding_id,
                    not projected_runtime_id
                    or projected_runtime_id == authoritative_runtime_id,
                ))
                if identity_matches:
                    binding_id = authoritative_binding_id
                    runtime_id = authoritative_runtime_id
                    binding_ok = True
                else:
                    binding_failed = True
            elif len(active_bindings) > 1:
                binding_failed = True
            elif binding_id and any(
                str(value.get("binding_id") or value.get("id") or "") == binding_id
                for value in (all_bindings or {}).values()
                if isinstance(value, dict)
            ):
                # The expected binding identity exists under another plan.
                binding_failed = True
            elif any(
                str(value.get("state") or value.get("status") or "").lower()
                in {"failed", "stopped", "error"}
                for value in authoritative_bindings
            ):
                binding_failed = True
        except Exception as exc:
            log.warning(
                "Failed to query RuntimeBindings for plan %s / %s: %s",
                plan_id,
                persona_id,
                exc,
            )
            _append_persona_reconcile_diagnostic(diagnostics, "runtime_manager")

    # Require exactly one fresh, active worker joined on the complete identity.
    monitoring_sessions: List[Dict[str, Any]] = []
    worker_identity_conflict = False
    if binding_ok and runtime_id and binding_id:
        try:
            owner_sessions = (
                all_monitoring_sessions
                if all_monitoring_sessions is not None
                else read_store.list_authoritative_paper_runtime_monitoring_sessions()
            )
        except Exception as exc:
            log.warning(
                "Failed to query paper worker sessions for %s: %s",
                persona_id,
                exc,
            )
            _append_persona_reconcile_diagnostic(diagnostics, "paper_runtime_manager")
            owner_sessions = []
        for s in owner_sessions:
            # The paper-fleet reconciler owns worker sessions and joins them to
            # RuntimeBinding by runtime_id + binding_id.  It does not duplicate
            # Persona identity into the session.  Persona identity is instead
            # proven above from the authoritative RuntimeBinding metadata.  If
            # a future session does carry persona_id, treat a conflicting value
            # as fail-closed rather than ignoring it.
            s_pid = str(s.get("persona_id") or "").strip()
            s_rtid = str(s.get("runtime_id") or "").strip()
            s_bid = str(s.get("binding_id") or s.get("runtime_binding_id") or "").strip()
            s_pool_id = str(s.get("capital_pool_id") or "").strip()
            if s_rtid == runtime_id and s_bid == binding_id:
                if (s_pid and s_pid != persona_id) or s_pool_id != capital_pool_id:
                    worker_identity_conflict = True
                else:
                    monitoring_sessions.append(s)

    max_heartbeat_age = max(
        1,
        int(os.getenv("PANTHEON_PERSONA_HEARTBEAT_MAX_AGE_SECONDS", "90")),
    )
    now_dt = datetime.now(timezone.utc)
    live_sessions: List[Dict[str, Any]] = []
    startup_sessions: List[Dict[str, Any]] = []
    current_owner_sessions: List[Dict[str, Any]] = []
    for session in monitoring_sessions:
        status = str(session.get("status") or "").strip().lower()
        staleness = session.get("staleness")
        stale_marker = bool(
            isinstance(staleness, Mapping)
            and (
                str(staleness.get("status") or "").strip().lower() == "stale"
                or staleness.get("reason")
            )
        )
        heartbeat_at = _parse_rfc3339(session.get("last_heartbeat_at"))
        fresh = bool(
            heartbeat_at is not None
            and 0 <= (now_dt - heartbeat_at).total_seconds() <= max_heartbeat_age
        )
        session_id = str(session.get("session_id") or session.get("id") or "").strip()
        current_owner = (
            session_id
            and session.get("active") is not False
            and session.get("ended_at") in (None, "")
            and status not in {"failed", "ended", "error", "stale"}
            and not stale_marker
        )
        if current_owner:
            current_owner_sessions.append(session)
        startup_status = status in {
            "accepted",
            "initializing",
            "pending",
            "queued",
            "starting",
        }
        if (
            current_owner
            and (status == "running" or startup_status)
            and session.get("last_heartbeat_at") in (None, "")
        ):
            startup_sessions.append(session)
        if (
            session_id
            and status == "running"
            and session.get("active") is not False
            and session.get("ended_at") in (None, "")
            and fresh
            and not stale_marker
        ):
            live_sessions.append(session)
    heartbeat_ok = len(live_sessions) == 1
    # Historical ended/stale sessions are expected after worker replacement.
    # They cannot poison one unique fresh owner session.  No fresh successor
    # or multiple current workers is fail-closed once an owner record exists.
    # One exact running owner may briefly precede its first heartbeat; keep
    # that startup race pending and let the provisioning timeout decide if the
    # worker never becomes authoritative.
    startup_pending = (
        len(startup_sessions) == 1 and len(current_owner_sessions) == 1
    )
    heartbeat_failed = worker_identity_conflict or (
        bool(monitoring_sessions) and not heartbeat_ok and not startup_pending
    )

    # The schedule authority must contain the exact first-evaluation workflow.
    cron_ok = False
    authoritative_schedule_readback: Optional[Dict[str, Any]] = None
    try:
        schedule_discovered = all_cron_registrations is None or (
                persona_id,
                _PERSONA_FIRST_EVALUATION_WORKFLOW_ID,
            ) in all_cron_registrations
        if schedule_discovered:
            if (
                projection_observed
                and projection_complete
                and binding_ok
                and runtime_id
                and binding_id
                and capital_pool_id
                and persona_capital_binding_id
            ):
                schedule_receipt = _register_persona_cron_required(
                    persona_id,
                    capital_pool_id,
                    persona_capital_binding_id,
                    runtime_id=runtime_id,
                    runtime_binding_id=binding_id,
                )
                authoritative = schedule_receipt.get("authoritative_readback")
                cron_ok = bool(
                    isinstance(authoritative, dict)
                    and authoritative.get("registered") is True
                    and authoritative.get("persona_id") == persona_id
                    and authoritative.get("workflow_id")
                    == _PERSONA_FIRST_EVALUATION_WORKFLOW_ID
                    and authoritative.get("runtime_id") == runtime_id
                    and authoritative.get("runtime_binding_id") == binding_id
                    and authoritative.get("capital_pool_id") == capital_pool_id
                    and authoritative.get("persona_capital_binding_id")
                    == persona_capital_binding_id
                    and isinstance(authoritative.get("job_id"), str)
                    and bool(authoritative["job_id"].strip())
                    and authoritative.get("request_id")
                    == (
                        f"persona-provisioning:{persona_id}:"
                        f"{_PERSONA_FIRST_EVALUATION_WORKFLOW_ID}"
                    )
                )
                if cron_ok:
                    authoritative_schedule_readback = deepcopy(authoritative)
    except Exception as exc:
        log.warning("Failed to query first-evaluation schedule for %s: %s", persona_id, exc)
        _append_persona_reconcile_diagnostic(diagnostics, "persona_cron")

    # A timed-out attempt is terminal even if stale evidence happens to appear
    # later; recovery must be an explicit retry that acquires the durable lease.
    is_timeout = False
    readback_started_at = metadata.get("provisioning_readback_started_at")
    if readback_started_at:
        try:
            started_at_dt = _parse_rfc3339(readback_started_at)
            timeout_seconds = max(
                1,
                int(os.getenv("PANTHEON_PERSONA_PROVISIONING_TIMEOUT_SECONDS", "600")),
            )
            is_timeout = bool(
                started_at_dt is not None
                and (now_dt - started_at_dt).total_seconds() > timeout_seconds
            )
        except (TypeError, ValueError):
            is_timeout = False

    if (
        projection_failed
        or projection_identity_failed
        or binding_failed
        or heartbeat_failed
        or is_timeout
    ):
        new_state = "provisioning_failed"
    elif (
        projection_observed
        and projection_complete
        and binding_ok
        and heartbeat_ok
        and cron_ok
    ):
        new_state = "paper_running"
    else:
        new_state = "provisioning"

    metadata_updates: Dict[str, Any] = {}
    if binding_ok and binding_id:
        metadata_updates["runtime_binding_id"] = binding_id
    if binding_ok and runtime_id:
        metadata_updates["runtime_id"] = runtime_id
    if new_state == "provisioning_failed":
        failure_reasons = []
        if projection_failed:
            failure_reasons.append("deployment_saga_failed")
        if projection_identity_failed:
            failure_reasons.append("deployment_projection_identity_mismatched")
        if binding_failed:
            failure_reasons.append("runtime_binding_failed_or_mismatched")
        if heartbeat_failed:
            failure_reasons.append("paper_worker_failed_stale_or_duplicated")
        if is_timeout:
            failure_reasons.append("provisioning_timeout")
        metadata_updates["provisioning_failure_reason"] = ",".join(failure_reasons)
    elif new_state == "paper_running":
        metadata_updates["paper_runtime_state"] = "running"
        metadata_updates.pop("provisioning_failure_reason", None)

    # The durable ledger is the release barrier for terminal Persona state.
    # If its lease is busy or storage is unavailable, leave the Persona in
    # provisioning so a later controller pass can recover with RPO=0.
    if new_state in {"paper_running", "provisioning_failed"}:
        authoritative_readback: Optional[Dict[str, Any]] = None
        if new_state == "paper_running":
            if (
                not isinstance(binding, Mapping)
                or len(live_sessions) != 1
                or authoritative_schedule_readback is None
            ):
                return "provisioning"
            authoritative_readback = {
                "observed_at": utc_now(),
                "deployment": {
                    "plan_id": plan_id,
                    "saga_id": projected_saga_id,
                    "saga_status": saga_status,
                    "progress_status": progress_status,
                },
                "runtime_binding": deepcopy(dict(binding)),
                "paper_worker": deepcopy(live_sessions[0]),
                "first_evaluation_schedule": deepcopy(
                    authoritative_schedule_readback
                ),
            }
        terminal_checkpoint = _checkpoint_persona_provisioning_readback(
            persona_id=persona_id,
            metadata={**metadata, **metadata_updates},
            state=new_state,
            runtime_binding_id=binding_id,
            runtime_id=runtime_id,
            authoritative_readback=authoritative_readback,
            failure_reason=metadata_updates.get("provisioning_failure_reason"),
        )
        ledger_state = terminal_checkpoint.get("ledger_state")
        if terminal_checkpoint.get("terminal_replay"):
            # The ledger release is the durable lifecycle decision.  A crash
            # between that release and Persona projection must recover the
            # earlier terminal state, never remain stuck in provisioning or
            # reverse the decision from newer observations.
            if ledger_state == "succeeded":
                durable_references = terminal_checkpoint.get("references")
                durable_references = (
                    durable_references
                    if isinstance(durable_references, Mapping)
                    else {}
                )
                durable_readback = durable_references.get("authoritative_readback")
                durable_result = terminal_checkpoint.get("result")
                if (
                    not isinstance(durable_readback, Mapping)
                    or not isinstance(durable_result, Mapping)
                    or durable_result.get("paper_running") is not True
                    or durable_result.get("status") != "paper_running"
                ):
                    return "provisioning"
                binding_id = str(
                    durable_references.get("runtime_binding_id") or ""
                ).strip()
                runtime_id = str(
                    durable_references.get("runtime_id") or ""
                ).strip()
                if not binding_id or not runtime_id:
                    return "provisioning"
                new_state = "paper_running"
                metadata_updates["paper_runtime_state"] = "running"
                metadata_updates["runtime_binding_id"] = binding_id
                metadata_updates["runtime_id"] = runtime_id
                metadata_updates["provisioning_authoritative_readback"] = deepcopy(
                    dict(durable_readback)
                )
                metadata_updates.pop("provisioning_failure_reason", None)
            elif ledger_state in {"failed", "compensated"}:
                new_state = "provisioning_failed"
                metadata_updates["provisioning_failure_reason"] = (
                    terminal_checkpoint.get("failure_reason")
                    or "durable_ledger_terminal_failure"
                )
        elif not terminal_checkpoint.get("committed"):
            return "provisioning"
        if new_state == "paper_running":
            durable_references = terminal_checkpoint.get("references")
            durable_readback = (
                durable_references.get("authoritative_readback")
                if isinstance(durable_references, Mapping)
                else None
            )
            if not isinstance(durable_readback, Mapping):
                return "provisioning"
            metadata_updates["provisioning_authoritative_readback"] = deepcopy(
                dict(durable_readback)
            )
        schedule_cleanup = terminal_checkpoint.get("schedule_cleanup")
        if isinstance(schedule_cleanup, Mapping):
            metadata_updates["first_evaluation_schedule_cleanup"] = deepcopy(
                dict(schedule_cleanup)
            )
        elif terminal_checkpoint.get("schedule_cleanup_error"):
            _append_persona_reconcile_diagnostic(diagnostics, "persona_cron")
            metadata_updates["first_evaluation_schedule_cleanup"] = {
                "status": "pending",
                "registered": None,
                "terminal_reason": terminal_checkpoint["schedule_cleanup_error"],
            }
        if new_state == "provisioning_failed":
            compensation = _reconcile_persona_provisioning_compensation(
                {**metadata, **metadata_updates}
            )
            if compensation is not None:
                metadata_updates["provisioning_compensation"] = compensation
                if compensation.get("status") in {"failed", "pending"}:
                    _append_persona_reconcile_diagnostic(
                        diagnostics, "provisioning_compensation"
                    )

    if new_state != current_state or metadata_updates:
        read_store.update_persona(
            persona_id,
            lifecycle_state=new_state,
            metadata=metadata_updates,
        )
        if persona_id in _PERSONA_BFF_OVERLAY:
            _PERSONA_BFF_OVERLAY[persona_id]["state"] = _normalize_lifecycle_state(new_state)
            _PERSONA_BFF_OVERLAY[persona_id]["lifecycleStatus"] = new_state
            if binding_id:
                _PERSONA_BFF_OVERLAY[persona_id]["runtimeBindingId"] = binding_id
            if runtime_id:
                _PERSONA_BFF_OVERLAY[persona_id]["runtimeId"] = runtime_id
        raw["lifecycle_state"] = new_state
        raw["status"] = new_state
        raw.setdefault("metadata", {}).update(metadata_updates)
        raw["metadata"]["lifecycle_state"] = new_state

    return new_state


def _project_persona_dto(
    raw: Dict[str, Any],
    *,
    overlay: Optional[Dict[str, Any]] = None,
    routed_strategies: Optional[int] = None,
    all_bindings: Optional[Dict[str, Dict[str, Any]]] = None,
    all_cron_registrations: Optional[Set[Tuple[str, str]]] = None,
    evaluate_provisioning: bool = False,
) -> Dict[str, Any]:
    """Project canonical persona data into execute-plans Persona DTO."""
    persona_id = str(raw.get("persona_id") or raw.get("id") or "")
    if persona_id and evaluate_provisioning:
        _evaluate_persona_provisioning_status(
            persona_id,
            raw,
            all_bindings=all_bindings,
            all_cron_registrations=all_cron_registrations,
        )
    metadata = dict(raw.get("metadata") or {}) if isinstance(raw.get("metadata"), dict) else {}
    archetype = str(
        metadata.get("archetype")
        or raw.get("strategy_family")
        or raw.get("mandate")
        or "generalist"
    )
    capital_mode = str(
        metadata.get("capital_mode")
        or metadata.get("capitalMode")
        or metadata.get("deployment_stage")
        or metadata.get("deploymentStage")
        or ""
    ).strip().lower()
    if capital_mode not in {"paper", "canary", "live"}:
        capital_mode = ""
    metadata_paper_ledger = (
        metadata.get("paper_ledger")
        if isinstance(metadata.get("paper_ledger"), dict)
        else {}
    )
    paper_ledger_id = (
        str(
            metadata.get("paper_ledger_id")
            or metadata.get("paperLedgerId")
            or metadata_paper_ledger.get("id")
            or ""
        ).strip()
        or (f"paper-ledger-{persona_id}" if capital_mode == "paper" and persona_id else None)
    )
    paper_ledger = None
    if paper_ledger_id:
        paper_ledger = dict(metadata_paper_ledger)
        paper_ledger.update({
            "id": paper_ledger_id,
            "mode": paper_ledger.get("mode") or "paper",
            "persona_id": paper_ledger.get("persona_id") or persona_id,
            "is_isolated": bool(paper_ledger.get("is_isolated", True)),
            "isolated": bool(paper_ledger.get("isolated", True)),
        })
    legacy_paper_capital_pool_id = None
    if capital_mode == "paper":
        legacy_paper_capital_pool_id = (
            metadata.get("legacy_paper_capital_pool_id")
            or metadata.get("capital_pool_id")
        )
    capital_pool_id = None if capital_mode == "paper" else metadata.get("capital_pool_id")
    dto: Dict[str, Any] = {
        "id": persona_id,
        "name": raw.get("name") or persona_id,
        "owner": metadata.get("owner") or raw.get("owner") or "pantheon-bff",
        "tenantId": metadata.get("tenant_id"),
        "updatedAt": raw.get("updated_at") or raw.get("created_at") or utc_now(),
        "state": _normalize_lifecycle_state(raw.get("lifecycle_state")),
        "risk": _normalize_risk_level(metadata.get("risk_level")),
        "archetype": archetype,
        "routedStrategies": int(routed_strategies if routed_strategies is not None else 0),
        "successRate": float(metadata.get("success_rate") or 0.0),
        "labelKey": f"persona.{persona_id}" if persona_id else None,
        "lifecycleStatus": str(raw.get("lifecycle_state") or ""),
        "marketScope": list(metadata.get("market_scope") or []),
        "assetClasses": list(metadata.get("asset_classes") or []),
        "paperLedgerId": paper_ledger_id,
        "paperLedger": paper_ledger,
        "legacyPaperCapitalPoolId": legacy_paper_capital_pool_id,
        "capitalPoolId": capital_pool_id,
        "capitalMode": metadata.get("capital_mode") or capital_mode or None,
        "runtimeId": metadata.get("runtime_id") or metadata.get("runtime_binding_id"),
        "runtimeBindingId": metadata.get("runtime_binding_id"),
        "deploymentPlanId": metadata.get("deployment_plan_id"),
        "deploymentStage": metadata.get("deployment_stage"),
        "oodaStage": metadata.get("ooda_stage"),
        "currentWork": metadata.get("current_work"),
        "governanceRequired": bool(metadata.get("governance_required", True)),
        "recommendedGovernanceAction": metadata.get("recommended_governance_action"),
        "riskFlags": list(metadata.get("risk_flags") or []),
        # Real persona identity + trading-character traits (drive the OpenClaw SOUL
        # and let the FE display/edit them).
        "mandate": raw.get("mandate") or "",
        "strategyFamily": raw.get("strategy_family") or "",
        "traits": metadata.get("traits") if isinstance(metadata.get("traits"), dict) else {},
    }
    if dto.get("capitalPoolId") is None:
        dto.pop("capitalPoolId", None)
    if not dto.get("paperLedgerId"):
        dto.pop("paperLedgerId", None)
        dto.pop("paperLedger", None)
    if not dto.get("legacyPaperCapitalPoolId"):
        dto.pop("legacyPaperCapitalPoolId", None)
    for optional_runtime_field in ("runtimeId", "runtimeBindingId"):
        if not dto.get(optional_runtime_field):
            dto.pop(optional_runtime_field, None)
    required_data_sources = (
        raw.get("required_data_sources")
        if isinstance(raw.get("required_data_sources"), list)
        else []
    )
    if isinstance(metadata.get("data_source_status"), dict) or isinstance(metadata.get("data_sources"), list) or required_data_sources:
        data_source_status, data_sources, source_health_bindings = _overlay_source_health_truth(
            metadata.get("data_source_status") if isinstance(metadata.get("data_source_status"), dict) else {},
            metadata.get("data_sources") if isinstance(metadata.get("data_sources"), list) else [],
            required_data_sources=required_data_sources,
        )
        metadata["data_source_status"] = data_source_status
        metadata["data_sources"] = data_sources
        metadata["source_health_bindings"] = source_health_bindings

    for source_key, dto_key in (
        ("data_source_status", "dataSourceStatus"),
        ("data_sources", "dataSources"),
        ("data_source_refs", "dataSourceRefs"),
        ("source_health_bindings", "sourceHealthBindings"),
        ("research_status", "researchStatus"),
        ("research_refs", "researchRefs"),
        ("current_research_projects", "currentResearchProjects"),
    ):
        value = metadata.get(source_key)
        if value is not None:
            dto[dto_key] = json.loads(json.dumps(value))
    if required_data_sources:
        dto["requiredDataSources"] = json.loads(json.dumps(required_data_sources))
    performance = metadata.get("performance") if isinstance(metadata.get("performance"), dict) else {}
    if performance:
        dto["metrics"] = json.loads(json.dumps(performance))
    if overlay:
        for k, v in overlay.items():
            if v is not None:
                dto[k] = v
    return dto


def _strategy_routed_persona_count(strategy_id: str) -> int:
    detail = read_store.get_strategy_spec_detail(strategy_id, version_selector="current")
    if not detail:
        return 0
    persona_ids = detail.get("persona_ids") or []
    if not isinstance(persona_ids, list):
        return 0
    return len([p for p in persona_ids if str(p).strip()])


def _routed_strategies_for_persona(persona_id: str) -> int:
    items = read_store.list_strategy_specs(persona_id=persona_id) or []
    return len(items)


def _list_strategy_summaries() -> List[Dict[str, Any]]:
    """Combine canonical strategy_specs with overlay records created via /bff."""
    items = list(read_store.list_strategy_specs() or [])
    seen = {str(item.get("strategy_id") or "") for item in items}
    for sid, overlay in _STRATEGY_BFF_OVERLAY.items():
        if sid in seen:
            continue
        items.append({
            "strategy_id": sid,
            "title": overlay.get("name"),
            "lifecycle_state": overlay.get("state") or "draft",
            "last_modified_at": overlay.get("updatedAt"),
            "owner": overlay.get("owner"),
        })
    return items


def _list_persona_records() -> List[Dict[str, Any]]:
    """Combine canonical personas with overlay records created via /bff."""
    items = list(read_store.list_personas() or [])
    seen = {str(item.get("id") or item.get("persona_id") or "") for item in items}
    for pid, overlay in _PERSONA_BFF_OVERLAY.items():
        if pid in seen:
            continue
        items.append({
            "id": pid,
            "persona_id": pid,
            "name": overlay.get("name"),
            "lifecycle_state": overlay.get("state") or "draft",
            "updated_at": overlay.get("updatedAt"),
            "metadata": {
                "archetype": overlay.get("archetype"),
                "owner": overlay.get("owner"),
                "risk_level": overlay.get("risk"),
                "tenant_id": overlay.get("tenantId"),
            },
        })
    return items


_PERSONA_STRATEGY_MATCH_ALLOWED_ACTIONS = frozenset({
    "create_research_ticket",
    "promote_seed_candidate",
})
_PERSONA_STRATEGY_MATCH_FORBIDDEN_ACTION_TERMS = frozenset({
    "deploy",
    "deployment",
    "broker",
    "live",
    "order",
    "runtime",
    "execute",
    "execution",
})


def _load_strategy_seed_match_candidates(
    *,
    snapshot_at: str,
) -> Tuple[List[Any], Dict[str, Any]]:
    try:
        store = StrategySpecSeedStore()
        seeds = store.list_all()
        path_exists = store.path.exists()
        surface: Dict[str, Any] = {
            "status": "ok" if path_exists else "degraded",
            "source": "strategy_spec_seed_store" if path_exists else "strategy_spec_seed_store_missing",
            "path": str(store.path),
        }
        if not path_exists:
            surface["note"] = "StrategySpecSeed store file is absent; matching will use StrategySpec candidates only."
            surface["staleness"] = {"served_from": "empty_dev_store", "last_known_at": snapshot_at}
        return list(seeds), surface
    except Exception as exc:  # pragma: no cover - exercised by corrupt local stores.
        log.warning("StrategySpecSeed store unavailable for persona discovery: %s", exc)
        return [], {
            "status": "unavailable",
            "source": "strategy_spec_seed_store",
            "message": str(exc),
            "staleness": {"served_from": "unverifiable", "last_known_at": snapshot_at},
        }


def _list_strategy_spec_match_candidates(
    *,
    include_retired: bool,
    snapshot_at: str,
) -> Tuple[List[Dict[str, Any]], Dict[str, Any]]:
    items: List[Dict[str, Any]] = []
    try:
        summaries = read_store.list_strategy_specs(
            include_retired=include_retired,
            include_fixture_pack=False,
        ) or []
        for summary in summaries:
            strategy_id = str(summary.get("strategy_id") or summary.get("id") or "").strip()
            if not strategy_id:
                continue
            detail = read_store.get_strategy_spec_detail(strategy_id, version_selector="current")
            if detail:
                items.append(detail)
    except Exception as exc:  # pragma: no cover - defensive read composition.
        log.warning("StrategySpec read surface unavailable for persona discovery: %s", exc)
        return [], {
            "status": "unavailable",
            "source": read_store.dataset_source("strategy_specs"),
            "message": str(exc),
            "staleness": {"served_from": "unverifiable", "last_known_at": snapshot_at},
        }

    surface = _dataset_surface_status(
        "strategy_specs",
        snapshot_at=snapshot_at,
        has_data=read_store.dataset_source("strategy_specs") != "missing",
    )
    return items, surface


def _persona_strategy_discovery_payload(
    persona_id: str,
    *,
    include_retired: bool,
    include_blocked: bool,
    snapshot_at: str,
    discovery_session_id: Optional[str] = None,
) -> Dict[str, Any]:
    _ensure_persona_exists(persona_id)
    persona = read_store.get_persona(persona_id)
    if persona is None:
        overlay = _PERSONA_BFF_OVERLAY.get(persona_id) or {}
        persona = {
            "id": persona_id,
            "persona_id": persona_id,
            "name": overlay.get("name") or persona_id,
            "mandate": overlay.get("archetype") or overlay.get("name") or persona_id,
            "strategy_family": overlay.get("archetype"),
            "lifecycle_state": overlay.get("state") or "draft",
            "status": overlay.get("state") or "draft",
            "metadata": {
                "archetype": overlay.get("archetype"),
                "risk_level": overlay.get("risk"),
                "market_scope": overlay.get("marketScope"),
                "asset_classes": overlay.get("assetClasses"),
            },
        }
    route_policy = read_store.get_route_policy_for_persona(persona_id) or {}
    capability_snapshot = read_store.get_capability_snapshot_for_persona(persona_id) or {}
    profile = extract_persona_strategy_profile(
        persona,
        route_policy=route_policy,
        capability_snapshot=capability_snapshot,
    )
    seeds, seed_surface = _load_strategy_seed_match_candidates(snapshot_at=snapshot_at)
    strategy_specs, strategy_spec_surface = _list_strategy_spec_match_candidates(
        include_retired=include_retired,
        snapshot_at=snapshot_at,
    )
    matches = PersonaStrategyDiscoveryService().match_candidates(
        profile,
        strategy_seeds=seeds,
        strategy_specs=strategy_specs,
        created_at=snapshot_at,
        discovery_session_id=discovery_session_id,
        include_blocked=include_blocked,
    )
    match_payloads = [match.to_dict() for match in matches]
    return {
        "profile": profile.to_dict(),
        "matches": match_payloads,
        "surfaces": {
            "persona_strategy_profile": _dataset_surface_status(
                "personas",
                snapshot_at=snapshot_at,
                has_data=True,
            ),
            "strategy_spec_seeds": seed_surface,
            "strategy_specs": strategy_spec_surface,
        },
        "candidate_counts": {
            "strategy_spec_seeds": len(seeds),
            "strategy_specs": len(strategy_specs),
            "total_matches": len(match_payloads),
        },
    }


def _persona_strategy_matches_response(
    persona_id: str,
    *,
    include_retired: bool,
    include_blocked: bool,
    page_token: Optional[str],
    page_size: int,
    discovery_session_id: Optional[str] = None,
) -> Dict[str, Any]:
    snapshot_at = utc_now()
    payload = _persona_strategy_discovery_payload(
        persona_id,
        include_retired=include_retired,
        include_blocked=include_blocked,
        snapshot_at=snapshot_at,
        discovery_session_id=discovery_session_id,
    )
    matches = payload["matches"]
    page_items, next_page_token = _page_slice(matches, page_token, page_size)
    return {
        "data": page_items,
        "items": page_items,
        "profile": payload["profile"],
        "page_info": {
            "next_page_token": next_page_token,
            "page_size": page_size,
            "total": len(matches),
            "has_more": next_page_token is not None,
        },
        "meta": {
            "snapshot_at": snapshot_at,
            "surfaces": payload["surfaces"],
            "candidate_counts": payload["candidate_counts"],
            "research_only": True,
            "execution_route": "none",
        },
    }


def _strategy_discovery_page_size(value: Any) -> int:
    try:
        page_size = int(value or 20)
    except (TypeError, ValueError) as exc:
        raise _bff_error(
            422,
            ErrorCode.VALIDATION_FAILED,
            "page_size must be an integer",
            "Persona strategy discovery page_size must be an integer from 1 to 100.",
            precondition_failed="page_size",
        ) from exc
    if page_size < 1 or page_size > 100:
        raise _bff_error(
            422,
            ErrorCode.VALIDATION_FAILED,
            "page_size must be between 1 and 100",
            "Persona strategy discovery page_size must be an integer from 1 to 100.",
            precondition_failed="page_size",
        )
    return page_size


def _strategy_match_action_type(payload: Mapping[str, Any]) -> str:
    action = str(
        payload.get("action")
        or payload.get("type")
        or payload.get("recommended_action")
        or ""
    ).strip()
    if not action:
        raise _bff_error(
            422,
            ErrorCode.VALIDATION_FAILED,
            "strategy match action is required",
            "Set action to create_research_ticket or promote_seed_candidate.",
            precondition_failed="action",
        )
    normalized = action.lower().replace("-", "_")
    if (
        normalized not in _PERSONA_STRATEGY_MATCH_ALLOWED_ACTIONS
        or any(term in normalized for term in _PERSONA_STRATEGY_MATCH_FORBIDDEN_ACTION_TERMS)
    ):
        raise _bff_error(
            422,
            ErrorCode.OPERATION_NOT_ALLOWED,
            "Strategy match action cannot deploy or execute",
            (
                "Persona strategy discovery actions are limited to research ticket "
                "creation or seed-candidate promotion review."
            ),
            precondition_failed="action",
        )
    return normalized


def _find_persona_strategy_match(persona_id: str, match_id: str, *, snapshot_at: str) -> Dict[str, Any]:
    payload = _persona_strategy_discovery_payload(
        persona_id,
        include_retired=False,
        include_blocked=True,
        snapshot_at=snapshot_at,
    )
    for match in payload["matches"]:
        if str(match.get("match_id") or "") == match_id:
            return match
    raise _bff_error(
        404,
        ErrorCode.RESOURCE_NOT_FOUND,
        "Persona strategy match not found",
        f"Match {match_id} does not exist for persona {persona_id}",
    )


def _persona_strategy_match_action_response(
    *,
    persona_id: str,
    match_id: str,
    payload: Dict[str, Any],
    identity: OperatorIdentity,
    resolved_key: str,
) -> Dict[str, Any]:
    action = _strategy_match_action_type(payload)
    snapshot_at = utc_now()
    request_hash = _stable_json_hash(
        {
            "route": "POST /api/v1/personas/{persona_id}/strategy-matches/{match_id}/actions",
            "persona_id": persona_id,
            "match_id": match_id,
            "action": action,
            "payload": payload,
        }
    )
    cached = _strategy_persona_idempotency_check(resolved_key, request_hash)
    if cached is not None:
        return cached

    match = _find_persona_strategy_match(persona_id, match_id, snapshot_at=snapshot_at)
    blockers = list(((match.get("metadata") or {}).get("blockers") or []))
    if blockers and action != "create_research_ticket":
        raise _bff_error(
            422,
            ErrorCode.OPERATION_NOT_ALLOWED,
            "Blocked strategy match cannot be promoted",
            f"Hard blockers must be resolved first: {', '.join(blockers)}",
            precondition_failed="blockers",
        )
    if action == "promote_seed_candidate" and match.get("matched_object_type") != "strategy_spec_seed":
        raise _bff_error(
            422,
            ErrorCode.OPERATION_NOT_ALLOWED,
            "Only StrategySpecSeed matches can be promoted as seed candidates",
            "Use create_research_ticket for StrategySpec matches.",
            precondition_failed="matched_object_type",
        )

    if action == "create_research_ticket":
        ticket = read_store.create_research_ticket(
            title=str(payload.get("title") or f"Research persona strategy match {match_id}"),
            description=str(
                payload.get("description")
                or (
                    f"Evaluate {match.get('matched_object_type')} {match.get('matched_object_id')} "
                    f"for persona {persona_id}. Score: {match.get('score')}."
                )
            ),
            priority=str(payload.get("priority") or "normal"),
            owner=str(payload.get("owner") or persona_id),
            actor_id=identity.operator_id,
            created_at=snapshot_at,
        )
        result = {
            "data": {
                "action": action,
                "status": "research_ticket_created",
                "match_id": match_id,
                "persona_id": persona_id,
                "ticket": ticket,
                "deployment_authority": "none",
                "registry_write_performed": False,
            },
            "meta": {
                "snapshot_at": snapshot_at,
                "research_only": True,
                "execution_route": "none",
            },
        }
    else:
        promotion_request_id = f"seed-promotion-{match_id}-{uuid.uuid4().hex[:8]}"
        result = {
            "data": {
                "action": action,
                "status": "queued",
                "promotion_request_id": promotion_request_id,
                "match_id": match_id,
                "persona_id": persona_id,
                "matched_object_id": match.get("matched_object_id"),
                "registry_write_performed": False,
                "deployment_authority": "none",
                "next": "Submit the seed candidate to StrategySpec review before any deployment gate.",
            },
            "meta": {
                "snapshot_at": snapshot_at,
                "research_only": True,
                "execution_route": "none",
            },
        }
    _STRATEGY_PERSONA_BFF_IDEMPOTENCY[resolved_key] = {
        "request_hash": request_hash,
        "result": result,
    }
    return result


def _management_record_id(record: Dict[str, Any], *keys: str) -> str:
    for key in keys:
        value = record.get(key)
        if value is not None and str(value).strip():
            return str(value).strip()
    return ""


def _management_normalized_status(record: Dict[str, Any]) -> str:
    return str(record.get("status") or record.get("state") or "unknown").strip().lower() or "unknown"


def _management_as_float(value: Any) -> Optional[float]:
    if isinstance(value, bool):
        return None
    if value is None or value == "":
        return None
    try:
        return float(value)
    except (TypeError, ValueError):
        return None


def _management_first_non_empty(*values: Any) -> Any:
    for value in values:
        if value not in (None, ""):
            return value
    return None


def _management_dict_value(record: Dict[str, Any], *keys: str) -> Any:
    for key in keys:
        value = record.get(key)
        if value not in (None, ""):
            return value
    return None


def _management_nested_dict(record: Dict[str, Any], *keys: str) -> Dict[str, Any]:
    for key in keys:
        value = record.get(key)
        if isinstance(value, dict):
            return value
    return {}


def _management_position_records(telemetry: Dict[str, Any]) -> List[Dict[str, Any]]:
    for key in ("positions", "holdings", "position_snapshots"):
        raw_items = telemetry.get(key)
        if isinstance(raw_items, list):
            items = [item for item in raw_items if isinstance(item, dict)]
            if items:
                return items
    for key in ("position", "holding"):
        raw_item = telemetry.get(key)
        if isinstance(raw_item, dict):
            return [raw_item]
    return []


def _management_sum_numeric(items: List[Dict[str, Any]], field: str) -> Optional[float]:
    values = [
        value
        for value in (_management_as_float(item.get(field)) for item in items)
        if value is not None
    ]
    return round(sum(values), 6) if values else None


def _management_nested_value(record: Dict[str, Any], path: str) -> Any:
    value: Any = record
    for part in path.split("."):
        if not isinstance(value, dict):
            return None
        value = value.get(part)
    return value


def _management_first_float(record: Dict[str, Any], *paths: str) -> Optional[float]:
    for path in paths:
        value = _management_nested_value(record, path)
        number = _management_as_float(value)
        if number is not None:
            return number
    return None


def _management_sum_first_float(records: List[Dict[str, Any]], *paths: str) -> Optional[float]:
    values = [
        value
        for record in records
        for value in [_management_first_float(record, *paths)]
        if value is not None
    ]
    return round(sum(values), 6) if values else None


def _management_exposure_payload(
    *,
    pool: Dict[str, Any],
    pool_bindings: List[Dict[str, Any]],
    pool_plans: List[Dict[str, Any]],
    pool_runtimes: List[Dict[str, Any]],
) -> Dict[str, Any]:
    risk_budget = _management_first_float(
        pool,
        "risk_budget",
        "risk_budget_amount",
        "budget",
        "capital_allocation",
        "allocation_limit",
        "max_target_size",
        "params.risk_budget",
        "params.budget",
        "limits.risk_budget",
        "risk.budget",
    )
    max_drawdown_pct = _management_first_float(
        pool,
        "max_drawdown_pct",
        "risk.max_drawdown_pct",
        "limits.max_drawdown_pct",
        "params.max_drawdown_pct",
    )

    direct_exposure = _management_first_float(
        pool,
        "current_exposure",
        "current_exposure_amount",
        "exposure",
        "exposure_amount",
        "used_capital",
        "used_budget",
        "deployed_capital",
        "capital_deployed",
        "metrics.exposure",
        "summary.exposure",
        "params.exposure",
    )
    plan_exposure = _management_sum_first_float(
        pool_plans,
        "target_size",
        "targetSize",
        "target_notional",
        "notional",
        "requested_capital",
        "capital_allocation",
        "params.target_size",
        "params.notional",
    )
    runtime_exposure = _management_sum_first_float(
        pool_runtimes,
        "current_exposure",
        "exposure",
        "notional",
        "allocated_capital",
        "capital_allocation",
        "metrics.exposure",
        "summary.exposure",
    )
    binding_exposure = _management_sum_first_float(
        pool_bindings,
        "budget",
        "risk_budget",
        "allocation",
        "allocated_capital",
        "capital_allocation",
    )

    current_exposure = direct_exposure
    exposure_source = "capital_pool"
    if current_exposure is None:
        current_exposure = plan_exposure
        exposure_source = "deployment_plans"
    if current_exposure is None:
        current_exposure = runtime_exposure
        exposure_source = "runtime_bindings"
    if current_exposure is None:
        current_exposure = binding_exposure
        exposure_source = "persona_bindings"
    if current_exposure is None:
        exposure_source = "unavailable"

    utilization = None
    if current_exposure is not None and risk_budget not in (None, 0):
        utilization = round(current_exposure / risk_budget, 6)

    return {
        "risk_budget": risk_budget,
        "max_drawdown_pct": max_drawdown_pct,
        "current_exposure": current_exposure,
        "risk_budget_utilization": utilization,
        "exposure": {
            "amount": current_exposure,
            "risk_budget": risk_budget,
            "risk_budget_utilization": utilization,
            "source": exposure_source,
        },
        "risk": {
            "policy_ref": pool.get("risk_policy_ref"),
            "budget": risk_budget,
            "max_drawdown_pct": max_drawdown_pct,
        },
    }


def _management_latest_timestamp(items: List[Dict[str, Any]], *fields: str) -> Optional[str]:
    latest: Optional[str] = None
    for item in items:
        for field in fields:
            value = str(item.get(field) or "").strip()
            if value and (latest is None or value > latest):
                latest = value
    return latest


def _management_telemetry_rollup(records: List[Dict[str, Any]]) -> Dict[str, Any]:
    if not records:
        return {
            "runtime_count": 0,
            "total_pnl": None,
            "max_drawdown": None,
            "average_fill_rate": None,
            "total_trades": 0,
            "latest_collected_at": None,
        }

    pnl_values: List[float] = []
    drawdown_values: List[float] = []
    fill_rates: List[float] = []
    total_trades = 0
    latest_collected_at: Optional[str] = None

    for record in records:
        pnl = _management_first_float(record, "pnl", "summary.total_pnl", "summary.pnl")
        drawdown = _management_first_float(
            record,
            "drawdown",
            "max_drawdown",
            "summary.max_drawdown",
        )
        fill_rate = _management_first_float(record, "fill_rate", "summary.fill_rate")
        trades = _management_first_float(record, "total_trades", "summary.total_trades")
        collected_at = str(
            record.get("collected_at")
            or record.get("collectedAt")
            or record.get("updated_at")
            or record.get("updatedAt")
            or ""
        ).strip()
        if pnl is not None:
            pnl_values.append(pnl)
        if drawdown is not None:
            drawdown_values.append(drawdown)
        if fill_rate is not None:
            fill_rates.append(fill_rate)
        if trades is not None:
            total_trades += int(trades)
        if collected_at and (latest_collected_at is None or collected_at > latest_collected_at):
            latest_collected_at = collected_at

    return {
        "runtime_count": len(records),
        "total_pnl": round(sum(pnl_values), 6) if pnl_values else None,
        "max_drawdown": max(drawdown_values) if drawdown_values else None,
        "average_fill_rate": round(sum(fill_rates) / len(fill_rates), 6) if fill_rates else None,
        "total_trades": total_trades,
        "latest_collected_at": latest_collected_at,
    }


def _management_portfolio_book_entry(
    pool: Dict[str, Any],
    *,
    bindings: List[Dict[str, Any]],
    deployment_plans: List[Dict[str, Any]],
    runtime_bindings: List[Dict[str, Any]],
    telemetry_by_runtime_id: Dict[str, Dict[str, Any]],
) -> Dict[str, Any]:
    pool_id = _management_record_id(pool, "pool_id", "id")
    pool_bindings = [
        binding
        for binding in bindings
        if _management_record_id(binding, "capital_pool_id", "pool_id") == pool_id
    ]
    pool_binding_ids = {
        _management_record_id(binding, "binding_id", "id", "persona_capital_binding_id")
        for binding in pool_bindings
    }
    pool_binding_ids.discard("")
    pool_plans = [
        plan
        for plan in deployment_plans
        if _management_record_id(plan, "capital_pool_id", "target_pool_id", "pool_id") == pool_id
        or bool(pool_binding_ids.intersection(str(v) for v in (plan.get("binding_ids") or [])))
    ]
    pool_plan_ids = {_management_record_id(plan, "plan_id", "id") for plan in pool_plans}
    pool_plan_ids.discard("")

    pool_runtimes = [
        runtime
        for runtime in runtime_bindings
        if _management_record_id(runtime, "capital_pool_id", "pool_id") == pool_id
        or _management_record_id(runtime, "plan_id", "deployment_plan_id") in pool_plan_ids
    ]
    telemetry_records = [
        telemetry_by_runtime_id[runtime_id]
        for runtime_id in (
            _management_record_id(runtime, "runtime_id", "id", "binding_id")
            for runtime in pool_runtimes
        )
        if runtime_id in telemetry_by_runtime_id
    ]
    telemetry = _management_telemetry_rollup(telemetry_records)
    exposure = _management_exposure_payload(
        pool=pool,
        pool_bindings=pool_bindings,
        pool_plans=pool_plans,
        pool_runtimes=pool_runtimes,
    )

    active_bindings = [
        binding
        for binding in pool_bindings
        if _management_normalized_status(binding) == "active"
        or str(binding.get("validity") or "").strip().lower() == "active"
    ]
    approved_plans = [
        plan
        for plan in pool_plans
        if _management_normalized_status(plan) in {"approved", "executing", "executed", "active"}
    ]
    active_runtimes = [
        runtime
        for runtime in pool_runtimes
        if _management_normalized_status(runtime) in {"active", "running", "healthy"}
    ]

    deployment_stages = sorted({
        stage
        for stage in (
            [
                str(plan.get("target_stage") or plan.get("stage") or plan.get("deployment_stage") or "").strip()
                for plan in pool_plans
            ]
            + [
                str(runtime.get("deployment_stage") or runtime.get("deployment_mode") or "").strip()
                for runtime in pool_runtimes
            ]
        )
        if stage
    })

    persona_ids_set = {
        str(b.get("persona_id") or "").strip()
        for b in pool_bindings
    }
    persona_ids_set.add(str(pool.get("persona_id") or pool.get("persona") or "").strip())
    persona_ids_set.discard("")
    persona_ids = sorted(persona_ids_set)

    strategy_ids_set = {
        str(x.get("strategy_id") or "").strip()
        for x in pool_bindings + pool_plans + pool_runtimes
    }
    strategy_ids_set.add(str(pool.get("strategy_id") or pool.get("strategy") or "").strip())
    strategy_ids_set.discard("")
    strategy_ids = sorted(strategy_ids_set)

    sleeve_ids_set = {
        str(x.get("sleeve_id") or "").strip()
        for x in pool_bindings + pool_plans + pool_runtimes
    }
    sleeve_ids_set.add(str(pool.get("sleeve_id") or pool.get("sleeve") or "").strip())
    sleeve_ids_set.discard("")
    sleeve_ids = sorted(sleeve_ids_set)

    artifact_ids_set = {
        str(x.get("artifact_id") or "").strip()
        for x in pool_plans + pool_runtimes
    }
    artifact_ids_set.add(str(pool.get("artifact_id") or pool.get("artifact") or "").strip())
    artifact_ids_set.discard("")
    artifact_ids = sorted(artifact_ids_set)

    broker_ids_set = {
        str(x.get("broker_id") or "").strip()
        for x in pool_bindings + pool_plans + pool_runtimes
    }
    broker_ids_set.add(str(pool.get("broker_id") or pool.get("broker") or "").strip())
    broker_ids_set.discard("")
    broker_ids = sorted(broker_ids_set)

    runtime_ids_set = {
        _management_record_id(runtime, "runtime_id", "id", "binding_id")
        for runtime in pool_runtimes
        if _management_record_id(runtime, "runtime_id", "id", "binding_id")
    }
    runtime_ids_set.add(str(pool.get("runtime_id") or pool.get("runtime") or "").strip())
    runtime_ids_set.discard("")
    runtime_ids = sorted(runtime_ids_set)

    return {
        "id": pool_id,
        "pool_id": pool_id,
        "name": pool.get("name") or pool_id,
        "status": pool.get("status") or "unknown",
        "risk_policy_ref": pool.get("risk_policy_ref"),
        "owner": {
            "id": pool.get("owner_id") or pool.get("owner"),
            "type": pool.get("owner_type"),
        },
        "currency": pool.get("currency"),
        **exposure,
        "pnl": telemetry["total_pnl"],
        "total_pnl": telemetry["total_pnl"],
        "pnl_summary": telemetry,
        "binding_count": len(pool_bindings),
        "active_binding_count": len(active_bindings),
        "deployment_count": len(pool_plans),
        "approved_deployment_count": len(approved_plans),
        "runtime_count": len(pool_runtimes),
        "active_runtime_count": len(active_runtimes),
        "paper_runtime_count": len([
            runtime
            for runtime in pool_runtimes
            if str(runtime.get("deployment_stage") or runtime.get("deployment_mode") or "").lower() == "paper"
        ]),
        "live_runtime_count": len([
            runtime
            for runtime in pool_runtimes
            if str(runtime.get("deployment_stage") or runtime.get("deployment_mode") or "").lower() == "live"
        ]),
        "deployment_stages": deployment_stages,
        "binding_ids": sorted(pool_binding_ids),
        "deployment_ids": sorted(pool_plan_ids),
        "runtime_ids": runtime_ids,
        "persona_ids": persona_ids,
        "strategy_ids": strategy_ids,
        "sleeve_ids": sleeve_ids,
        "artifact_ids": artifact_ids,
        "broker_ids": broker_ids,
        "telemetry": telemetry,
    }


def _management_portfolio_book_pool_sources(
    *,
    status: Optional[str] = None,
    risk_policy_ref: Optional[str] = None,
) -> Dict[str, Any]:
    capital_pools = read_store.list_capital_pools(status=status, risk_policy_ref=risk_policy_ref) or []
    bindings = read_store.list_bindings() or []
    deployment_plans = read_store.list_deployment_plans() or []
    runtime_bindings = read_store.list_runtime_bindings() or []

    telemetry_by_runtime_id: Dict[str, Dict[str, Any]] = {}
    for runtime in runtime_bindings:
        runtime_id = _management_record_id(runtime, "runtime_id", "id", "binding_id")
        if not runtime_id:
            continue
        telemetry = read_store.get_telemetry_summary(runtime_id)
        if telemetry is not None:
            telemetry_by_runtime_id[runtime_id] = telemetry

    entries = [
        _management_portfolio_book_entry(
            pool,
            bindings=bindings,
            deployment_plans=deployment_plans,
            runtime_bindings=runtime_bindings,
            telemetry_by_runtime_id=telemetry_by_runtime_id,
        )
        for pool in capital_pools
    ]
    return {
        "capital_pools": capital_pools,
        "bindings": bindings,
        "deployment_plans": deployment_plans,
        "runtime_bindings": runtime_bindings,
        "telemetry_by_runtime_id": telemetry_by_runtime_id,
        "entries": sorted(entries, key=lambda entry: str(entry.get("pool_id") or "")),
    }


def _management_exposure_risk_state(utilization: Optional[float]) -> str:
    if utilization is None:
        return "unknown"
    if utilization > 1:
        return "over_budget"
    if utilization >= 0.8:
        return "near_limit"
    return "within_budget"


def _management_portfolio_book_exposure_item(entry: Dict[str, Any]) -> Dict[str, Any]:
    pool_id = str(entry.get("pool_id") or entry.get("id") or "")
    risk_budget = _management_as_float(entry.get("risk_budget"))
    current_exposure = _management_as_float(entry.get("current_exposure"))
    utilization = _management_as_float(entry.get("risk_budget_utilization"))
    if utilization is None and current_exposure is not None and risk_budget not in (None, 0):
        utilization = round(current_exposure / risk_budget, 6)
    exposure = entry.get("exposure") if isinstance(entry.get("exposure"), dict) else {}
    runtime_ids = [
        str(value)
        for value in (entry.get("runtime_ids") or [])
        if str(value).strip()
    ]
    binding_ids = [
        str(value)
        for value in (entry.get("binding_ids") or [])
        if str(value).strip()
    ]
    deployment_ids = [
        str(value)
        for value in (entry.get("deployment_ids") or [])
        if str(value).strip()
    ]
    risk_state = _management_exposure_risk_state(utilization)
    available_budget = (
        round(risk_budget - current_exposure, 6)
        if risk_budget is not None and current_exposure is not None
        else None
    )
    return {
        "id": f"portfolio-book-exposure-{pool_id or 'unassigned'}",
        "pool_id": pool_id,
        "capital_pool_id": pool_id,
        "name": entry.get("name") or pool_id,
        "status": entry.get("status") or "unknown",
        "risk_policy_ref": entry.get("risk_policy_ref"),
        "currency": entry.get("currency"),
        "risk_budget": risk_budget,
        "current_exposure": current_exposure,
        "exposure_amount": current_exposure,
        "risk_budget_utilization": utilization,
        "risk_state": risk_state,
        "exposure_source": exposure.get("source"),
        "available_budget": available_budget,
        "risk": entry.get("risk"),
        "exposure": {
            **exposure,
            "amount": current_exposure,
            "risk_budget": risk_budget,
            "risk_budget_utilization": utilization,
            "risk_state": risk_state,
        },
        "pnl": entry.get("pnl"),
        "total_pnl": entry.get("total_pnl"),
        "pnl_summary": entry.get("pnl_summary"),
        "telemetry": entry.get("telemetry"),
        "binding_count": entry.get("binding_count", 0),
        "active_binding_count": entry.get("active_binding_count", 0),
        "deployment_count": entry.get("deployment_count", 0),
        "approved_deployment_count": entry.get("approved_deployment_count", 0),
        "runtime_count": entry.get("runtime_count", 0),
        "active_runtime_count": entry.get("active_runtime_count", 0),
        "paper_runtime_count": entry.get("paper_runtime_count", 0),
        "live_runtime_count": entry.get("live_runtime_count", 0),
        "deployment_stages": entry.get("deployment_stages") or [],
        "source_refs": {
            "runtime_ids": runtime_ids,
            "binding_ids": binding_ids,
            "deployment_ids": deployment_ids,
            "capital_pool_ids": [pool_id] if pool_id else [],
        },
        "links": {
            "capital_pool": _management_link("/bff/capital-pools", pool_id),
        },
    }


def _management_link(path: str, record_id: Optional[str]) -> Optional[str]:
    if not record_id:
        return None
    return f"{path}/{record_id}"


_PORTFOLIO_STALE_SOURCE_STATES = {"stale", "expired", "lagging"}
_PORTFOLIO_DEGRADED_SOURCE_STATES = {
    "degraded",
    "missing",
    "partial",
    "timeout",
    "unavailable",
    "unhealthy",
}


def _management_portfolio_stage(*records: Dict[str, Any]) -> str:
    for record in records:
        if not isinstance(record, dict):
            continue
        value = _management_first_non_empty(
            record.get("deployment_stage"),
            record.get("deployment_mode"),
            record.get("target_stage"),
            record.get("stage"),
        )
        if value not in (None, ""):
            return str(value).strip().lower()
    return "unknown"


def _management_portfolio_broker_id(
    position: Dict[str, Any],
    telemetry: Dict[str, Any],
    runtime: Dict[str, Any],
    plan: Dict[str, Any],
) -> str:
    return str(
        _management_first_non_empty(
            _management_dict_value(position, "broker_id", "broker", "broker_ref"),
            _management_dict_value(telemetry, "broker_id", "broker", "broker_ref"),
            _management_dict_value(runtime, "broker_id", "broker", "broker_ref"),
            _management_dict_value(plan, "broker_id", "broker", "broker_ref"),
        )
        or ""
    )


def _management_portfolio_ledger_id(
    position: Dict[str, Any],
    runtime: Dict[str, Any],
    plan: Dict[str, Any],
    persona_binding: Dict[str, Any],
) -> str:
    return str(
        _management_first_non_empty(
            _management_dict_value(position, "paper_ledger_id", "ledger_id"),
            _management_dict_value(runtime, "paper_ledger_id", "ledger_id"),
            _management_dict_value(plan, "paper_ledger_id", "ledger_id"),
            _management_dict_value(persona_binding, "paper_ledger_id", "ledger_id"),
        )
        or ""
    )


def _management_portfolio_sleeve_id(
    position: Dict[str, Any],
    runtime: Dict[str, Any],
    plan: Dict[str, Any],
    persona_binding: Dict[str, Any],
) -> str:
    return str(
        _management_first_non_empty(
            _management_dict_value(position, "sleeve_id", "canary_sleeve_id", "capital_sleeve_id"),
            _management_dict_value(runtime, "sleeve_id", "canary_sleeve_id", "capital_sleeve_id"),
            _management_dict_value(plan, "sleeve_id", "canary_sleeve_id", "capital_sleeve_id"),
            _management_dict_value(persona_binding, "sleeve_id", "canary_sleeve_id", "capital_sleeve_id"),
        )
        or ""
    )


def _management_portfolio_source_issues(
    *,
    runtime_id: str,
    persona_id: str,
    persona_binding_id: str,
    telemetry: Dict[str, Any],
    position_source_count: int,
) -> List[Dict[str, Any]]:
    issues: List[Dict[str, Any]] = []
    if not persona_id or not persona_binding_id:
        issues.append({
            "source_name": "persona_bindings",
            "code": "MISSING_PERSONA_BINDING",
            "message": f"Runtime {runtime_id or 'unknown'} does not resolve to a persona capital binding.",
        })
    if not telemetry:
        issues.append({
            "source_name": "telemetry_summaries",
            "code": "MISSING_TELEMETRY",
            "message": f"Telemetry summary is unavailable for runtime {runtime_id or 'unknown'}.",
        })
    elif position_source_count <= 0:
        issues.append({
            "source_name": "portfolio_holdings",
            "code": "MISSING_HOLDING_ROW",
            "message": f"Telemetry for runtime {runtime_id or 'unknown'} did not include a holding or position row.",
        })

    freshness = str(
        _management_first_non_empty(
            telemetry.get("source_status"),
            telemetry.get("source_state"),
            telemetry.get("data_status"),
            telemetry.get("freshness_status"),
        )
        or ""
    ).strip().lower()
    if bool(telemetry.get("stale")) or freshness in _PORTFOLIO_STALE_SOURCE_STATES:
        issues.append({
            "source_name": "telemetry_summaries",
            "code": "STALE_TELEMETRY",
            "message": f"Telemetry for runtime {runtime_id or 'unknown'} is stale.",
        })
    elif freshness in _PORTFOLIO_DEGRADED_SOURCE_STATES:
        issues.append({
            "source_name": "telemetry_summaries",
            "code": "DEGRADED_TELEMETRY",
            "message": f"Telemetry for runtime {runtime_id or 'unknown'} is degraded.",
        })
    return issues


def _management_portfolio_source_status(issues: List[Dict[str, Any]]) -> str:
    codes = {str(issue.get("code") or "") for issue in issues}
    if "STALE_TELEMETRY" in codes:
        return "stale"
    if codes:
        return "degraded"
    return "ok"


def _management_portfolio_risk_state(
    *,
    source_status: str,
    source_issues: List[Dict[str, Any]],
    deployment_stage: str,
) -> str:
    codes = {str(issue.get("code") or "") for issue in source_issues}
    if "MISSING_PERSONA_BINDING" in codes:
        return "missing_binding"
    if "STALE_TELEMETRY" in codes:
        return "stale_telemetry"
    if source_status == "degraded":
        return "degraded_source"
    if deployment_stage == "live":
        return "live_exposure"
    if deployment_stage == "canary":
        return "canary_exposure"
    if deployment_stage == "paper":
        return "paper_exposure"
    return "unknown"


def _management_portfolio_operator_links(
    *,
    persona_id: str,
    runtime_id: str,
    holding_id: str,
) -> Dict[str, Optional[str]]:
    query: Dict[str, str] = {}
    if persona_id:
        query["persona_id"] = persona_id
    if runtime_id:
        query["runtime_id"] = runtime_id
    query_string = urlencode(query)
    attribution_href = "/management/performance-attribution"
    review_href = "/management/human-inbox"
    if query_string:
        attribution_href = f"{attribution_href}?{query_string}"
        review_href = f"{review_href}?{query_string}"
    return {
        "persona_fleet": f"/management/persona-fleet?persona_id={quote(persona_id)}" if persona_id else None,
        "performance_attribution": attribution_href if query else None,
        "human_review": (
            f"{review_href}&target_type=portfolio_holding&target_id={quote(holding_id)}"
            if query_string and holding_id
            else review_href if query else None
        ),
    }


def _management_portfolio_identity(
    *,
    portfolio_id: str,
    capital_pool_id: str,
    sleeve_id: str,
    paper_ledger_id: str,
    persona_id: str,
    runtime_id: str,
    runtime_binding_id: str,
    plan_id: str,
    strategy_id: str,
    artifact_id: str,
    broker_id: str,
    deployment_stage: str,
) -> Dict[str, Any]:
    stage = deployment_stage or "unknown"
    return {
        "portfolio_id": portfolio_id,
        "capital_pool_id": capital_pool_id,
        "capital_pool_ids": [capital_pool_id] if capital_pool_id else [],
        "sleeve_id": sleeve_id or None,
        "sleeve_ids": [sleeve_id] if sleeve_id else [],
        "paper_ledger_id": paper_ledger_id or None,
        "paper_ledger_ids": [paper_ledger_id] if paper_ledger_id else [],
        "persona_id": persona_id,
        "persona_ids": [persona_id] if persona_id else [],
        "runtime_id": runtime_id,
        "runtime_ids": [runtime_id] if runtime_id else [],
        "runtime_binding_id": runtime_binding_id,
        "runtime_binding_ids": [runtime_binding_id] if runtime_binding_id else [],
        "deployment_plan_id": plan_id,
        "deployment_plan_ids": [plan_id] if plan_id else [],
        "strategy_id": strategy_id,
        "strategy_ids": [strategy_id] if strategy_id else [],
        "artifact_id": artifact_id,
        "artifact_ids": [artifact_id] if artifact_id else [],
        "broker_id": broker_id,
        "broker_ids": [broker_id] if broker_id else [],
        "stage": stage,
        "deployment_stage": stage,
    }


def _management_portfolio_capital_scope(
    *,
    deployment_stage: str,
    capital_pool_id: str,
    sleeve_id: str,
    paper_ledger_id: str,
) -> Dict[str, Any]:
    if deployment_stage == "paper":
        scope_kind = "paper_ledger"
        scope_id = paper_ledger_id
    elif deployment_stage == "canary":
        scope_kind = "canary_sleeve"
        scope_id = sleeve_id
    elif deployment_stage == "live":
        scope_kind = "live_capital_pool"
        scope_id = capital_pool_id
    else:
        scope_kind = "unclassified"
        scope_id = capital_pool_id or sleeve_id or paper_ledger_id
    return {
        "stage": deployment_stage or "unknown",
        "scope_kind": scope_kind,
        "scope_id": scope_id or None,
        "paper_ledger_id": paper_ledger_id or None,
        "canary_sleeve_id": sleeve_id if deployment_stage == "canary" else None,
        "live_capital_pool_id": capital_pool_id if deployment_stage == "live" else None,
        "capital_pool_id": capital_pool_id or None,
        "sleeve_id": sleeve_id or None,
    }


def _management_portfolio_incident(metadata: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    issues = metadata.get("source_issues") if isinstance(metadata.get("source_issues"), list) else []
    if not issues:
        return None
    runtime_id = str(metadata.get("runtime_id") or "")
    holding_id = str(metadata.get("holding_id") or runtime_id or "unassigned")
    risk_state = str(metadata.get("risk_state") or "degraded_source")
    severity = "high" if risk_state in {"missing_binding", "degraded_source"} else "medium"
    return {
        "id": f"portfolio-risk-{risk_state}-{holding_id}",
        "kind": risk_state,
        "status": "open",
        "severity": severity,
        "message": "; ".join(str(issue.get("message") or issue.get("code") or "") for issue in issues if issue),
        "risk_state": risk_state,
        "source_status": metadata.get("source_status"),
        "source_issues": issues,
        "identity": metadata.get("identity") or {},
        "source_refs": {
            "runtime_ids": [runtime_id] if runtime_id else [],
            "persona_ids": [metadata.get("persona_id")] if metadata.get("persona_id") else [],
            "capital_pool_ids": [metadata.get("capital_pool_id")] if metadata.get("capital_pool_id") else [],
        },
        "links": metadata.get("links") or {},
    }


def _management_portfolio_holding_entry(
    runtime: Dict[str, Any],
    position: Dict[str, Any],
    *,
    position_index: int,
    plan: Dict[str, Any],
    persona_binding: Dict[str, Any],
    capital_pool: Dict[str, Any],
    telemetry: Dict[str, Any],
    position_source_count: int = 1,
) -> Dict[str, Any]:
    summary = telemetry.get("summary") if isinstance(telemetry.get("summary"), dict) else {}
    instrument = _management_nested_dict(position, "instrument", "asset", "contract")
    mark = _management_nested_dict(position, "mark", "mark_price", "market_price")

    runtime_id = _management_record_id(runtime, "runtime_id", "id", "binding_id")
    runtime_binding_id = _management_record_id(runtime, "runtime_binding_id", "binding_id", "id")
    plan_id = _management_record_id(runtime, "plan_id", "deployment_plan_id") or _management_record_id(plan, "plan_id", "id")
    persona_binding_id = (
        _management_record_id(runtime, "persona_capital_binding_id")
        or _management_record_id(persona_binding, "binding_id", "id", "persona_capital_binding_id")
    )
    capital_pool_id = str(
        _management_first_non_empty(
            _management_dict_value(position, "capital_pool_id", "pool_id"),
            _management_dict_value(runtime, "capital_pool_id", "pool_id"),
            _management_dict_value(plan, "capital_pool_id", "target_pool_id", "pool_id"),
            _management_dict_value(persona_binding, "capital_pool_id", "pool_id"),
        )
        or ""
    )
    persona_id = str(
        _management_first_non_empty(
            _management_dict_value(position, "persona_id"),
            _management_dict_value(runtime, "persona_id"),
            _management_dict_value(plan, "persona_id"),
            _management_dict_value(persona_binding, "persona_id"),
        )
        or ""
    )
    strategy_id = str(
        _management_first_non_empty(
            _management_dict_value(position, "strategy_id", "strategy_ref"),
            _management_dict_value(runtime, "strategy_id", "strategy_ref"),
            _management_dict_value(plan, "strategy_id", "strategy_ref"),
            _management_dict_value(persona_binding, "strategy_id"),
        )
        or ""
    )
    artifact_id = str(
        _management_first_non_empty(
            _management_dict_value(position, "artifact_id"),
            _management_dict_value(runtime, "artifact_id"),
            _management_dict_value(plan, "artifact_id"),
        )
        or ""
    )
    artifact_version = str(
        _management_first_non_empty(
            _management_dict_value(position, "artifact_version", "version"),
            _management_dict_value(runtime, "artifact_version", "version"),
            _management_dict_value(plan, "artifact_version", "version"),
        )
        or ""
    )
    broker_id = _management_portfolio_broker_id(position, telemetry, runtime, plan)
    paper_ledger_id = _management_portfolio_ledger_id(position, runtime, plan, persona_binding)
    sleeve_id = _management_portfolio_sleeve_id(position, runtime, plan, persona_binding)

    symbol = str(
        _management_first_non_empty(
            _management_dict_value(position, "symbol", "instrument_id", "asset_id", "contract_id"),
            _management_dict_value(instrument, "symbol", "instrument_id", "asset_id", "contract_id"),
            _management_dict_value(telemetry, "symbol", "instrument_id", "asset_id", "contract_id"),
        )
        or ""
    )
    asset_class = _management_first_non_empty(
        _management_dict_value(position, "asset_class"),
        _management_dict_value(instrument, "asset_class"),
        _management_dict_value(telemetry, "asset_class"),
    )
    currency = _management_first_non_empty(
        _management_dict_value(position, "currency"),
        _management_dict_value(instrument, "currency"),
        _management_dict_value(telemetry, "currency"),
    )
    quantity = _management_as_float(
        _management_first_non_empty(
            _management_dict_value(position, "quantity", "qty", "net_quantity", "position_quantity"),
            _management_dict_value(telemetry, "quantity", "position_quantity"),
            _management_dict_value(summary, "quantity", "position_quantity"),
        )
    )
    mark_price = _management_as_float(
        _management_first_non_empty(
            _management_dict_value(position, "mark_price", "market_price", "last_price"),
            _management_dict_value(mark, "price", "mark_price", "market_price", "last_price"),
            _management_dict_value(telemetry, "mark_price", "market_price", "last_price"),
            _management_dict_value(summary, "mark_price", "market_price", "last_price"),
        )
    )
    average_price = _management_as_float(
        _management_first_non_empty(
            _management_dict_value(position, "average_price", "avg_price", "cost_basis"),
            _management_dict_value(telemetry, "average_price", "avg_price", "cost_basis"),
            _management_dict_value(summary, "average_price", "avg_price", "cost_basis"),
        )
    )
    market_value = _management_as_float(
        _management_first_non_empty(
            _management_dict_value(position, "market_value", "value"),
            _management_dict_value(telemetry, "market_value"),
            _management_dict_value(summary, "market_value"),
        )
    )
    if market_value is None and quantity is not None and mark_price is not None:
        market_value = round(quantity * mark_price, 6)
    notional = _management_as_float(
        _management_first_non_empty(
            _management_dict_value(position, "notional", "gross_notional"),
            _management_dict_value(telemetry, "notional", "gross_notional"),
            _management_dict_value(summary, "notional", "gross_notional"),
        )
    )
    if notional is None and market_value is not None:
        notional = abs(market_value)
    exposure = _management_as_float(
        _management_first_non_empty(
            _management_dict_value(position, "exposure", "gross_exposure"),
            _management_dict_value(telemetry, "exposure", "gross_exposure"),
            _management_dict_value(summary, "exposure", "gross_exposure"),
        )
    )
    weight = _management_as_float(
        _management_first_non_empty(
            _management_dict_value(position, "weight", "portfolio_weight"),
            _management_dict_value(telemetry, "weight", "portfolio_weight"),
            _management_dict_value(summary, "weight", "portfolio_weight"),
        )
    )
    runtime_pnl = _management_as_float(
        _management_first_non_empty(
            _management_dict_value(telemetry, "pnl"),
            _management_dict_value(summary, "total_pnl"),
        )
    )
    total_pnl = _management_as_float(
        _management_first_non_empty(
            _management_dict_value(position, "total_pnl", "pnl"),
            runtime_pnl,
        )
    )
    unrealized_pnl = _management_as_float(
        _management_first_non_empty(
            _management_dict_value(position, "unrealized_pnl", "unrealized"),
            _management_dict_value(telemetry, "unrealized_pnl"),
            _management_dict_value(summary, "unrealized_pnl"),
        )
    )
    realized_pnl = _management_as_float(
        _management_first_non_empty(
            _management_dict_value(position, "realized_pnl", "realized"),
            _management_dict_value(telemetry, "realized_pnl"),
            _management_dict_value(summary, "realized_pnl"),
        )
    )
    side = str(
        _management_first_non_empty(
            _management_dict_value(position, "side", "direction"),
            _management_dict_value(telemetry, "side", "direction"),
        )
        or ""
    ).lower()
    if not side and quantity is not None:
        side = "long" if quantity > 0 else "short" if quantity < 0 else "flat"
    if not side:
        side = "unknown"

    holding_key = str(
        _management_first_non_empty(
            _management_dict_value(position, "holding_id", "position_id", "id"),
            symbol,
            artifact_id,
            position_index,
        )
    )
    holding_id = f"{runtime_id}:{holding_key}" if runtime_id else holding_key
    deployment_stage = _management_portfolio_stage(position, runtime, plan)
    status = str(_management_first_non_empty(position.get("status"), runtime.get("status"), "unknown") or "unknown")
    last_mark_at = str(
        _management_first_non_empty(
            _management_dict_value(position, "marked_at", "mark_time", "updated_at", "collected_at"),
            _management_dict_value(mark, "marked_at", "mark_time", "updated_at", "collected_at"),
            _management_dict_value(telemetry, "collected_at", "updated_at"),
            _management_dict_value(summary, "collected_at", "updated_at"),
        )
        or ""
    )
    source_issues = _management_portfolio_source_issues(
        runtime_id=runtime_id,
        persona_id=persona_id,
        persona_binding_id=persona_binding_id,
        telemetry=telemetry,
        position_source_count=position_source_count,
    )
    source_status = _management_portfolio_source_status(source_issues)
    risk_state = _management_portfolio_risk_state(
        source_status=source_status,
        source_issues=source_issues,
        deployment_stage=deployment_stage,
    )
    identity = _management_portfolio_identity(
        portfolio_id=holding_id,
        capital_pool_id=capital_pool_id,
        sleeve_id=sleeve_id,
        paper_ledger_id=paper_ledger_id,
        persona_id=persona_id,
        runtime_id=runtime_id,
        runtime_binding_id=runtime_binding_id,
        plan_id=plan_id,
        strategy_id=strategy_id,
        artifact_id=artifact_id,
        broker_id=broker_id,
        deployment_stage=deployment_stage,
    )
    operator_links = _management_portfolio_operator_links(
        persona_id=persona_id,
        runtime_id=runtime_id,
        holding_id=holding_id,
    )

    return {
        "id": holding_id,
        "holding_id": holding_id,
        "runtime_id": runtime_id,
        "runtime_binding_id": runtime_binding_id,
        "deployment_plan_id": plan_id,
        "capital_pool_id": capital_pool_id,
        "capital_pool": {
            "id": capital_pool_id,
            "name": capital_pool.get("name") or capital_pool_id,
            "status": capital_pool.get("status"),
            "risk_policy_ref": capital_pool.get("risk_policy_ref"),
        },
        "persona_id": persona_id,
        "persona_capital_binding_id": persona_binding_id,
        "strategy_id": strategy_id,
        "artifact_id": artifact_id,
        "artifact_version": artifact_version,
        "broker_id": broker_id,
        "paper_ledger_id": paper_ledger_id or None,
        "sleeve_id": sleeve_id or None,
        "deployment_stage": deployment_stage,
        "status": status,
        "identity": identity,
        "capital_scope": _management_portfolio_capital_scope(
            deployment_stage=deployment_stage,
            capital_pool_id=capital_pool_id,
            sleeve_id=sleeve_id,
            paper_ledger_id=paper_ledger_id,
        ),
        "source_status": source_status,
        "source_row_count": position_source_count,
        "source_issues": source_issues,
        "telemetry_available": bool(telemetry),
        "telemetry_stale": any(issue.get("code") == "STALE_TELEMETRY" for issue in source_issues),
        "risk_state": risk_state,
        "instrument": {
            "symbol": symbol,
            "asset_class": asset_class,
            "currency": currency,
            "market": _management_first_non_empty(
                _management_dict_value(position, "market"),
                _management_dict_value(instrument, "market"),
                _management_dict_value(telemetry, "market"),
            ),
        },
        "symbol": symbol,
        "side": side,
        "quantity": quantity,
        "average_price": average_price,
        "mark_price": mark_price,
        "market_value": market_value,
        "notional": notional,
        "exposure": exposure,
        "weight": weight,
        "pnl": {
            "total": total_pnl,
            "runtime": runtime_pnl,
            "unrealized": unrealized_pnl,
            "realized": realized_pnl,
            "drawdown": _management_as_float(
                _management_first_non_empty(telemetry.get("drawdown"), summary.get("max_drawdown"))
            ),
            "fill_rate": _management_as_float(
                _management_first_non_empty(telemetry.get("fill_rate"), summary.get("fill_rate"))
            ),
            "total_trades": _management_as_float(
                _management_first_non_empty(telemetry.get("total_trades"), summary.get("total_trades"))
            ),
        },
        "total_pnl": total_pnl,
        "unrealized_pnl": unrealized_pnl,
        "realized_pnl": realized_pnl,
        "last_mark_at": last_mark_at or None,
        "telemetry": {
            "runtime_id": telemetry.get("runtime_id") or runtime_id,
            "window": telemetry.get("window"),
            "collected_at": telemetry.get("collected_at"),
            "drawdown": telemetry.get("drawdown"),
            "fill_rate": telemetry.get("fill_rate"),
            "avg_slippage_bps": telemetry.get("avg_slippage_bps"),
            "total_trades": telemetry.get("total_trades"),
        },
        "links": {
            "runtime": _management_link("/bff/runtimes", runtime_id),
            "capital_pool": _management_link("/bff/capital-pools", capital_pool_id),
            "persona": _management_link("/bff/personas", persona_id),
            "strategy": _management_link("/bff/strategies", strategy_id),
            "deployment": _management_link("/bff/deployments", plan_id),
            **operator_links,
        },
    }


