@app.get("/bff/management/portfolio-book")
async def bff_management_portfolio_book(
    page_token: Optional[str] = None,
    page_size: int = Query(default=50, ge=1, le=200),
    authorization: Optional[str] = Header(default=None),
    # Common filters:
    persona_id: Optional[str] = Query(default=None, alias="personaId"),
    persona: Optional[str] = Query(default=None),
    runtime_id: Optional[str] = Query(default=None, alias="runtimeId"),
    runtime: Optional[str] = Query(default=None),
    strategy_id: Optional[str] = Query(default=None, alias="strategyId"),
    strategy: Optional[str] = Query(default=None),
    capital_pool_id: Optional[str] = Query(default=None, alias="capitalPoolId"),
    pool: Optional[str] = Query(default=None),
    sleeve_id: Optional[str] = Query(default=None, alias="sleeveId"),
    sleeve: Optional[str] = Query(default=None),
    artifact_id: Optional[str] = Query(default=None, alias="artifactId"),
    artifact: Optional[str] = Query(default=None),
    broker_id: Optional[str] = Query(default=None, alias="brokerId"),
    broker: Optional[str] = Query(default=None),
    stage: Optional[str] = Query(default=None),
    period: Optional[str] = Query(default=None),
    as_of: Optional[str] = Query(default=None, alias="asOf"),
):
    """BFF: composed portfolio-book summary for Management Console PM-12."""
    page_token = _resolve_param(page_token)
    page_size = _resolve_param(page_size)
    authorization = _resolve_param(authorization)
    persona_id = _resolve_param(persona_id)
    persona = _resolve_param(persona)
    runtime_id = _resolve_param(runtime_id)
    runtime = _resolve_param(runtime)
    strategy_id = _resolve_param(strategy_id)
    strategy = _resolve_param(strategy)
    capital_pool_id = _resolve_param(capital_pool_id)
    pool = _resolve_param(pool)
    sleeve_id = _resolve_param(sleeve_id)
    sleeve = _resolve_param(sleeve)
    artifact_id = _resolve_param(artifact_id)
    artifact = _resolve_param(artifact)
    broker_id = _resolve_param(broker_id)
    broker = _resolve_param(broker)
    stage = _resolve_param(stage)
    period = _resolve_param(period)
    as_of = _resolve_param(as_of)

    identity = _extract_identity(authorization)
    _require_read_role(identity)

    snapshot_at = utc_now()
    sources = _management_portfolio_book_pool_sources()
    capital_pools = sources["capital_pools"]
    bindings = sources["bindings"]
    deployment_plans = sources["deployment_plans"]
    runtime_bindings = sources["runtime_bindings"]
    telemetry_by_runtime_id = sources["telemetry_by_runtime_id"]
    entries = sources["entries"]

    # Apply common filters
    entries = _filter_by_common_identifiers(
        entries,
        persona_id=persona_id, persona=persona,
        runtime_id=runtime_id, runtime=runtime,
        strategy_id=strategy_id, strategy=strategy,
        capital_pool_id=capital_pool_id, pool=pool,
        sleeve_id=sleeve_id, sleeve=sleeve,
        artifact_id=artifact_id, artifact=artifact,
        broker_id=broker_id, broker=broker,
        stage=stage, period=period, as_of=as_of
    )

    total = len(entries)
    page_items, next_page_token = _page_slice(entries, page_token, page_size)
    portfolio_telemetry = _management_telemetry_rollup(list(telemetry_by_runtime_id.values()))

    active_pool_count = len([
        pool for pool in capital_pools if _management_normalized_status(pool) in {"active", "ready"}
    ])
    active_binding_count = len([
        binding
        for binding in bindings
        if _management_normalized_status(binding) == "active"
        or str(binding.get("validity") or "").strip().lower() == "active"
    ])
    approved_deployment_count = len([
        plan
        for plan in deployment_plans
        if _management_normalized_status(plan) in {"approved", "executing", "executed", "active"}
    ])
    active_runtime_count = len([
        runtime
        for runtime in runtime_bindings
        if _management_normalized_status(runtime) in {"active", "running", "healthy"}
    ])
    paper_runtime_count = len([
        runtime
        for runtime in runtime_bindings
        if str(runtime.get("deployment_stage") or runtime.get("deployment_mode") or "").lower() == "paper"
    ])
    live_runtime_count = len([
        runtime
        for runtime in runtime_bindings
        if str(runtime.get("deployment_stage") or runtime.get("deployment_mode") or "").lower() == "live"
    ])
    stale_telemetry_runtime_count = len([
        telemetry
        for telemetry in telemetry_by_runtime_id.values()
        if bool(telemetry.get("stale"))
        or str(
            _management_first_non_empty(
                telemetry.get("source_status"),
                telemetry.get("source_state"),
                telemetry.get("data_status"),
                telemetry.get("freshness_status"),
            )
            or ""
        ).strip().lower() in _PORTFOLIO_STALE_SOURCE_STATES
    ])
    missing_binding_count = len([
        runtime
        for runtime in runtime_bindings
        if not _management_record_id(runtime, "persona_id", "persona_capital_binding_id")
    ])
    degraded_source_count = max(0, len(runtime_bindings) - portfolio_telemetry["runtime_count"]) + stale_telemetry_runtime_count
    source_row_count = (
        len(capital_pools)
        + len(bindings)
        + len(deployment_plans)
        + len(runtime_bindings)
        + portfolio_telemetry["runtime_count"]
    )

    summary = {
        "portfolio_book_status": "ready" if total else "empty",
        "source_row_count": source_row_count,
        "capital_pool_count": len(capital_pools),
        "active_capital_pool_count": active_pool_count,
        "binding_count": len(bindings),
        "active_binding_count": active_binding_count,
        "deployment_count": len(deployment_plans),
        "approved_deployment_count": approved_deployment_count,
        "runtime_count": len(runtime_bindings),
        "active_runtime_count": active_runtime_count,
        "paper_runtime_count": paper_runtime_count,
        "live_runtime_count": live_runtime_count,
        "telemetry_runtime_count": portfolio_telemetry["runtime_count"],
        "stale_row_count": stale_telemetry_runtime_count,
        "missing_binding_count": missing_binding_count,
        "degraded_source_count": degraded_source_count,
        "source_coverage": {
            "source_row_count": source_row_count,
            "runtime_count": len(runtime_bindings),
            "telemetry_runtime_count": portfolio_telemetry["runtime_count"],
            "stale_row_count": stale_telemetry_runtime_count,
            "missing_binding_count": missing_binding_count,
            "degraded_source_count": degraded_source_count,
        },
        "total_pnl": portfolio_telemetry["total_pnl"],
        "max_drawdown": portfolio_telemetry["max_drawdown"],
        "average_fill_rate": portfolio_telemetry["average_fill_rate"],
        "total_trades": portfolio_telemetry["total_trades"],
        "latest_telemetry_at": portfolio_telemetry["latest_collected_at"],
    }

    surfaces = {
        "portfolio_book": _composed_surface_status(
            snapshot_at=snapshot_at,
            available=bool(capital_pools or bindings or deployment_plans or runtime_bindings),
            missing_message="Portfolio-book composition has no readable source records.",
        ),
        "capital_pools": _dataset_surface_status("capital_pools", snapshot_at=snapshot_at),
        "persona_bindings": _dataset_surface_status("persona_bindings", snapshot_at=snapshot_at),
        "deployment_plans": _dataset_surface_status("deployment_plans", snapshot_at=snapshot_at),
        "runtime_bindings": _dataset_surface_status("runtime_bindings", snapshot_at=snapshot_at),
        "telemetry_summaries": _dataset_surface_status(
            "telemetry_summaries",
            snapshot_at=snapshot_at,
            has_data=bool(telemetry_by_runtime_id) if runtime_bindings else None,
            missing_message="Telemetry summaries unavailable for portfolio-book runtimes.",
        ),
    }
    if any(surface.get("status") == "unavailable" for key, surface in surfaces.items() if key != "portfolio_book"):
        surfaces["portfolio_book"] = _composed_surface_status(
            snapshot_at=snapshot_at,
            available=False,
            missing_message="Portfolio-book composition is degraded because one or more source surfaces are unavailable.",
        )

    meta = _snapshot_meta(snapshot_at)
    meta["surfaces"] = surfaces
    meta["total"] = total
    meta["summary"] = {
        "source_mode": "bff_composed",
        "task": "BFF-PM12-001",
    }

    return {
        "data": {
            "summary": summary,
            "items": page_items,
        },
        "page_info": {"next_page_token": next_page_token, "total": total},
        "meta": meta,
    }


@app.get("/bff/management/portfolio-book/pools")
async def bff_management_portfolio_book_pools(
    status: Optional[str] = None,
    risk_policy_ref: Optional[str] = None,
    page_token: Optional[str] = None,
    page_size: int = Query(default=50, ge=1, le=200),
    authorization: Optional[str] = Header(default=None),
    # Common filters:
    persona_id: Optional[str] = Query(default=None, alias="personaId"),
    persona: Optional[str] = Query(default=None),
    runtime_id: Optional[str] = Query(default=None, alias="runtimeId"),
    runtime: Optional[str] = Query(default=None),
    strategy_id: Optional[str] = Query(default=None, alias="strategyId"),
    strategy: Optional[str] = Query(default=None),
    capital_pool_id: Optional[str] = Query(default=None, alias="capitalPoolId"),
    pool: Optional[str] = Query(default=None),
    sleeve_id: Optional[str] = Query(default=None, alias="sleeveId"),
    sleeve: Optional[str] = Query(default=None),
    artifact_id: Optional[str] = Query(default=None, alias="artifactId"),
    artifact: Optional[str] = Query(default=None),
    broker_id: Optional[str] = Query(default=None, alias="brokerId"),
    broker: Optional[str] = Query(default=None),
    stage: Optional[str] = Query(default=None),
    period: Optional[str] = Query(default=None),
    as_of: Optional[str] = Query(default=None, alias="asOf"),
):
    """BFF: PM-12 portfolio-book capital pool summaries."""
    status = _resolve_param(status)
    risk_policy_ref = _resolve_param(risk_policy_ref)
    page_token = _resolve_param(page_token)
    page_size = _resolve_param(page_size)
    authorization = _resolve_param(authorization)
    persona_id = _resolve_param(persona_id)
    persona = _resolve_param(persona)
    runtime_id = _resolve_param(runtime_id)
    runtime = _resolve_param(runtime)
    strategy_id = _resolve_param(strategy_id)
    strategy = _resolve_param(strategy)
    capital_pool_id = _resolve_param(capital_pool_id)
    pool = _resolve_param(pool)
    sleeve_id = _resolve_param(sleeve_id)
    sleeve = _resolve_param(sleeve)
    artifact_id = _resolve_param(artifact_id)
    artifact = _resolve_param(artifact)
    broker_id = _resolve_param(broker_id)
    broker = _resolve_param(broker)
    stage = _resolve_param(stage)
    period = _resolve_param(period)
    as_of = _resolve_param(as_of)

    identity = _extract_identity(authorization)
    _require_read_role(identity)

    snapshot_at = utc_now()
    sources = _management_portfolio_book_pool_sources(
        status=status,
        risk_policy_ref=risk_policy_ref,
    )
    entries = sources["entries"]

    # Apply common filters
    entries = _filter_by_common_identifiers(
        entries,
        persona_id=persona_id, persona=persona,
        runtime_id=runtime_id, runtime=runtime,
        strategy_id=strategy_id, strategy=strategy,
        capital_pool_id=capital_pool_id, pool=pool,
        sleeve_id=sleeve_id, sleeve=sleeve,
        artifact_id=artifact_id, artifact=artifact,
        broker_id=broker_id, broker=broker,
        stage=stage, period=period, as_of=as_of
    )

    telemetry_by_runtime_id = sources["telemetry_by_runtime_id"]
    total = len(entries)
    page_items, next_page_token = _page_slice(entries, page_token, page_size)

    risk_budgets = [
        value
        for entry in entries
        for value in [_management_as_float(entry.get("risk_budget"))]
        if value is not None
    ]
    exposures = [
        value
        for entry in entries
        for value in [_management_as_float(entry.get("current_exposure"))]
        if value is not None
    ]
    portfolio_telemetry = _management_telemetry_rollup(list(telemetry_by_runtime_id.values()))
    risk_budget_total = round(sum(risk_budgets), 6) if risk_budgets else None
    current_exposure_total = round(sum(exposures), 6) if exposures else None
    utilization = None
    if current_exposure_total is not None and risk_budget_total not in (None, 0):
        utilization = round(current_exposure_total / risk_budget_total, 6)

    source_surfaces = {
        "capital_pools": _dataset_surface_status("capital_pools", snapshot_at=snapshot_at),
        "persona_bindings": _dataset_surface_status("persona_bindings", snapshot_at=snapshot_at),
        "deployment_plans": _dataset_surface_status("deployment_plans", snapshot_at=snapshot_at),
        "runtime_bindings": _dataset_surface_status("runtime_bindings", snapshot_at=snapshot_at),
        "telemetry_summaries": _dataset_surface_status(
            "telemetry_summaries",
            snapshot_at=snapshot_at,
            has_data=bool(telemetry_by_runtime_id) if sources["runtime_bindings"] else None,
            missing_message="Telemetry summaries unavailable for portfolio-book pool runtimes.",
        ),
    }
    pool_surface = _aggregate_group_surface(
        "portfolio_book_pools",
        list(source_surfaces.values()),
        snapshot_at=snapshot_at,
        unavailable_message="Portfolio-book pool composition has no readable source records.",
        degraded_message="Portfolio-book pool composition is degraded because one or more source surfaces are degraded.",
    )

    return {
        "data": {
            "items": page_items,
            "summary": {
                "total_pools": total,
                "returned_pools": len(page_items),
                "active_pool_count": len([
                    entry for entry in entries
                    if str(entry.get("status") or "").strip().lower() in {"active", "ready"}
                ]),
                "risk_budget_total": risk_budget_total,
                "current_exposure_total": current_exposure_total,
                "risk_budget_utilization": utilization,
                "telemetry_runtime_count": portfolio_telemetry["runtime_count"],
                "total_pnl": portfolio_telemetry["total_pnl"],
                "max_drawdown": portfolio_telemetry["max_drawdown"],
                "average_fill_rate": portfolio_telemetry["average_fill_rate"],
                "total_trades": portfolio_telemetry["total_trades"],
                "latest_telemetry_at": portfolio_telemetry["latest_collected_at"],
            },
        },
        "page_info": {
            "next_page_token": next_page_token,
            "total": total,
            "page_size": page_size,
        },
        "meta": {
            **_snapshot_meta(snapshot_at),
            "total": total,
            "surfaces": {
                "portfolio_book_pools": pool_surface,
                **source_surfaces,
            },
            "composition_sources": [
                "GET /bff/capital-pools",
                "GET /api/v1/persona-capital-bindings",
                "GET /api/v1/deployment-plans",
                "GET /api/v1/runtime-bindings",
                "GET /api/v1/telemetry/{runtime_id}/summary",
            ],
        },
    }


@app.get("/bff/management/portfolio-book/exposure")
async def bff_management_portfolio_book_exposure(
    status: Optional[str] = None,
    risk_policy_ref: Optional[str] = None,
    capital_pool_id: Optional[str] = None,
    page_token: Optional[str] = None,
    page_size: int = Query(default=50, ge=1, le=200),
    authorization: Optional[str] = Header(default=None),
    # Common filters:
    persona_id: Optional[str] = Query(default=None, alias="personaId"),
    persona: Optional[str] = Query(default=None),
    runtime_id: Optional[str] = Query(default=None, alias="runtimeId"),
    runtime: Optional[str] = Query(default=None),
    strategy_id: Optional[str] = Query(default=None, alias="strategyId"),
    strategy: Optional[str] = Query(default=None),
    pool: Optional[str] = Query(default=None),
    sleeve_id: Optional[str] = Query(default=None, alias="sleeveId"),
    sleeve: Optional[str] = Query(default=None),
    artifact_id: Optional[str] = Query(default=None, alias="artifactId"),
    artifact: Optional[str] = Query(default=None),
    broker_id: Optional[str] = Query(default=None, alias="brokerId"),
    broker: Optional[str] = Query(default=None),
    stage: Optional[str] = Query(default=None),
    period: Optional[str] = Query(default=None),
    as_of: Optional[str] = Query(default=None, alias="asOf"),
):
    """BFF: PM-12 portfolio-book exposure and risk-budget rollup."""
    status = _resolve_param(status)
    risk_policy_ref = _resolve_param(risk_policy_ref)
    capital_pool_id = _resolve_param(capital_pool_id)
    page_token = _resolve_param(page_token)
    page_size = _resolve_param(page_size)
    authorization = _resolve_param(authorization)
    persona_id = _resolve_param(persona_id)
    persona = _resolve_param(persona)
    runtime_id = _resolve_param(runtime_id)
    runtime = _resolve_param(runtime)
    strategy_id = _resolve_param(strategy_id)
    strategy = _resolve_param(strategy)
    pool = _resolve_param(pool)
    sleeve_id = _resolve_param(sleeve_id)
    sleeve = _resolve_param(sleeve)
    artifact_id = _resolve_param(artifact_id)
    artifact = _resolve_param(artifact)
    broker_id = _resolve_param(broker_id)
    broker = _resolve_param(broker)
    stage = _resolve_param(stage)
    period = _resolve_param(period)
    as_of = _resolve_param(as_of)

    identity = _extract_identity(authorization)
    _require_read_role(identity)

    snapshot_at = utc_now()
    sources = _management_portfolio_book_pool_sources(
        status=status,
        risk_policy_ref=risk_policy_ref,
    )
    entries = sources["entries"]

    # Resolve capital pool filter
    resolved_pool_id = capital_pool_id or pool
    if resolved_pool_id:
        requested = {item.strip() for item in resolved_pool_id.split(",") if item.strip()}
        entries = [
            entry
            for entry in entries
            if str(entry.get("pool_id") or entry.get("id") or "") in requested
        ]

    # Apply remaining common filters
    entries = _filter_by_common_identifiers(
        entries,
        persona_id=persona_id, persona=persona,
        runtime_id=runtime_id, runtime=runtime,
        strategy_id=strategy_id, strategy=strategy,
        sleeve_id=sleeve_id, sleeve=sleeve,
        artifact_id=artifact_id, artifact=artifact,
        broker_id=broker_id, broker=broker,
        stage=stage, period=period, as_of=as_of
    )

    total = len(entries)
    page_entries, next_page_token = _page_slice(entries, page_token, page_size)
    page_items = [
        _management_portfolio_book_exposure_item(entry)
        for entry in page_entries
    ]

    risk_budgets = [
        value
        for entry in entries
        for value in [_management_as_float(entry.get("risk_budget"))]
        if value is not None
    ]
    exposures = [
        value
        for entry in entries
        for value in [_management_as_float(entry.get("current_exposure"))]
        if value is not None
    ]
    exposure_runtime_ids = {
        runtime_id
        for entry in entries
        for runtime_id in (entry.get("runtime_ids") or [])
        if str(runtime_id).strip()
    }
    portfolio_telemetry = _management_telemetry_rollup([
        sources["telemetry_by_runtime_id"][runtime_id]
        for runtime_id in sorted(exposure_runtime_ids)
        if runtime_id in sources["telemetry_by_runtime_id"]
    ])
    risk_budget_total = round(sum(risk_budgets), 6) if risk_budgets else None
    current_exposure_total = round(sum(exposures), 6) if exposures else None
    utilization = None
    if current_exposure_total is not None and risk_budget_total not in (None, 0):
        utilization = round(current_exposure_total / risk_budget_total, 6)
    available_budget_total = (
        round(risk_budget_total - current_exposure_total, 6)
        if risk_budget_total is not None and current_exposure_total is not None
        else None
    )
    active_pool_count = len([
        entry for entry in entries
        if str(entry.get("status") or "").strip().lower() in {"active", "ready"}
    ])
    risk_states = [
        _management_exposure_risk_state(
            _management_as_float(entry.get("risk_budget_utilization"))
            if _management_as_float(entry.get("risk_budget_utilization")) is not None
            else (
                round(
                    _management_as_float(entry.get("current_exposure")) / _management_as_float(entry.get("risk_budget")),
                    6,
                )
                if _management_as_float(entry.get("current_exposure")) is not None
                and _management_as_float(entry.get("risk_budget")) not in (None, 0)
                else None
            )
        )
        for entry in entries
    ]
    over_budget_count = len([
        state for state in risk_states if state == "over_budget"
    ])
    near_limit_count = len([
        state for state in risk_states if state == "near_limit"
    ])
    unknown_exposure_count = len([
        state for state in risk_states if state == "unknown"
    ])

    source_surfaces = {
        "capital_pools": _dataset_surface_status("capital_pools", snapshot_at=snapshot_at),
        "persona_bindings": _dataset_surface_status("persona_bindings", snapshot_at=snapshot_at),
        "deployment_plans": _dataset_surface_status("deployment_plans", snapshot_at=snapshot_at),
        "runtime_bindings": _dataset_surface_status("runtime_bindings", snapshot_at=snapshot_at),
        "telemetry_summaries": _dataset_surface_status(
            "telemetry_summaries",
            snapshot_at=snapshot_at,
            has_data=bool(sources["telemetry_by_runtime_id"]) if sources["runtime_bindings"] else None,
            missing_message="Telemetry summaries unavailable for portfolio-book exposure runtimes.",
        ),
    }
    exposure_surface = _aggregate_group_surface(
        "portfolio_book_exposure",
        list(source_surfaces.values()),
        snapshot_at=snapshot_at,
        unavailable_message="Portfolio-book exposure composition has no readable source records.",
        degraded_message="Portfolio-book exposure composition is degraded because one or more source surfaces are degraded.",
    )

    summary = {
        "exposure_count": total,
        "returned_exposure_count": len(page_items),
        "total_pools": total,
        "active_pool_count": active_pool_count,
        "risk_budget_total": risk_budget_total,
        "current_exposure_total": current_exposure_total,
        "available_budget_total": available_budget_total,
        "risk_budget_utilization": utilization,
        "over_budget_count": over_budget_count,
        "near_limit_count": near_limit_count,
        "unknown_exposure_count": unknown_exposure_count,
        "telemetry_runtime_count": portfolio_telemetry["runtime_count"],
        "total_pnl": portfolio_telemetry["total_pnl"],
        "max_drawdown": portfolio_telemetry["max_drawdown"],
        "average_fill_rate": portfolio_telemetry["average_fill_rate"],
        "total_trades": portfolio_telemetry["total_trades"],
        "latest_telemetry_at": portfolio_telemetry["latest_collected_at"],
        "basis": "capital_pool_exposure_with_runtime_telemetry",
    }
    data = {
        "id": "pm12-portfolio-book-exposure",
        "summary": summary,
        "items": page_items,
    }

    return {
        "data": data,
        "page_info": {
            "next_page_token": next_page_token,
            "total": total,
            "page_size": page_size,
        },
        "meta": {
            **_snapshot_meta(snapshot_at),
            "total": total,
            "surfaces": {
                "portfolio_book_exposure": exposure_surface,
                **source_surfaces,
            },
            "composition_sources": [
                "GET /bff/capital-pools",
                "GET /api/v1/persona-capital-bindings",
                "GET /api/v1/deployment-plans",
                "GET /api/v1/runtime-bindings",
                "GET /api/v1/telemetry/{runtime_id}/summary",
            ],
            "policy": "read_only_portfolio_exposure",
        },
    }


@app.get("/bff/management/portfolio-book/holdings")
async def bff_management_portfolio_book_holdings(
    capital_pool_id: Optional[str] = None,
    persona_id: Optional[str] = None,
    runtime_id: Optional[str] = None,
    deployment_stage: Optional[str] = None,
    broker_id: Optional[str] = None,
    status: Optional[str] = None,
    source_status: Optional[str] = None,
    stale_telemetry: Optional[bool] = None,
    risk_state: Optional[str] = None,
    q: Optional[str] = None,
    page_token: Optional[str] = None,
    page_size: int = Query(default=50, ge=1, le=200),
    authorization: Optional[str] = Header(default=None),
):
    """BFF: PM-12 global holdings table composed from runtime and telemetry surfaces."""
    capital_pool_id = _resolve_param(capital_pool_id)
    persona_id = _resolve_param(persona_id)
    runtime_id = _resolve_param(runtime_id)
    deployment_stage = _resolve_param(deployment_stage)
    broker_id = _resolve_param(broker_id)
    status = _resolve_param(status)
    source_status = _resolve_param(source_status)
    stale_telemetry = _resolve_param(stale_telemetry)
    risk_state = _resolve_param(risk_state)
    q = _resolve_param(q)
    page_token = _resolve_param(page_token)
    page_size = _resolve_param(page_size)
    authorization = _resolve_param(authorization)

    identity = _extract_identity(authorization)
    _require_read_role(identity)

    snapshot_at = utc_now()
    runtime_bindings = read_store.list_runtime_bindings(include_market_persona_defaults=True) or []
    deployment_plans = read_store.list_deployment_plans() or []
    bindings = read_store.list_bindings(include_market_persona_defaults=True) or []
    capital_pools = read_store.list_capital_pools(include_market_persona_defaults=True) or []

    plans_by_id = {
        _management_record_id(plan, "plan_id", "id"): plan
        for plan in deployment_plans
        if _management_record_id(plan, "plan_id", "id")
    }
    bindings_by_id = {
        _management_record_id(binding, "binding_id", "id", "persona_capital_binding_id"): binding
        for binding in bindings
        if _management_record_id(binding, "binding_id", "id", "persona_capital_binding_id")
    }
    pools_by_id = {
        _management_record_id(pool, "pool_id", "id"): pool
        for pool in capital_pools
        if _management_record_id(pool, "pool_id", "id")
    }

    telemetry_by_runtime_id: Dict[str, Dict[str, Any]] = {}
    for runtime in runtime_bindings:
        rid = _management_record_id(runtime, "runtime_id", "id", "binding_id")
        if not rid:
            continue
        telemetry = read_store.get_telemetry_summary(rid)
        if telemetry is not None:
            telemetry_by_runtime_id[rid] = telemetry

    holding_contexts: List[Dict[str, Any]] = []
    for runtime in runtime_bindings:
        rid = _management_record_id(runtime, "runtime_id", "id", "binding_id")
        telemetry = telemetry_by_runtime_id.get(rid, {})
        plan = plans_by_id.get(_management_record_id(runtime, "plan_id", "deployment_plan_id"), {})
        plan_binding_ids = [
            str(value).strip()
            for value in (plan.get("binding_ids") or [])
            if str(value).strip()
        ]
        persona_binding_id = (
            _management_record_id(runtime, "persona_capital_binding_id")
            or (plan_binding_ids[0] if plan_binding_ids else "")
        )
        persona_binding = bindings_by_id.get(persona_binding_id, {})
        pool_id = str(
            _management_first_non_empty(
                runtime.get("capital_pool_id"),
                plan.get("capital_pool_id"),
                plan.get("target_pool_id"),
                persona_binding.get("capital_pool_id"),
            )
            or ""
        )
        capital_pool = pools_by_id.get(pool_id, {})
        position_records = _management_position_records(telemetry)
        positions = position_records or [{}]
        position_source_count = len(position_records)
        for index, position in enumerate(positions):
            metadata = _management_portfolio_holding_metadata(
                runtime,
                position,
                position_index=index,
                plan=plan,
                persona_binding=persona_binding,
                telemetry=telemetry,
                position_source_count=position_source_count,
            )
            holding_contexts.append({
                "runtime": runtime,
                "position": position,
                "position_index": index,
                "position_source_count": position_source_count,
                "plan": plan,
                "persona_binding": persona_binding,
                "capital_pool": capital_pool,
                "telemetry": telemetry,
                "metadata": metadata,
            })

    if capital_pool_id:
        requested = {item.strip() for item in capital_pool_id.split(",") if item.strip()}
        holding_contexts = [
            context for context in holding_contexts
            if str((context.get("metadata") or {}).get("capital_pool_id") or "") in requested
        ]
    if persona_id:
        requested = {item.strip() for item in persona_id.split(",") if item.strip()}
        holding_contexts = [
            context for context in holding_contexts
            if str((context.get("metadata") or {}).get("persona_id") or "") in requested
        ]
    if runtime_id:
        requested = {item.strip() for item in runtime_id.split(",") if item.strip()}
        holding_contexts = [
            context for context in holding_contexts
            if str((context.get("metadata") or {}).get("runtime_id") or "") in requested
        ]
    if deployment_stage:
        requested = {item.strip().lower() for item in deployment_stage.split(",") if item.strip()}
        holding_contexts = [
            context for context in holding_contexts
            if str((context.get("metadata") or {}).get("deployment_stage") or "").lower() in requested
        ]
    if broker_id:
        requested = {item.strip() for item in broker_id.split(",") if item.strip()}
        holding_contexts = [
            context for context in holding_contexts
            if str((context.get("metadata") or {}).get("broker_id") or "") in requested
        ]
    if status:
        requested = {item.strip().lower() for item in status.split(",") if item.strip()}
        holding_contexts = [
            context for context in holding_contexts
            if str((context.get("metadata") or {}).get("status") or "").lower() in requested
        ]
    if source_status:
        requested = {item.strip().lower() for item in source_status.split(",") if item.strip()}
        holding_contexts = [
            context for context in holding_contexts
            if str((context.get("metadata") or {}).get("source_status") or "").lower() in requested
        ]
    if stale_telemetry is not None:
        holding_contexts = [
            context for context in holding_contexts
            if bool((context.get("metadata") or {}).get("telemetry_stale")) is stale_telemetry
        ]
    if risk_state:
        requested = {item.strip().lower() for item in risk_state.split(",") if item.strip()}
        holding_contexts = [
            context for context in holding_contexts
            if str((context.get("metadata") or {}).get("risk_state") or "").lower() in requested
        ]
    if q:
        needle = q.strip().lower()
        holding_contexts = [
            context
            for context in holding_contexts
            if needle in " ".join(
                str(value or "").lower()
                for value in (
                    (context.get("metadata") or {}).get("holding_id"),
                    (context.get("metadata") or {}).get("symbol"),
                    (context.get("metadata") or {}).get("runtime_id"),
                    (context.get("metadata") or {}).get("capital_pool_id"),
                    (context.get("metadata") or {}).get("persona_id"),
                    (context.get("metadata") or {}).get("strategy_id"),
                    (context.get("metadata") or {}).get("artifact_id"),
                    (context.get("metadata") or {}).get("broker_id"),
                    (context.get("metadata") or {}).get("risk_state"),
                )
            )
        ]

    holding_contexts = sorted(
        holding_contexts,
        key=lambda context: (
            str((context.get("metadata") or {}).get("capital_pool_id") or ""),
            str((context.get("metadata") or {}).get("runtime_id") or ""),
            str((context.get("metadata") or {}).get("symbol") or ""),
            str((context.get("metadata") or {}).get("holding_id") or ""),
        ),
    )
    total = len(holding_contexts)
    page_contexts, next_page_token = _page_slice(holding_contexts, page_token, page_size)
    page_items = [
        _management_portfolio_holding_entry(
            context["runtime"],
            context["position"],
            position_index=context["position_index"],
            plan=context["plan"],
            persona_binding=context["persona_binding"],
            capital_pool=context["capital_pool"],
            telemetry=context["telemetry"],
            position_source_count=int(context.get("position_source_count") or 0),
        )
        for context in page_contexts
    ]
    holding_metadata = [
        context["metadata"]
        for context in holding_contexts
        if isinstance(context.get("metadata"), dict)
    ]
    incidents = [
        incident
        for incident in (_management_portfolio_incident(item) for item in holding_metadata)
        if incident is not None
    ]
    active_statuses = {"active", "running", "healthy", "bound"}
    summary = {
        "holding_count": total,
        "returned_holding_count": len(page_items),
        "source_row_count": sum(int(item.get("source_row_count") or 0) for item in holding_metadata),
        "active_holding_count": len([
            item for item in holding_metadata if str(item.get("status") or "").lower() in active_statuses
        ]),
        "paper_holding_count": len([
            item for item in holding_metadata if str(item.get("deployment_stage") or "").lower() == "paper"
        ]),
        "live_holding_count": len([
            item for item in holding_metadata if str(item.get("deployment_stage") or "").lower() == "live"
        ]),
        "runtime_count": len({
            str(item.get("runtime_id") or "")
            for item in holding_metadata
            if str(item.get("runtime_id") or "")
        }),
        "telemetry_runtime_count": len({
            str(item.get("runtime_id") or "")
            for item in holding_metadata
            if item.get("telemetry_available")
        }),
        "stale_row_count": len([
            item for item in holding_metadata if item.get("telemetry_stale")
        ]),
        "missing_binding_count": len([
            item for item in holding_metadata
            if any(issue.get("code") == "MISSING_PERSONA_BINDING" for issue in (item.get("source_issues") or []))
        ]),
        "degraded_source_count": len([
            item for item in holding_metadata
            if str(item.get("source_status") or "").lower() in {"degraded", "stale", "unavailable"}
        ]),
        "incident_count": len(incidents),
        "total_notional": _management_sum_numeric(holding_metadata, "notional"),
        "total_market_value": _management_sum_numeric(holding_metadata, "market_value"),
        "total_unrealized_pnl": _management_sum_numeric(holding_metadata, "unrealized_pnl"),
        "total_realized_pnl": _management_sum_numeric(holding_metadata, "realized_pnl"),
        "total_pnl": _management_sum_numeric(holding_metadata, "total_pnl"),
        "latest_mark_at": _management_latest_timestamp(holding_metadata, "last_mark_at"),
        "source_status_counts": _management_count_by(holding_metadata, "source_status"),
        "risk_state_counts": _management_count_by(holding_metadata, "risk_state"),
        "by_stage": _management_count_by(holding_metadata, "deployment_stage"),
        "by_broker": _management_count_by(holding_metadata, "broker_id"),
    }
    summary["source_coverage"] = {
        "source_row_count": summary["source_row_count"],
        "runtime_count": summary["runtime_count"],
        "telemetry_runtime_count": summary["telemetry_runtime_count"],
        "stale_row_count": summary["stale_row_count"],
        "missing_binding_count": summary["missing_binding_count"],
        "degraded_source_count": summary["degraded_source_count"],
    }

    surfaces = {
        "portfolio_book_holdings": _composed_surface_status(
            snapshot_at=snapshot_at,
            available=bool(runtime_bindings),
            missing_message="Portfolio-book holdings composition has no runtime binding source records.",
        ),
        "runtime_bindings": _dataset_surface_status("runtime_bindings", snapshot_at=snapshot_at),
        "telemetry_summaries": _dataset_surface_status(
            "telemetry_summaries",
            snapshot_at=snapshot_at,
            has_data=bool(telemetry_by_runtime_id) if runtime_bindings else None,
            missing_message="Telemetry summaries unavailable for portfolio-book holdings runtimes.",
        ),
        "deployment_plans": _dataset_surface_status("deployment_plans", snapshot_at=snapshot_at),
        "persona_bindings": _dataset_surface_status("persona_bindings", snapshot_at=snapshot_at),
        "capital_pools": _dataset_surface_status("capital_pools", snapshot_at=snapshot_at),
    }
    if any(
        surface.get("status") == "unavailable"
        for key, surface in surfaces.items()
        if key != "portfolio_book_holdings"
    ):
        surfaces["portfolio_book_holdings"] = _composed_surface_status(
            snapshot_at=snapshot_at,
            available=False,
            missing_message="Portfolio-book holdings composition is degraded because one or more source surfaces are unavailable.",
        )
    elif incidents and surfaces["portfolio_book_holdings"].get("status") == "ok":
        surfaces["portfolio_book_holdings"] = _composed_surface_status(
            snapshot_at=snapshot_at,
            available=False,
            missing_message="Portfolio-book holdings composition has row-level coverage incidents.",
        )

    meta = _snapshot_meta(snapshot_at)
    meta["surfaces"] = surfaces
    meta["total"] = total
    meta["incidents"] = incidents
    meta["filters"] = {
        "capital_pool_id": capital_pool_id,
        "persona_id": persona_id,
        "runtime_id": runtime_id,
        "deployment_stage": deployment_stage,
        "broker_id": broker_id,
        "status": status,
        "source_status": source_status,
        "stale_telemetry": stale_telemetry,
        "risk_state": risk_state,
        "q": q,
    }
    meta["composition_sources"] = [
        "GET /bff/runtimes",
        "GET /api/v1/telemetry/{runtime_id}/summary",
        "GET /bff/deployments",
        "GET /bff/capital-pools",
        "GET /bff/personas",
    ]
    meta["summary"] = {
        "source_mode": "bff_composed",
        "task": "BFF-PM12-002",
    }

    return {
        "data": {
            "summary": summary,
            "items": page_items,
        },
        "page_info": {"next_page_token": next_page_token, "total": total},
        "meta": meta,
    }


@app.get("/bff/management/portfolio-book/positions")
async def bff_management_portfolio_book_positions(
    capital_pool_id: Optional[str] = None,
    persona_id: Optional[str] = None,
    runtime_id: Optional[str] = None,
    deployment_stage: Optional[str] = None,
    broker_id: Optional[str] = None,
    status: Optional[str] = None,
    source_status: Optional[str] = None,
    stale_telemetry: Optional[bool] = None,
    risk_state: Optional[str] = None,
    q: Optional[str] = None,
    page_token: Optional[str] = None,
    page_size: int = Query(default=50, ge=1, le=200),
    authorization: Optional[str] = Header(default=None),
):
    """BFF: PM-12 global positions table composed from runtime and telemetry surfaces."""
    capital_pool_id = _resolve_param(capital_pool_id)
    persona_id = _resolve_param(persona_id)
    runtime_id = _resolve_param(runtime_id)
    deployment_stage = _resolve_param(deployment_stage)
    broker_id = _resolve_param(broker_id)
    status = _resolve_param(status)
    source_status = _resolve_param(source_status)
    stale_telemetry = _resolve_param(stale_telemetry)
    risk_state = _resolve_param(risk_state)
    q = _resolve_param(q)
    page_token = _resolve_param(page_token)
    page_size = _resolve_param(page_size)
    authorization = _resolve_param(authorization)

    holdings_payload = await bff_management_portfolio_book_holdings(
        capital_pool_id=capital_pool_id,
        persona_id=persona_id,
        runtime_id=runtime_id,
        deployment_stage=deployment_stage,
        broker_id=broker_id,
        status=status,
        source_status=source_status,
        stale_telemetry=stale_telemetry,
        risk_state=risk_state,
        q=q,
        page_token=page_token,
        page_size=page_size,
        authorization=authorization,
    )

    positions: List[Dict[str, Any]] = []
    for item in _management_payload_items(holdings_payload):
        if not isinstance(item, dict):
            continue
        position = dict(item)
        position_id = str(
            _management_first_non_empty(
                position.get("position_id"),
                position.get("holding_id"),
                position.get("id"),
            )
            or ""
        )
        position["id"] = position_id
        position["position_id"] = position_id
        positions.append(position)

    holding_summary = dict(_management_payload_summary(holdings_payload) or {})
    summary = {
        "position_count": holding_summary.get("holding_count", len(positions)),
        "returned_position_count": holding_summary.get("returned_holding_count", len(positions)),
        "source_row_count": holding_summary.get("source_row_count", len(positions)),
        "active_position_count": holding_summary.get("active_holding_count", 0),
        "paper_position_count": holding_summary.get("paper_holding_count", 0),
        "live_position_count": holding_summary.get("live_holding_count", 0),
        "runtime_count": holding_summary.get("runtime_count", 0),
        "telemetry_runtime_count": holding_summary.get("telemetry_runtime_count", 0),
        "stale_row_count": holding_summary.get("stale_row_count", 0),
        "missing_binding_count": holding_summary.get("missing_binding_count", 0),
        "degraded_source_count": holding_summary.get("degraded_source_count", 0),
        "incident_count": holding_summary.get("incident_count", 0),
        "total_notional": holding_summary.get("total_notional"),
        "total_market_value": holding_summary.get("total_market_value"),
        "total_unrealized_pnl": holding_summary.get("total_unrealized_pnl"),
        "total_realized_pnl": holding_summary.get("total_realized_pnl"),
        "total_pnl": holding_summary.get("total_pnl"),
        "latest_mark_at": holding_summary.get("latest_mark_at"),
        "source_status_counts": holding_summary.get("source_status_counts") or {},
        "risk_state_counts": holding_summary.get("risk_state_counts") or {},
        "by_stage": holding_summary.get("by_stage") or {},
        "by_broker": holding_summary.get("by_broker") or {},
        "source_coverage": holding_summary.get("source_coverage") or {},
    }

    meta = dict(holdings_payload.get("meta") or {})
    surfaces = dict(meta.get("surfaces") or {})
    holding_surface = surfaces.pop("portfolio_book_holdings", None)
    if holding_surface:
        surfaces["portfolio_book_positions"] = dict(holding_surface)
    else:
        surfaces["portfolio_book_positions"] = _composed_surface_status(
            snapshot_at=str(meta.get("snapshot_at") or utc_now()),
            available=bool(positions),
            missing_message="Portfolio-book positions composition has no runtime binding source records.",
        )
    meta["surfaces"] = surfaces
    meta["total"] = summary["position_count"]
    meta["summary"] = {
        "source_mode": "bff_composed",
        "task": "BFF-PM12-DELTA-005",
    }

    page_info = dict(holdings_payload.get("page_info") or {})
    page_info["page_size"] = page_size

    return {
        "data": {
            "summary": summary,
            "items": positions,
        },
        "page_info": page_info,
        "meta": meta,
    }


def _sort_records_latest_first(
    records: List[Dict[str, Any]],
    fields: tuple[str, ...],
) -> List[Dict[str, Any]]:
    return sorted(
        records,
        key=lambda item: next(
            (str(item.get(field) or "") for field in fields if item.get(field)),
            "",
        ),
        reverse=True,
    )


def _persona_fleet_runtime_matches(
    runtime_binding: Dict[str, Any],
    *,
    binding_ids: set[str],
    capital_pool_ids: set[str],
    runtime_refs: set[str],
) -> bool:
    runtime_ids = {
        str(runtime_binding.get(key) or "").strip()
        for key in ("id", "binding_id", "runtime_binding_id", "runtime_id")
    }
    runtime_ids.discard("")
    if runtime_ids.intersection(runtime_refs):
        return True

    persona_binding_id = str(runtime_binding.get("persona_capital_binding_id") or "").strip()
    if persona_binding_id and persona_binding_id in binding_ids:
        return True

    capital_pool_id = str(runtime_binding.get("capital_pool_id") or "").strip()
    if capital_pool_id and capital_pool_id in capital_pool_ids:
        return True

    plan_id = str(runtime_binding.get("plan_id") or runtime_binding.get("deployment_plan_id") or "").strip()
    if plan_id:
        plan = read_store.get_deployment_plan(plan_id) or {}
        plan_binding_ids = {
            str(value).strip()
            for value in (plan.get("binding_ids") or [])
            if str(value).strip()
        }
        if plan_binding_ids.intersection(binding_ids):
            return True
        plan_pool_id = str(plan.get("capital_pool_id") or plan.get("target_pool_id") or "").strip()
        if plan_pool_id and plan_pool_id in capital_pool_ids:
            return True

    return False


def _project_persona_fleet_health(
    *,
    persona: Dict[str, Any],
    runtime_bindings: List[Dict[str, Any]],
    telemetry_summaries: List[Dict[str, Any]],
    active_incidents: List[Dict[str, Any]],
) -> Dict[str, Any]:
    reasons: List[str] = []
    lifecycle = str(persona.get("lifecycle_state") or persona.get("state") or "").lower()
    if lifecycle and not _is_persona_lifecycle_operational(lifecycle):
        reasons.append("persona_lifecycle_not_active")
    if not runtime_bindings:
        reasons.append("no_runtime_binding")
    if active_incidents:
        reasons.append("active_incident")

    latest_telemetry = telemetry_summaries[0] if telemetry_summaries else {}
    drawdown = latest_telemetry.get("drawdown")
    pnl = latest_telemetry.get("pnl")
    try:
        if drawdown is not None and float(drawdown) >= 0.10:
            reasons.append("drawdown_threshold")
    except (TypeError, ValueError):
        pass
    try:
        if pnl is not None and float(pnl) <= -0.05:
            reasons.append("negative_pnl")
    except (TypeError, ValueError):
        pass

    runtime_statuses = {
        str(binding.get("status") or "").strip().lower()
        for binding in runtime_bindings
        if str(binding.get("status") or "").strip()
    }
    unhealthy_runtime_statuses = sorted(runtime_statuses.difference({"active", "ready", "running", "idle"}))
    if unhealthy_runtime_statuses:
        reasons.append("runtime_status_attention")

    status = "healthy"
    severity = "low"
    if active_incidents or "drawdown_threshold" in reasons:
        status = "critical"
        severity = "high"
    elif reasons:
        status = "degraded"
        severity = "medium"

    score = max(0, 100 - (35 if status == "critical" else 0) - (15 * max(len(reasons) - 1, 0)))
    return {
        "status": status,
        "severity": severity,
        "score": score,
        "reasons": reasons,
        "runtime_statuses": sorted(runtime_statuses),
        "latest_telemetry_at": latest_telemetry.get("collected_at"),
        "active_incident_count": len(active_incidents),
    }


def _project_persona_fleet_item(
    raw_persona: Dict[str, Any],
    *,
    all_runtime_bindings: List[Dict[str, Any]],
    all_incidents: List[Dict[str, Any]],
    all_evolution_decisions: List[Dict[str, Any]],
) -> Dict[str, Any]:
    persona_id = str(raw_persona.get("persona_id") or raw_persona.get("id") or "").strip()
    overlay = _PERSONA_BFF_OVERLAY.get(persona_id)
    routed = _routed_strategies_for_persona(persona_id)
    persona_dto = _project_persona_dto(raw_persona, overlay=overlay, routed_strategies=routed)

    bindings = list(read_store.get_bindings_for_persona(persona_id) or [])
    binding_ids = {
        str(binding.get("id") or binding.get("binding_id") or "").strip()
        for binding in bindings
        if str(binding.get("id") or binding.get("binding_id") or "").strip()
    }
    capital_pool_ids = {
        str(binding.get("capital_pool_id") or "").strip()
        for binding in bindings
        if str(binding.get("capital_pool_id") or "").strip()
    }

    sessions = list(read_store.get_sessions_for_persona(persona_id) or [])
    runtime_refs = {
        str(session.get("runtime_binding_id") or session.get("runtime_id") or "").strip()
        for session in sessions
        if str(session.get("runtime_binding_id") or session.get("runtime_id") or "").strip()
    }
    runtime_bindings = [
        binding
        for binding in all_runtime_bindings
        if _persona_fleet_runtime_matches(
            binding,
            binding_ids=binding_ids,
            capital_pool_ids=capital_pool_ids,
            runtime_refs=runtime_refs,
        )
    ]
    runtime_ids = {
        str(binding.get("runtime_id") or binding.get("runtime_binding_id") or binding.get("id") or "").strip()
        for binding in runtime_bindings
        if str(binding.get("runtime_id") or binding.get("runtime_binding_id") or binding.get("id") or "").strip()
    }
    artifact_ids = {
        str(binding.get("artifact_id") or "").strip()
        for binding in runtime_bindings
        if str(binding.get("artifact_id") or "").strip()
    }

    telemetry_summaries = [
        summary
        for runtime_id in sorted(runtime_ids)
        for summary in [read_store.get_telemetry_summary(runtime_id)]
        if summary
    ]
    telemetry_summaries = _sort_records_latest_first(telemetry_summaries, ("collected_at", "updated_at", "created_at"))
    latest_telemetry = telemetry_summaries[0] if telemetry_summaries else None

    teaching_sessions = _sort_records_latest_first(
        list(read_store.get_teaching_sessions_for_persona(persona_id) or []),
        ("started_at", "created_at", "updated_at"),
    )
    latest_training = teaching_sessions[0] if teaching_sessions else None

    active_incidents = [
        incident
        for incident in all_incidents
        if str(incident.get("status") or "").lower() in {"open", "active", "investigating"}
        and (
            str(incident.get("persona_id") or "").strip() == persona_id
            or str(incident.get("persona_capital_binding_id") or "").strip() in binding_ids
            or str(incident.get("capital_pool_id") or incident.get("affected_pool_id") or "").strip() in capital_pool_ids
            or str(incident.get("runtime_id") or "").strip() in runtime_ids
        )
    ]
    incident_ids = {
        str(incident.get("incident_id") or incident.get("id") or "").strip()
        for incident in all_incidents
        if str(incident.get("incident_id") or incident.get("id") or "").strip()
        and (
            str(incident.get("persona_id") or "").strip() == persona_id
            or str(incident.get("persona_capital_binding_id") or "").strip() in binding_ids
            or str(incident.get("capital_pool_id") or incident.get("affected_pool_id") or "").strip() in capital_pool_ids
            or str(incident.get("runtime_id") or "").strip() in runtime_ids
        )
    }
    evolution_decisions = [
        decision
        for decision in all_evolution_decisions
        if str(decision.get("target_id") or "").strip() == persona_id
        or str(decision.get("artifact_id") or "").strip() in artifact_ids
        or str(decision.get("incident_ref") or decision.get("linked_incident_id") or "").strip() in incident_ids
    ]
    evolution_decisions = _sort_records_latest_first(evolution_decisions, ("updated_at", "created_at"))

    capital_pools = [
        pool
        for pool_id in sorted(capital_pool_ids)
        for pool in [read_store.get_capital_pool(pool_id)]
        if pool
    ]
    enriched_bindings = [
        {
            **binding,
            "capital_pool": read_store.get_capital_pool(str(binding.get("capital_pool_id") or "")),
        }
        for binding in bindings
    ]
    health = _project_persona_fleet_health(
        persona=raw_persona,
        runtime_bindings=runtime_bindings,
        telemetry_summaries=telemetry_summaries,
        active_incidents=active_incidents,
    )
    allowed_actions = read_store.get_persona_allowed_actions(persona_id) or {}

    telemetry_summary = {
        "latest": latest_telemetry,
        "runtime_count": len(runtime_bindings),
        "covered_runtime_count": len(telemetry_summaries),
        "summaries": telemetry_summaries,
    }
    training_summary = {
        "session_count": len(teaching_sessions),
        "active_session_count": len([
            session for session in teaching_sessions
            if str(session.get("status") or "").lower() == "active"
        ]),
        "completed_session_count": len([
            session for session in teaching_sessions
            if str(session.get("status") or "").lower() == "completed"
        ]),
        "latest_session": latest_training,
    }
    evolution_summary = {
        "decision_count": len(evolution_decisions),
        "pending_decision_count": len([
            decision for decision in evolution_decisions
            if str(decision.get("status") or decision.get("decision_state") or "").lower()
            in {"pending", "in_review", "reviewed", "under_review"}
        ]),
        "latest_decision": evolution_decisions[0] if evolution_decisions else None,
        "decisions": evolution_decisions,
    }

    return {
        "id": persona_id,
        "persona_id": persona_id,
        "persona": persona_dto,
        "health": health,
        "bindings": enriched_bindings,
        "capitalPools": capital_pools,
        "capital_pools": capital_pools,
        "runtimeBindings": runtime_bindings,
        "runtime_bindings": runtime_bindings,
        "telemetrySummary": telemetry_summary,
        "telemetry_summary": telemetry_summary,
        "training": training_summary,
        "evolution": evolution_summary,
        "sessions": sessions,
        "activeIncidents": active_incidents,
        "active_incidents": active_incidents,
        "allowedActions": allowed_actions,
    }


def _project_persona_fleet_payload(
    *,
    state: Optional[str],
    health: Optional[str],
    page_token: Optional[str],
    page_size: int,
) -> Dict[str, Any]:
    snapshot_at = utc_now()
    personas = _list_persona_records()
    runtime_bindings = list(read_store.list_runtime_bindings() or [])
    incidents = list(read_store.list_incidents() or [])
    evolution_decisions = list(read_store.list_evolution_decisions() or [])
    items = [
        _project_persona_fleet_item(
            persona,
            all_runtime_bindings=runtime_bindings,
            all_incidents=incidents,
            all_evolution_decisions=evolution_decisions,
        )
        for persona in personas
    ]

    if state:
        requested_states = {token.strip().lower() for token in state.split(",") if token.strip()}
        items = [
            item for item in items
            if str((item.get("persona") or {}).get("state") or "").lower() in requested_states
        ]
    if health:
        requested_health = {token.strip().lower() for token in health.split(",") if token.strip()}
        items = [
            item for item in items
            if str((item.get("health") or {}).get("status") or "").lower() in requested_health
        ]

    items = sorted(
        items,
        key=lambda item: (
            str((item.get("health") or {}).get("severity") or ""),
            str((item.get("persona") or {}).get("updatedAt") or ""),
            str(item.get("id") or ""),
        ),
        reverse=True,
    )
    total = len(items)
    page_items, next_page_token = _page_slice(items, page_token, page_size)

    source_surfaces = {
        "personas": _dataset_surface_status("personas", snapshot_at=snapshot_at),
        "persona_bindings": _dataset_surface_status("persona_bindings", snapshot_at=snapshot_at),
        "runtime_bindings": _dataset_surface_status("runtime_bindings", snapshot_at=snapshot_at),
        "telemetry_summaries": _dataset_surface_status("telemetry_summaries", snapshot_at=snapshot_at),
        "teaching_sessions": _dataset_surface_status("teaching_sessions", snapshot_at=snapshot_at),
        "evolution_decisions": _dataset_surface_status("evolution_decisions", snapshot_at=snapshot_at),
    }
    persona_fleet_surface = _aggregate_group_surface(
        "persona_fleet",
        list(source_surfaces.values()),
        snapshot_at=snapshot_at,
        unavailable_message="Persona fleet aggregate unavailable.",
        degraded_message="Persona fleet aggregate is degraded because one or more source surfaces are degraded.",
    )

    summary = {
        "total_personas": total,
        "returned_personas": len(page_items),
        "critical_personas": len([item for item in items if item["health"]["status"] == "critical"]),
        "degraded_personas": len([item for item in items if item["health"]["status"] == "degraded"]),
        "healthy_personas": len([item for item in items if item["health"]["status"] == "healthy"]),
        "bound_personas": len([item for item in items if item["bindings"]]),
        "runtime_bound_personas": len([item for item in items if item["runtimeBindings"]]),
    }
    return {
        "data": page_items,
        "items": page_items,
        "summary": summary,
        "page_info": {
            "next_page_token": next_page_token,
            "total": total,
            "page_size": page_size,
        },
        "meta": {
            **_snapshot_meta(snapshot_at),
            "surfaces": {
                "persona_fleet": persona_fleet_surface,
                **source_surfaces,
            },
        },
    }


# ---------------- /bff/management aggregate routes ----------------

_HUMAN_INBOX_OPEN_APPROVAL_STATES = {
    "pending",
    "in_review",
    "under_review",
    "reviewed",
    "proposed",
}
_HUMAN_INBOX_OPEN_INTERVENTION_STATUSES = {"pending", "escalated"}
_HUMAN_INBOX_OPEN_GOVERNANCE_STATUSES = {
    "pending",
    "open",
    "in_review",
    "under_review",
    "reviewed",
}
_HUMAN_INBOX_OPEN_SENTINEL_STATUSES = {"pending", "open", "active", "escalated"}
_HUMAN_INBOX_PRIORITY_RANK = {
    "critical": 4,
    "high": 3,
    "medium": 2,
    "low": 1,
    "unknown": 0,
}
_HIQ_BACKLOG_DEFAULT_KINDS = {"hiq_sentinel", "risk_breach"}
_HIQ_BACKLOG_DEFAULT_STATUSES = {"pending", "escalated", "open", "active", "in_progress"}


def _human_inbox_csv_filter(value: Optional[str]) -> Optional[set[str]]:
    if not value:
        return None
    requested = {part.strip().lower() for part in value.split(",") if part.strip()}
    return requested or None


def _human_inbox_priority(value: Any, *, fallback: str = "medium") -> str:
    normalized = str(value or "").strip().lower()
    if normalized in _HUMAN_INBOX_PRIORITY_RANK:
        return normalized
    if normalized in {"sev1", "p0"}:
        return "critical"
    if normalized in {"sev2", "p1"}:
        return "high"
    if normalized in {"sev3", "p2"}:
        return "medium"
    return fallback


def _human_inbox_attach_common_fields(
    projected: Dict[str, Any],
    *,
    inbox_type: str,
    source_dataset: str,
    risk_level: str,
    created_at: Optional[str],
    updated_at: Optional[str],
    href: str,
    source_record: Dict[str, Any],
) -> Dict[str, Any]:
    projected.setdefault("kind", inbox_type)
    projected["inbox_type"] = inbox_type
    projected["sourceDataset"] = source_dataset
    projected["source_dataset"] = source_dataset
    projected["riskLevel"] = risk_level
    projected["risk_level"] = risk_level
    projected["createdAt"] = created_at
    projected["created_at"] = created_at
    projected["updatedAt"] = updated_at
    projected["updated_at"] = updated_at
    projected["href"] = href
    projected.setdefault("route", href)
    return projected


def _human_inbox_action_state(status: str, open_statuses: set[str]) -> str:
    return "pending" if status in open_statuses else "resolved"


def _human_inbox_governance_review_item(item: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    item_id = _management_record_id(item, "item_id", "id", "review_id")
    if not item_id:
        return None
    review_type = str(item.get("item_type") or item.get("review_type") or "GovernanceReview").strip()
    status = str(item.get("status") or item.get("governance_outcome") or "pending").strip().lower() or "pending"
    risk_level = str(item.get("risk_level") or "unknown").strip().lower() or "unknown"
    priority = _human_inbox_priority(item.get("priority") or risk_level, fallback="medium")
    created_at = item.get("submitted_at") or item.get("created_at")
    updated_at = item.get("updated_at") or created_at
    route = f"{_GOVERNANCE_REVIEW_QUEUE_ROUTE}?item={item_id}"
    action_state = _human_inbox_action_state(status, _HUMAN_INBOX_OPEN_GOVERNANCE_STATUSES)
    projected = {
        "id": f"governance_review:{item_id}",
        "inbox_id": f"governance_review:{item_id}",
        "inboxType": "governance_review",
        "source_type": "governance_review",
        "source_id": item_id,
        "review_item_id": item_id,
        "title": item.get("title") or f"Governance review: {review_type}",
        "summary": item.get("summary") or item.get("description") or "Governance review awaiting human action.",
        "priority": priority,
        "risk_level": risk_level,
        "status": status,
        "action_state": action_state,
        "created_at": created_at,
        "updated_at": updated_at,
        "submitted_by": item.get("submitted_by"),
        "target": {
            "type": review_type,
            "id": item.get("target_id") or item.get("plan_id") or item.get("artifact_id") or item_id,
        },
        "route": route,
        "bff_detail_path": route,
        "allowedActions": _management_json_clone(item.get("allowedActions") or {
            "canReview": action_state == "pending",
            "canRequestRevision": action_state == "pending",
        }),
    }
    return _human_inbox_attach_common_fields(
        projected,
        inbox_type="governance_review",
        source_dataset="governance_review_queue_items",
        risk_level=risk_level,
        created_at=created_at,
        updated_at=updated_at,
        href=route,
        source_record=item,
    )


def _human_inbox_approval_item(item: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    decision_id = _management_record_id(item, "decision_id", "id", "approval_decision_id")
    if not decision_id:
        return None
    decision_type = str(item.get("decision_type") or item.get("target_type") or "ApprovalDecision").strip()
    risk_level = str(item.get("risk_level") or "unknown").strip().lower() or "unknown"
    state = str(item.get("decision_state") or item.get("state") or "pending").strip().lower() or "pending"
    context = item.get("decision_context") if isinstance(item.get("decision_context"), dict) else {}
    governance_chain = context.get("governance_chain") if isinstance(context.get("governance_chain"), dict) else {}
    priority = _human_inbox_priority(item.get("priority") or risk_level, fallback="medium")
    risk_summary = str(context.get("risk_summary") or "").strip()
    target_type = str(governance_chain.get("target_type") or decision_type or "ApprovalDecision").strip()
    target_id = str(governance_chain.get("target_id") or governance_chain.get("linked_review_item_id") or "").strip()
    action_state = "pending" if state in _HUMAN_INBOX_OPEN_APPROVAL_STATES else "resolved"
    route = f"/management/approvals?approval={decision_id}"
    created_at = item.get("submitted_at")
    updated_at = item.get("updated_at") or created_at
    projected = {
        "id": f"approval:{decision_id}",
        "inbox_id": f"approval:{decision_id}",
        "inboxType": "approval",
        "source_type": "approval",
        "source_id": decision_id,
        "approval_decision_id": decision_id,
        "title": item.get("title") or f"{decision_type} approval",
        "summary": risk_summary or "Approval decision awaiting human review.",
        "priority": priority,
        "risk_level": risk_level,
        "status": state,
        "action_state": action_state,
        "created_at": created_at,
        "updated_at": updated_at,
        "submitted_by": item.get("submitted_by"),
        "target": {
            "type": target_type,
            "id": target_id or None,
        },
        "route": route,
        "bff_detail_path": f"/bff/approvals/{decision_id}",
        "decision_context": json.loads(json.dumps(context)),
        "allowedActions": json.loads(json.dumps(item.get("allowedActions") or {})),
    }
    return _human_inbox_attach_common_fields(
        projected,
        inbox_type="approval",
        source_dataset="approval_queue_items",
        risk_level=risk_level,
        created_at=created_at,
        updated_at=updated_at,
        href=route,
        source_record=item,
    )


def _human_inbox_intervention_item(record: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    intervention_id = _management_record_id(record, "intervention_id", "id")
    if not intervention_id:
        return None
    status = str(record.get("status") or "pending").strip().lower() or "pending"
    kind = str(record.get("kind") or "hiq_sentinel").strip().lower() or "hiq_sentinel"
    priority = _human_inbox_priority(
        record.get("priority") or record.get("severity") or record.get("risk_level"),
        fallback="critical" if status == "pending" and kind == "hiq_sentinel" else "high",
    )
    action_state = "pending" if status in _HUMAN_INBOX_OPEN_INTERVENTION_STATUSES else "resolved"
    raw_allowed_actions = record.get("allowedActions") if isinstance(record.get("allowedActions"), dict) else {}
    allowed_actions = {
        "canClaim": status == "pending",
        "canRelease": status == "claimed",
        "canEscalate": status == "pending",
        "canDecide": status in _HUMAN_INBOX_OPEN_INTERVENTION_STATUSES,
        "canRemediate": status in _HUMAN_INBOX_OPEN_INTERVENTION_STATUSES,
        **raw_allowed_actions,
    }
    route = f"/management/interventions?intervention={intervention_id}"
    created_at = record.get("triggered_at") or record.get("created_at")
    updated_at = record.get("remediated_at") or record.get("updated_at") or created_at
    projected = {
        "id": f"intervention:{intervention_id}",
        "inbox_id": f"intervention:{intervention_id}",
        "inboxType": "intervention",
        "source_type": "intervention",
        "source_id": intervention_id,
        "intervention_id": intervention_id,
        "title": record.get("title") or f"{kind.replace('_', ' ').title()} intervention",
        "summary": record.get("description") or "Human intervention is required before the loop can continue.",
        "priority": priority,
        "risk_level": str(record.get("risk_level") or priority).strip().lower(),
        "status": status,
        "action_state": action_state,
        "created_at": created_at,
        "updated_at": updated_at,
        "triggered_by": record.get("triggered_by"),
        "target": {
            "type": record.get("target_type"),
            "id": record.get("target_id"),
        },
        "route": route,
        "bff_detail_path": f"/bff/v5/interventions/{intervention_id}",
        "remediation_context": {
            "kind": kind,
            "remediation_action": record.get("remediation_action"),
            "two_man_signature_id": record.get("two_man_signature_id"),
            "correlation_id": record.get("correlation_id"),
        },
        "allowedActions": json.loads(json.dumps(allowed_actions)),
    }
    return _human_inbox_attach_common_fields(
        projected,
        inbox_type="intervention",
        source_dataset="v5_interventions",
        risk_level=str(record.get("risk_level") or priority).strip().lower(),
        created_at=created_at,
        updated_at=updated_at,
        href=route,
        source_record=record,
    )


def _human_inbox_sentinel_item(record: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    finding_id = _management_record_id(record, "id", "finding_id", "incident_id")
    if not finding_id:
        return None
    status = str(record.get("status") or "open").strip().lower() or "open"
    if status not in _HUMAN_INBOX_OPEN_SENTINEL_STATUSES:
        return None
    kind = str(record.get("kind") or "sentinel_finding").strip().lower() or "sentinel_finding"
    risk_level = str(record.get("severity") or record.get("risk_level") or "high").strip().lower() or "high"
    priority = _human_inbox_priority(record.get("priority") or risk_level, fallback="high")
    created_at = record.get("triggered_at") or record.get("created_at") or record.get("opened_at")
    updated_at = record.get("updated_at") or record.get("last_seen_at") or created_at
    runtime_id = record.get("runtime_id") or record.get("target_id")
    persona_id = record.get("persona_id")
    target_type = "Persona" if persona_id else "Runtime" if runtime_id else record.get("target_type")
    target_id = persona_id or runtime_id or record.get("target_id") or finding_id
    route = f"/management/sentinel?finding={finding_id}"
    action_state = _human_inbox_action_state(status, _HUMAN_INBOX_OPEN_SENTINEL_STATUSES)
    projected = {
        "id": f"sentinel_finding:{finding_id}",
        "inbox_id": f"sentinel_finding:{finding_id}",
        "inboxType": "sentinel_finding",
        "source_type": "sentinel_finding",
        "source_id": finding_id,
        "finding_id": finding_id,
        "title": record.get("title") or f"Sentinel finding: {kind}",
        "summary": record.get("summary") or record.get("description") or "Sentinel finding requires operator review.",
        "priority": priority,
        "risk_level": risk_level,
        "status": status,
        "action_state": action_state,
        "created_at": created_at,
        "updated_at": updated_at,
        "target": {
            "type": target_type,
            "id": target_id,
        },
        "route": route,
        "bff_detail_path": f"/bff/v5/sentinel/findings/{finding_id}",
        "sentinel_context": {
            "kind": kind,
            "runtime_id": runtime_id,
            "persona_id": persona_id,
            "derived_from_incident_id": record.get("derived_from_incident_id"),
        },
        "allowedActions": _management_json_clone(record.get("allowedActions") or {
            "canReview": action_state == "pending",
            "canRemediate": action_state == "pending",
        }),
    }
    return _human_inbox_attach_common_fields(
        projected,
        inbox_type="sentinel_finding",
        source_dataset="sentinel_findings",
        risk_level=risk_level,
        created_at=created_at,
        updated_at=updated_at,
        href=route,
        source_record=record,
    )


def _human_inbox_persona_blocking_reasons(row: Dict[str, Any]) -> List[str]:
    reasons: List[str] = []
    current_work = str(row.get("current_work") or row.get("currentWork") or "").strip()
    if current_work:
        reasons.append(current_work)
    recommendation = str(row.get("recommendation") or "").strip()
    if recommendation:
        reasons.append(f"governance recommendation: {recommendation}")
    research_status = row.get("research_status") if isinstance(row.get("research_status"), dict) else {}
    pending_task_ids = research_status.get("pending_task_ids")
    if isinstance(pending_task_ids, list) and pending_task_ids:
        reasons.append(f"pending research tasks: {', '.join(str(task_id) for task_id in pending_task_ids)}")
    if row.get("can_deploy") is False or row.get("canDeploy") is False:
        reasons.append("deployment is blocked until human review clears")
    return reasons


def _human_inbox_persona_readiness_item(row: Dict[str, Any], *, snapshot_at: str) -> Optional[Dict[str, Any]]:
    persona_id = _management_record_id(row, "persona_id", "personaId", "id")
    if not persona_id or not bool(row.get("human_needed") or row.get("humanNeeded")):
        return None
    name = str(row.get("persona_name") or row.get("personaName") or row.get("name") or persona_id).strip()
    status = str(row.get("state") or row.get("status") or "needs_human_approval").strip().lower()
    research_status = row.get("research_status") if isinstance(row.get("research_status"), dict) else {}
    current_projects = row.get("current_research_projects") if isinstance(row.get("current_research_projects"), list) else []
    blocking_reasons = _human_inbox_persona_blocking_reasons(row)
    risk_level = "high" if status in {"critical", "needs_human_approval", "blocked"} or blocking_reasons else "medium"
    priority = _human_inbox_priority(row.get("priority") or risk_level, fallback=risk_level)
    created_at = row.get("updated_at") or row.get("lastMutation") or row.get("last_mutation") or snapshot_at
    route = f"/management/persona-fleet?persona={persona_id}"
    summary = (
        str(row.get("current_work") or row.get("currentWork") or "").strip()
        or str(research_status.get("summary") or "").strip()
        or "Persona readiness is blocked on human governance review."
    )
    projected = {
        "id": f"readiness_blocker:persona:{persona_id}",
        "inbox_id": f"readiness_blocker:persona:{persona_id}",
        "inboxType": "readiness_blocker",
        "source_type": "readiness_blocker",
        "source_id": persona_id,
        "persona_id": persona_id,
        "title": f"Persona needs review: {name}",
        "summary": summary,
        "priority": priority,
        "risk_level": risk_level,
        "status": status,
        "action_state": "pending",
        "created_at": created_at,
        "updated_at": created_at,
        "target": {
            "type": "persona",
            "id": persona_id,
        },
        "route": route,
        "bff_detail_path": f"/bff/management/human-inbox/readiness_blocker:persona:{persona_id}",
        "blocking_reasons": list(blocking_reasons),
        "can_proceed": False,
        "research_context": {
            "research_status": _management_json_clone(research_status),
            "current_research_projects": _management_json_clone(current_projects),
            "recommendation": row.get("recommendation"),
            "current_work": row.get("current_work") or row.get("currentWork"),
            "data_source_status": _management_json_clone(row.get("data_source_status") or {}),
        },
        "allowedActions": {
            "canProceed": False,
            "canDecide": False,
            "canOpenPersonaFleet": True,
            "canOpenResearch": bool(current_projects or research_status),
            "canRequestRevision": True,
        },
    }
    return _human_inbox_attach_common_fields(
        projected,
        inbox_type="readiness_blocker",
        source_dataset="persona_fleet",
        risk_level=risk_level,
        created_at=created_at,
        updated_at=created_at,
        href=route,
        source_record=row,
    )


_HUMAN_INBOX_PROMOTION_PRODUCER = "management_quarterly_ranking_recommendation_submit"
_HUMAN_INBOX_INACTIVE_COMMAND_STATUSES = {
    "canceled",
    "cancelled",
    "expired",
    "failed",
    "timed_out",
    "timeout",
}
_HUMAN_INBOX_PROMOTION_SNAPSHOT_SCALARS = {
    "action_id",
    "action_label",
    "archetype",
    "binding_state",
    "capital_mode",
    "capital_pool_id",
    "capital_scope",
    "capital_scope_id",
    "capital_sleeve_id",
    "current_weight",
    "current_weight_source",
    "deployment_stage",
    "eligible",
    "exclusion_reason",
    "formula_version",
    "id",
    "name",
    "owner",
    "paper_ledger_id",
    "priority",
    "quarter",
    "rank",
    "ranking_snapshot_id",
    "rationale",
    "recommendation_id",
    "risk",
    "risk_level",
    "score",
    "source_confidence",
    "stage",
    "state",
    "target_weight",
    "tier",
    "tier_id",
    "tier_label",
    "persona_id",
}
_HUMAN_INBOX_PROMOTION_SNAPSHOT_STRING_LISTS = {
    "artifact_ids",
    "binding_ids",
    "broker_ids",
    "capital_pool_ids",
    "exclusion_codes",
    "exclusion_reasons",
    "rationale_codes",
    "runtime_ids",
    "sleeve_ids",
    "strategy_ids",
}


def _human_inbox_promotion_recommendation_id(command: Dict[str, Any]) -> str:
    params = command.get("params") if isinstance(command.get("params"), dict) else {}
    target = command.get("target") if isinstance(command.get("target"), dict) else {}
    return str(
        params.get("recommendation_id")
        or params.get("recommendationId")
        or params.get("review_id")
        or params.get("promotion_review_id")
        or target.get("id")
        or ""
    ).strip()


def _human_inbox_trusted_promotion_submission(command: Dict[str, Any]) -> bool:
    if command.get("type") != CommandType.QUARTERLY_RANKING_RECOMMENDATION_SUBMIT.value:
        return False
    if str(command.get("status") or "").strip().lower() in _HUMAN_INBOX_INACTIVE_COMMAND_STATUSES:
        return False
    params = command.get("params") if isinstance(command.get("params"), dict) else {}
    target = command.get("target") if isinstance(command.get("target"), dict) else {}
    recommendation_id = _human_inbox_promotion_recommendation_id(command)
    review_revision_id = _promotion_review_record_revision_id(command)
    target_id = str(target.get("id") or "").strip()
    if (
        not recommendation_id
        or target.get("type") != ObjectType.RANKING.value
        or not review_revision_id
        or target_id not in {recommendation_id, review_revision_id}
    ):
        return False
    expected_quarter = _promotion_review_quarter_from_id(recommendation_id)
    quarter = str(params.get("quarter") or "").strip().upper()
    persona_id = str(params.get("persona_id") or "").strip()
    action_id = str(
        params.get("recommendation_action_id")
        or params.get("recommendationActionId")
        or ""
    ).strip()
    if not expected_quarter or quarter != expected_quarter or not persona_id:
        return False
    if action_id not in _PROMOTION_REVIEW_ACTION_IDS:
        return False
    ranking_snapshot_id = str(params.get("ranking_snapshot_id") or "").strip()
    if ranking_snapshot_id and review_revision_id != _promotion_review_revision_id(
        recommendation_id,
        ranking_snapshot_id,
    ):
        return False
    for flag in (
        "direct_live_capital_mutation",
        "liveCapitalMutation",
        "live_capital_mutation",
        "runtime_mutation",
    ):
        if params.get(flag) not in (None, False):
            return False

    foundation = command.get("foundation") if isinstance(command.get("foundation"), dict) else {}
    audit = command.get("audit") if isinstance(command.get("audit"), dict) else {}
    audit_foundation = audit.get("foundation") if isinstance(audit.get("foundation"), dict) else {}
    trusted_producer = (
        foundation.get("trusted_evidence_producer")
        or audit.get("trusted_evidence_producer")
        or audit_foundation.get("trusted_evidence_producer")
    )
    if trusted_producer == _HUMAN_INBOX_PROMOTION_PRODUCER:
        return True
    # Legacy submissions from the dedicated semantic route predate the
    # producer marker. Generic /bff/v1 command admission always persists an
    # admission_route and must not manufacture viewer-visible inbox rows.
    if foundation.get("admission_route"):
        return False
    if not foundation:
        # Pre-foundation command-store rows were written by the dedicated
        # semantic submit route. API-admitted generic commands always carry an
        # admission_route, so this compatibility path cannot be reached by a
        # current generic command request.
        return True
    return (
        params.get("source_type") == "quarterly_ranking_recommendation"
        and params.get("source_record_id") == recommendation_id
        and params.get("audit_event") == "quarterly_ranking.recommendation_submitted"
        and params.get("policy") == "promotion_governance_human_gate_no_direct_live_capital"
    )


def _human_inbox_sanitize_promotion_snapshot(
    command: Dict[str, Any],
) -> Optional[Dict[str, Any]]:
    if not _human_inbox_trusted_promotion_submission(command):
        return None
    params = command.get("params") if isinstance(command.get("params"), dict) else {}
    recommendation_id = _human_inbox_promotion_recommendation_id(command)
    expected_quarter = str(_promotion_review_quarter_from_id(recommendation_id) or "").upper()
    persona_id = str(params.get("persona_id") or "").strip()
    action_id = str(
        params.get("recommendation_action_id")
        or params.get("recommendationActionId")
        or ""
    ).strip()
    raw_snapshot = params.get("source_recommendation")
    if raw_snapshot is not None and not isinstance(raw_snapshot, dict):
        return None
    raw = raw_snapshot if isinstance(raw_snapshot, dict) else {}

    for snapshot_id in (raw.get("id"), raw.get("recommendation_id")):
        if snapshot_id not in (None, "") and str(snapshot_id).strip() != recommendation_id:
            return None
    snapshot_quarter = str(raw.get("quarter") or expected_quarter).strip().upper()
    snapshot_persona = str(raw.get("persona_id") or persona_id).strip()
    snapshot_action = str(raw.get("action_id") or action_id).strip()
    if (
        snapshot_quarter != expected_quarter
        or snapshot_persona != persona_id
        or snapshot_action != action_id
    ):
        return None
    params_snapshot_id = str(params.get("ranking_snapshot_id") or "").strip()
    raw_snapshot_id = str(raw.get("ranking_snapshot_id") or "").strip()
    if params_snapshot_id and raw_snapshot_id != params_snapshot_id:
        return None

    sanitized: Dict[str, Any] = {}
    for key in _HUMAN_INBOX_PROMOTION_SNAPSHOT_SCALARS:
        value = raw.get(key)
        if value is None or isinstance(value, (dict, list)):
            continue
        sanitized[key] = value
    for key in _HUMAN_INBOX_PROMOTION_SNAPSHOT_STRING_LISTS:
        value = raw.get(key)
        if isinstance(value, list):
            sanitized[key] = [str(item) for item in value if isinstance(item, (str, int, float))]
    for key in ("components", "metrics"):
        value = raw.get(key)
        if isinstance(value, dict):
            sanitized[key] = {
                str(metric): number
                for metric, number in value.items()
                if isinstance(number, (int, float)) and not isinstance(number, bool)
            }

    sanitized.update(
        {
            "id": recommendation_id,
            "recommendation_id": recommendation_id,
            "quarter": expected_quarter,
            "persona_id": persona_id,
            "action_id": action_id,
            "name": sanitized.get("name") or params.get("persona_name") or persona_id,
            "priority": sanitized.get("priority") or params.get("priority") or "high",
            "risk_level": sanitized.get("risk_level") or params.get("risk_level") or "high",
            "rationale": sanitized.get("rationale")
            or params.get("rationale")
            or "Submitted ranking recommendation requires Human Gate review.",
            # Evidence bodies are request-scoped and may contain privileged
            # material. Never replay arbitrary command params onto a read row.
            "evidence_refs": [],
            "evidence_ref_ids": [],
        }
    )
    if params_snapshot_id:
        sanitized["ranking_snapshot_id"] = params_snapshot_id
    review_revision_id = _promotion_review_record_revision_id(command)
    if not review_revision_id:
        return None
    sanitized["review_id"] = review_revision_id
    sanitized["promotion_review_id"] = review_revision_id
    stage_from = str(params.get("stage_from") or sanitized.get("stage") or sanitized.get("state") or "").strip()
    if stage_from:
        sanitized.setdefault("stage", stage_from)
        sanitized.setdefault("state", stage_from)
    expected_path = _promotion_review_stage_path(sanitized)
    for param_key, path_key in (
        ("stage_from", "from_stage"),
        ("stage_to", "target_stage"),
        ("review_kind", "review_kind"),
    ):
        value = str(params.get(param_key) or "").strip()
        if value and value != str(expected_path.get(path_key) or ""):
            return None
    return sanitized


def _human_inbox_submission_projection_from_record(
    command: Dict[str, Any],
    recommendation_id: str,
) -> Dict[str, Any]:
    params = command.get("params") if isinstance(command.get("params"), dict) else {}
    audit = command.get("audit") if isinstance(command.get("audit"), dict) else {}
    review_revision_id = _promotion_review_record_revision_id(command)
    return {
        "submitted": True,
        "submit_status": command.get("status"),
        "command_id": command.get("command_id"),
        "commandId": command.get("command_id"),
        "receipt_id": command.get("command_id"),
        "submitted_at": command.get("submitted_at"),
        "submitted_by": audit.get("operator_id") or audit.get("actor") or audit.get("actor_id"),
        "recommendation_id": recommendation_id,
        "review_id": review_revision_id,
        "promotion_review_id": review_revision_id,
        "recommendation_action_id": params.get("recommendation_action_id")
        or params.get("recommendationActionId"),
        "ranking_snapshot_id": params.get("ranking_snapshot_id"),
        "quarter": params.get("quarter"),
        "persona_id": params.get("persona_id"),
        "stage_from": params.get("stage_from"),
        "stage_to": params.get("stage_to"),
        "review_kind": params.get("review_kind"),
        "human_inbox_id": _promotion_review_target_id(review_revision_id),
        "live_capital_mutation": False,
        "requires_human_gate_decision": True,
    }


def _human_inbox_decision_recommendation_id(command: Dict[str, Any]) -> str:
    command_type = str(command.get("type") or "")
    if command_type not in {
        CommandType.HUMAN_GATE_APPROVE.value,
        CommandType.HUMAN_GATE_REJECT.value,
    }:
        return ""
    target = command.get("target") if isinstance(command.get("target"), dict) else {}
    if target.get("type") != ObjectType.HUMAN_GATE_ITEM.value:
        return ""
    params = command.get("params") if isinstance(command.get("params"), dict) else {}
    raw_target_id = str(target.get("id") or "").strip()
    review_revision_id = _promotion_review_clean_id(raw_target_id)
    if (
        not review_revision_id
        or raw_target_id != _promotion_review_target_id(review_revision_id)
    ):
        return ""
    recommendation_id = str(
        params.get("recommendation_id")
        or params.get("recommendationId")
        or _promotion_review_revision_recommendation_id(review_revision_id)
    ).strip()
    if (
        not recommendation_id
        or _promotion_review_revision_recommendation_id(review_revision_id)
        != recommendation_id
    ):
        return ""
    for key in (
        "human_gate_item_id",
        "humanGateItemId",
        "review_id",
        "reviewId",
        "promotion_review_id",
        "promotionReviewId",
    ):
        alias = params.get(key)
        if (
            alias not in (None, "")
            and _promotion_review_clean_id(alias) != review_revision_id
        ):
            return ""
    for key in ("recommendation_id", "recommendationId"):
        alias = params.get(key)
        if alias not in (None, "") and str(alias).strip() != recommendation_id:
            return ""
    ranking_snapshot_id = str(params.get("ranking_snapshot_id") or "").strip()
    if ranking_snapshot_id:
        if review_revision_id != _promotion_review_revision_id(
            recommendation_id,
            ranking_snapshot_id,
        ):
            return ""
    elif review_revision_id != recommendation_id:
        # A revision-aware decision without its snapshot lineage is unsafe.
        return ""
    return review_revision_id


def _human_inbox_decision_projection_from_record(command: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if str(command.get("status") or "").strip().lower() in _HUMAN_INBOX_INACTIVE_COMMAND_STATUSES:
        return None
    review_revision_id = _human_inbox_decision_recommendation_id(command)
    if not review_revision_id:
        return None
    params = command.get("params") if isinstance(command.get("params"), dict) else {}
    decision = str(params.get("decision") or "").strip().lower()
    if decision not in _PROMOTION_REVIEW_DECISIONS:
        return None
    command_type = str(command.get("type") or "")
    if command_type == CommandType.HUMAN_GATE_REJECT.value and decision != "reject":
        return None
    if command_type == CommandType.HUMAN_GATE_APPROVE.value and decision not in {
        "approve",
        "approve_with_conditions",
    }:
        return None
    audit = command.get("audit") if isinstance(command.get("audit"), dict) else {}
    projection: Dict[str, Any] = {
        "decision": decision,
        "decision_status": "accepted",
        "command_id": command.get("command_id"),
        "commandId": command.get("command_id"),
        "receipt_id": command.get("command_id"),
        "submitted_at": command.get("submitted_at"),
        "decided_at": command.get("submitted_at"),
        "decided_by": audit.get("operator_id") or audit.get("actor") or audit.get("actor_id"),
        "command_status": command.get("status"),
        "review_id": review_revision_id,
        "promotion_review_id": review_revision_id,
        "recommendation_id": params.get("recommendation_id")
        or params.get("recommendationId")
        or _promotion_review_revision_recommendation_id(
            review_revision_id
        ),
        "ranking_snapshot_id": params.get("ranking_snapshot_id"),
        "live_capital_mutation": False,
        "requires_human_gate_decision": True,
    }
    rationale = params.get("rationale") or params.get("reason") or params.get("rejection_reason") or params.get("memo")
    if rationale not in (None, ""):
        projection["rationale"] = rationale
    if "conditions" in params:
        projection["conditions"] = _management_json_clone(params.get("conditions"))
    return projection


def _human_inbox_promotion_review_from_projection(
    recommendation: Dict[str, Any],
    *,
    submission: Dict[str, Any],
    decision: Optional[Dict[str, Any]],
) -> Dict[str, Any]:
    recommendation_id = str(
        recommendation.get("recommendation_id")
        or recommendation.get("id")
        or ""
    )
    review_id = str(
        recommendation.get("promotion_review_id")
        or recommendation.get("review_id")
        or _promotion_review_revision_id(
            recommendation_id,
            recommendation.get("ranking_snapshot_id"),
        )
    )
    stage_path = _promotion_review_stage_path(recommendation)
    decision_status = "accepted" if decision else "pending"
    item: Dict[str, Any] = {
        **{
            key: _management_json_clone(value)
            for key, value in recommendation.items()
            if key not in {"id", "status"}
        },
        "id": review_id,
        "review_id": review_id,
        "promotion_review_id": review_id,
        "recommendation_id": recommendation_id,
        "status": "decision_accepted" if decision else "pending_human_gate",
        "decision_status": decision_status,
        "submitted": True,
        "submit_status": submission.get("submit_status"),
        "human_inbox_id": _promotion_review_target_id(review_id),
        "allowed_decisions": sorted(_PROMOTION_REVIEW_DECISIONS),
        "allowedActions": {
            "canSubmit": False,
            "canApprove": not bool(decision),
            "canApproveWithConditions": not bool(decision),
            "canReject": not bool(decision),
        },
        "promotion_path": stage_path,
        "review_kind": stage_path.get("review_kind"),
        "source_recommendation": _management_json_clone(recommendation),
        "submission": submission,
        "governance": {
            "requires_human_gate_decision": True,
            "decision_status": decision_status,
            "live_capital_mutation": False,
            "direct_live_capital_mutation": False,
            "policy": "promotion_governance_human_gate_no_direct_live_capital",
        },
        "requires_human_gate_decision": True,
        "live_capital_mutation": False,
        "direct_live_capital_mutation": False,
        "policy": "promotion_governance_human_gate_no_direct_live_capital",
        "links": {
            "persona": f"/bff/personas/{recommendation.get('persona_id')}",
            "recommendation": "/bff/management/quarterly-ranking/recommendations",
            "detail": f"/bff/management/promotion-reviews/{quote(review_id, safe='')}",
            "decisions": f"/bff/management/promotion-reviews/{quote(review_id, safe='')}/decisions",
            "human_inbox": f"/bff/management/human-inbox/{quote(_promotion_review_target_id(review_id), safe='')}",
        },
    }
    if decision:
        item["decision"] = decision
    return item


def _submitted_promotion_review_record_from_command(
    command: Dict[str, Any],
    *,
    decision: Optional[Dict[str, Any]] = None,
) -> Optional[Dict[str, Any]]:
    """Project one trusted durable submission without rebuilding PM12 reads."""
    recommendation = _human_inbox_sanitize_promotion_snapshot(command)
    if recommendation is None:
        return None
    recommendation_id = str(recommendation["recommendation_id"])
    review_id = _promotion_review_record_revision_id(command)
    if not review_id:
        return None
    return _human_inbox_promotion_review_from_projection(
        recommendation,
        submission=_human_inbox_submission_projection_from_record(command, recommendation_id),
        decision=decision,
    )


def _submitted_promotion_review_records(
    identity: OperatorIdentity,
    *,
    snapshot_at: str,
) -> List[Dict[str, Any]]:
    del identity, snapshot_at  # Projection is identity-stable; evidence is always stripped.
    submissions: Dict[str, Dict[str, Any]] = {}
    decisions: Dict[str, Dict[str, Any]] = {}
    # One command-log read per aggregate, regardless of submitted row count.
    for command in command_store._get_all_commands():
        if command.get("type") == CommandType.QUARTERLY_RANKING_RECOMMENDATION_SUBMIT.value:
            recommendation = _human_inbox_sanitize_promotion_snapshot(command)
            if recommendation is not None:
                review_id = _promotion_review_record_revision_id(command)
                if review_id:
                    submissions[review_id] = command
            continue
        review_id = _human_inbox_decision_recommendation_id(command)
        decision = _human_inbox_decision_projection_from_record(command)
        if review_id and decision is not None:
            decisions[review_id] = decision

    records: List[Dict[str, Any]] = []
    for review_id, command in submissions.items():
        review = _submitted_promotion_review_record_from_command(
            command,
            decision=decisions.get(review_id),
        )
        if review is not None:
            records.append(review)
    return records


def _human_inbox_promotion_review_item(review: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    review_id = str(review.get("review_id") or review.get("promotion_review_id") or "").strip()
    if not review_id:
        return None
    decision_status = str(review.get("decision_status") or "pending").strip().lower() or "pending"
    status = "accepted" if decision_status == "accepted" else "pending"
    risk_level = str(review.get("risk_level") or "high").strip().lower() or "high"
    priority = _human_inbox_priority(review.get("priority") or risk_level, fallback="high")
    submission = review.get("submission") if isinstance(review.get("submission"), dict) else {}
    created_at = submission.get("submitted_at") or review.get("created_at")
    updated_at = (review.get("decision") or {}).get("decided_at") if isinstance(review.get("decision"), dict) else None
    updated_at = updated_at or created_at
    inbox_id = _promotion_review_target_id(review_id)
    route = f"/management/human-inbox/{quote(inbox_id, safe='')}"
    action_state = "pending" if status == "pending" else "resolved"
    stage_path = review.get("promotion_path") if isinstance(review.get("promotion_path"), dict) else {}
    projected = {
        "id": inbox_id,
        "inbox_id": inbox_id,
        "inboxType": "promotion_review",
        "source_type": "promotion_review",
        "source_id": review_id,
        "review_id": review_id,
        "promotion_review_id": review_id,
        "recommendation_id": review.get("recommendation_id"),
        "persona_id": review.get("persona_id"),
        "title": f"Persona governance review: {review.get('name') or review.get('persona_id')}",
        "summary": review.get("rationale") or "Persona ranking recommendation requires Human Gate approval.",
        "priority": priority,
        "risk_level": risk_level,
        "status": status,
        "action_state": action_state,
        "created_at": created_at,
        "updated_at": updated_at,
        "submitted_by": submission.get("submitted_by"),
        "target": {
            "type": "persona",
            "id": review.get("persona_id"),
        },
        "route": route,
        "bff_detail_path": f"/bff/management/promotion-reviews/{quote(review_id, safe='')}",
        "decisionHref": f"/bff/management/promotion-reviews/{quote(review_id, safe='')}/decisions",
        "detailHref": route,
        "promotion_review": _management_json_clone(review),
        "promotion_context": {
            "from_stage": stage_path.get("from_stage"),
            "target_stage": stage_path.get("target_stage"),
            "review_kind": review.get("review_kind") or stage_path.get("review_kind"),
            "action_id": review.get("action_id"),
            "ranking_snapshot_id": review.get("ranking_snapshot_id"),
            "live_capital_mutation": False,
        },
        "allowedActions": _management_json_clone(review.get("allowedActions") or {
            "canApprove": action_state == "pending",
            "canApproveWithConditions": action_state == "pending",
            "canReject": action_state == "pending",
        }),
        "requires_human_gate_decision": True,
        "live_capital_mutation": False,
    }
    return _human_inbox_attach_common_fields(
        projected,
        inbox_type="promotion_review",
        source_dataset="promotion_reviews",
        risk_level=risk_level,
        created_at=created_at,
        updated_at=updated_at,
        href=route,
        source_record=review,
    )


def _human_inbox_project_items(
    *,
    snapshot_at: str,
    review_records: Sequence[Dict[str, Any]],
    approval_records: Sequence[Dict[str, Any]],
    intervention_records: Sequence[Dict[str, Any]],
    sentinel_records: Sequence[Dict[str, Any]],
    persona_rows: Sequence[Dict[str, Any]],
    promotion_review_records: Sequence[Dict[str, Any]],
) -> List[Dict[str, Any]]:
    """Project already-loaded contributors into the canonical inbox rows."""
    items: List[Dict[str, Any]] = []
    projectors: Sequence[tuple[Sequence[Dict[str, Any]], Callable[[Dict[str, Any]], Optional[Dict[str, Any]]]]] = (
        (review_records, _human_inbox_governance_review_item),
        (approval_records, _human_inbox_approval_item),
        (intervention_records, _human_inbox_intervention_item),
        (sentinel_records, _human_inbox_sentinel_item),
        (
            persona_rows,
            lambda row: _human_inbox_persona_readiness_item(row, snapshot_at=snapshot_at),
        ),
        (promotion_review_records, _human_inbox_promotion_review_item),
    )
    for records, projector in projectors:
        for record in records:
            projected = projector(record)
            if projected is not None:
                items.append(projected)
    items.sort(
        key=lambda item: (
            _HUMAN_INBOX_PRIORITY_RANK.get(str(item.get("priority") or "unknown"), 0),
            str(item.get("created_at") or ""),
            str(item.get("id") or ""),
        ),
        reverse=True,
    )
    return items


def _human_inbox_governance_contributor(
    snapshot_at: str,
) -> tuple[List[Dict[str, Any]], Dict[str, Any]]:
    records = list(read_store.list_governance_review_queue_items() or [])
    return records, _dataset_surface_status(
        "governance_review_queue_items",
        snapshot_at=snapshot_at,
        has_data=bool(records),
        missing_message="Governance review queue has no readable source records.",
        source=_dataset_source_after_read("governance_review_queue_items"),
    )


def _human_inbox_approval_contributor(
    snapshot_at: str,
) -> tuple[List[Dict[str, Any]], Dict[str, Any]]:
    records = list(read_store.list_approval_queue_items() or [])
    return records, _dataset_surface_status(
        "approval_queue_items",
        snapshot_at=snapshot_at,
        has_data=bool(records),
        missing_message="Approval queue has no readable source records.",
        source=_dataset_source_after_read("approval_queue_items"),
    )


def _human_inbox_intervention_contributor(
    snapshot_at: str,
) -> tuple[List[Dict[str, Any]], Dict[str, Any]]:
    records = list(_v5_intervention_records())
    surface = _dataset_surface_status(
        "v5_interventions",
        snapshot_at=snapshot_at,
        has_data=bool(records),
        missing_message="V5 interventions have no readable source records.",
        source=_dataset_source_after_read("v5_interventions"),
    )
    local_ids = {
        str(record.get("intervention_id") or record.get("id") or "")
        for record in _V5_INTERVENTIONS_STORE
        if isinstance(record, dict)
    }
    has_local_record = any(
        str(record.get("intervention_id") or record.get("id") or "") in local_ids
        for record in records
    )
    if has_local_record and surface.get("source") == "missing":
        surface = {**_surface_status(), "source": "bff_local_registry"}
    return records, surface


def _human_inbox_sentinel_contributor(
    snapshot_at: str,
) -> tuple[tuple[bool, List[Dict[str, Any]]], Dict[str, Any]]:
    available, raw_records = read_store.list_sentinel_findings()
    records = list(raw_records or [])
    incidents_source = _dataset_source_after_read("incidents")
    if incidents_source != "missing":
        surface = _dataset_surface_status("incidents", snapshot_at=snapshot_at)
    else:
        surface = _dataset_surface_status(
            "sentinel_findings",
            snapshot_at=snapshot_at,
            source=_dataset_source_after_read("sentinel_findings") if available else "missing",
        )
    return (bool(available), records), surface


def _build_persona_readiness_items(snapshot_at: str) -> List[Dict[str, Any]]:
    """Build only the persona fields consumed by Human Inbox readiness rows.

    The full Fleet projection performs per-persona binding, runtime, strategy,
    source-health, incident, and evolution reads. Human Inbox does not consume
    those fields, so using it here created a large N+1 latency chain. This
    projection deliberately performs one persona read and one league read and
    reuses the loaded personas when deriving market context defaults.
    """
    personas = list(
        read_store.list_personas(include_market_persona_defaults=True) or []
    )
    league_by_persona = {
        str(item.get("persona_id") or item.get("id") or "").strip(): item
        for item in (
            read_store.list_persona_league(
                include_market_persona_defaults=True,
            )
            or []
        )
        if str(item.get("persona_id") or item.get("id") or "").strip()
    }
    context_defaults = _persona_fleet_context_defaults_by_market(personas)
    rows: List[Dict[str, Any]] = []
    for persona in personas:
        persona_id = _persona_id(persona)
        if not persona_id:
            continue
        metadata = persona.get("metadata") if isinstance(persona.get("metadata"), dict) else {}
        context_metadata, _context_persona = _persona_fleet_context_overlay(
            persona,
            metadata,
            context_defaults,
        )
        league_entry = league_by_persona.get(persona_id, {})
        governance_required = bool(
            league_entry.get("governance_required")
            if "governance_required" in league_entry
            else context_metadata.get("governance_required", True)
        )
        recommendation = (
            league_entry.get("recommendation")
            or context_metadata.get("recommended_governance_action")
            or ""
        )
        human_needed = governance_required and str(recommendation).strip().lower() not in {
            "",
            "none",
            "no_change",
        }
        research_status = (
            context_metadata.get("research_status")
            if isinstance(context_metadata.get("research_status"), dict)
            else {}
        )
        current_projects = (
            context_metadata.get("current_research_projects")
            if isinstance(context_metadata.get("current_research_projects"), list)
            else []
        )
        can_deploy = research_status.get("can_deploy")
        if can_deploy is None:
            can_deploy = context_metadata.get("can_deploy")
        rows.append(
            {
                "id": persona_id,
                "persona_id": persona_id,
                "name": persona.get("name") or persona_id,
                "persona_name": persona.get("name") or persona_id,
                "human_needed": human_needed,
                "state": str(
                    metadata.get("persona_status")
                    or league_entry.get("status")
                    or persona.get("status")
                    or persona.get("lifecycle_state")
                    or "unknown"
                ),
                "current_work": context_metadata.get("current_work"),
                "recommendation": recommendation,
                "can_deploy": can_deploy,
                "priority": league_entry.get("priority") or context_metadata.get("priority"),
                "updated_at": (
                    league_entry.get("updated_at")
                    or persona.get("updated_at")
                    or persona.get("last_active_at")
                    or snapshot_at
                ),
                "research_status": _management_json_clone(research_status),
                "current_research_projects": _management_json_clone(current_projects),
                "data_source_status": _management_json_clone(
                    context_metadata.get("data_source_status") or {}
                ),
            }
        )
    return rows


def _human_inbox_persona_contributor(
    snapshot_at: str,
) -> tuple[List[Dict[str, Any]], Dict[str, Any]]:
    rows = list(_build_persona_readiness_items(snapshot_at) or [])
    return rows, _composed_dataset_surface_status(
        "persona_fleet",
        rows,
        snapshot_at=snapshot_at,
        source="bff_composed",
    )


def _human_inbox_promotion_contributor(
    identity: OperatorIdentity,
    snapshot_at: str,
) -> tuple[List[Dict[str, Any]], Dict[str, Any]]:
    records = _submitted_promotion_review_records(identity, snapshot_at=snapshot_at)
    return records, {**_surface_status(), "source": "command_store"}


def _human_inbox_all_items(
    snapshot_at: Optional[str] = None,
    *,
    identity: Optional[OperatorIdentity] = None,
    source_types: Optional[set[str]] = None,
) -> tuple[List[Dict[str, Any]], Dict[str, Any]]:
    snapshot_at = snapshot_at or utc_now()
    include_all = not source_types
    review_records: List[Dict[str, Any]] = []
    approval_records: List[Dict[str, Any]] = []
    intervention_records: List[Dict[str, Any]] = []
    sentinel_available = False
    sentinel_records: List[Dict[str, Any]] = []
    persona_rows: List[Dict[str, Any]] = []
    promotion_review_records: List[Dict[str, Any]] = []
    surfaces: Dict[str, Dict[str, Any]] = {}
    if include_all or "governance_review" in source_types:
        review_records, surfaces["governance_review_queue"] = _human_inbox_governance_contributor(snapshot_at)
    if include_all or "approval" in source_types:
        approval_records, surfaces["approval_queue"] = _human_inbox_approval_contributor(snapshot_at)
    if include_all or "intervention" in source_types:
        intervention_records, surfaces["v5_interventions"] = _human_inbox_intervention_contributor(snapshot_at)
    if include_all or "sentinel_finding" in source_types:
        sentinel_result, surfaces["sentinel_findings"] = _human_inbox_sentinel_contributor(snapshot_at)
        sentinel_available, sentinel_records = sentinel_result
    if include_all or "readiness_blocker" in source_types:
        persona_rows, surfaces["persona_readiness"] = _human_inbox_persona_contributor(snapshot_at)
    if identity is not None and (include_all or "promotion_review" in source_types):
        promotion_review_records, surfaces["promotion_reviews"] = _human_inbox_promotion_contributor(
            identity,
            snapshot_at,
        )
    items = _human_inbox_project_items(
        snapshot_at=snapshot_at,
        review_records=review_records,
        approval_records=approval_records,
        intervention_records=intervention_records,
        sentinel_records=sentinel_records,
        persona_rows=persona_rows,
        promotion_review_records=promotion_review_records,
    )
    return items, {
        "governance_review_records": review_records,
        "approval_records": approval_records,
        "intervention_records": intervention_records,
        "sentinel_available": sentinel_available,
        "sentinel_records": sentinel_records,
        "persona_rows": persona_rows,
        "promotion_review_records": promotion_review_records,
        "surfaces": surfaces,
    }


_HUMAN_INBOX_MAX_SURFACE_TIMEOUT_SECONDS = 1.0


def _human_inbox_surface_timeout_seconds() -> float:
    raw = os.getenv("PANTHEON_BFF_HUMAN_INBOX_SURFACE_TIMEOUT_SECONDS", "1.0").strip()
    try:
        return min(
            _HUMAN_INBOX_MAX_SURFACE_TIMEOUT_SECONDS,
            max(0.05, float(raw)),
        )
    except (TypeError, ValueError):
        return _HUMAN_INBOX_MAX_SURFACE_TIMEOUT_SECONDS


def _human_inbox_read_error_surface(
    dataset: str,
    *,
    snapshot_at: str,
) -> Dict[str, Any]:
    return {
        "status": "degraded",
        "dataset": dataset,
        "source": "management_read_error",
        "reason": "read_error",
        "message": f"{dataset} failed while composing the Human Inbox; returned rows may be partial.",
        "staleness": {"served_from": "read_error", "last_known_at": snapshot_at},
    }


def _human_inbox_read_slot_count() -> int:
    try:
        return max(1, int(os.getenv("PANTHEON_BFF_HUMAN_INBOX_READ_CONCURRENCY", "12")))
    except (TypeError, ValueError):
        return 12


_HUMAN_INBOX_READ_SLOT_COUNT = _human_inbox_read_slot_count()
_HUMAN_INBOX_READ_SLOTS = threading.BoundedSemaphore(_HUMAN_INBOX_READ_SLOT_COUNT)
_HUMAN_INBOX_READ_EXECUTOR = ThreadPoolExecutor(
    max_workers=_HUMAN_INBOX_READ_SLOT_COUNT,
    thread_name_prefix="bff-human-inbox",
)


def _human_inbox_capacity_surface(
    dataset: str,
    *,
    snapshot_at: str,
) -> Dict[str, Any]:
    return {
        "status": "degraded",
        "dataset": dataset,
        "source": "management_read_capacity",
        "reason": "read_capacity_saturated",
        "message": (
            f"{dataset} was not submitted because Human Inbox read capacity "
            "is occupied by earlier synchronous contributors."
        ),
        "staleness": {"served_from": "capacity_degraded", "last_known_at": snapshot_at},
    }


async def _human_inbox_all_items_bounded(
    snapshot_at: str,
    *,
    identity: OperatorIdentity,
    source_types: Optional[set[str]],
) -> tuple[List[Dict[str, Any]], Dict[str, Any], Dict[str, Dict[str, Any]]]:
    """Load independent inbox contributors concurrently under per-surface budgets."""
    include_all = not source_types
    timeout_seconds = _human_inbox_surface_timeout_seconds()
    jobs: Dict[str, Any] = {}
    if include_all or "governance_review" in source_types:
        jobs["governance_review_records"] = _run_management_read(
            _human_inbox_governance_contributor,
            snapshot_at,
            timeout_seconds=timeout_seconds,
            capacity=_HUMAN_INBOX_READ_SLOTS,
            executor=_HUMAN_INBOX_READ_EXECUTOR,
        )
    if include_all or "approval" in source_types:
        jobs["approval_records"] = _run_management_read(
            _human_inbox_approval_contributor,
            snapshot_at,
            timeout_seconds=timeout_seconds,
            capacity=_HUMAN_INBOX_READ_SLOTS,
            executor=_HUMAN_INBOX_READ_EXECUTOR,
        )
    if include_all or "intervention" in source_types:
        jobs["intervention_records"] = _run_management_read(
            _human_inbox_intervention_contributor,
            snapshot_at,
            timeout_seconds=timeout_seconds,
            capacity=_HUMAN_INBOX_READ_SLOTS,
            executor=_HUMAN_INBOX_READ_EXECUTOR,
        )
    if include_all or "sentinel_finding" in source_types:
        jobs["sentinel_result"] = _run_management_read(
            _human_inbox_sentinel_contributor,
            snapshot_at,
            timeout_seconds=timeout_seconds,
            capacity=_HUMAN_INBOX_READ_SLOTS,
            executor=_HUMAN_INBOX_READ_EXECUTOR,
        )
    if include_all or "readiness_blocker" in source_types:
        jobs["persona_rows"] = _run_management_read(
            _human_inbox_persona_contributor,
            snapshot_at,
            timeout_seconds=timeout_seconds,
            capacity=_HUMAN_INBOX_READ_SLOTS,
            executor=_HUMAN_INBOX_READ_EXECUTOR,
        )
    if include_all or "promotion_review" in source_types:
        jobs["promotion_review_records"] = _run_management_read(
            _human_inbox_promotion_contributor,
            identity,
            snapshot_at,
            timeout_seconds=timeout_seconds,
            capacity=_HUMAN_INBOX_READ_SLOTS,
            executor=_HUMAN_INBOX_READ_EXECUTOR,
        )

    results = await asyncio.gather(*jobs.values(), return_exceptions=True)
    loaded: Dict[str, Any] = {
        "governance_review_records": [],
        "approval_records": [],
        "intervention_records": [],
        "sentinel_available": False,
        "sentinel_records": [],
        "persona_rows": [],
        "promotion_review_records": [],
        "surfaces": {},
    }
    surface_specs = {
        "governance_review_records": ("governance_review_queue", "governance_review_queue_items"),
        "approval_records": ("approval_queue", "approval_queue_items"),
        "intervention_records": ("v5_interventions", "v5_interventions"),
        "sentinel_result": ("sentinel_findings", "sentinel_findings"),
        "persona_rows": ("persona_readiness", "persona_fleet"),
        "promotion_review_records": ("promotion_reviews", "promotion_reviews"),
    }
    failures: Dict[str, Dict[str, Any]] = {}
    for key, result in zip(jobs, results):
        surface_key, dataset = surface_specs[key]
        if isinstance(result, _ManagementReadSaturated):
            failures[surface_key] = _human_inbox_capacity_surface(
                dataset,
                snapshot_at=snapshot_at,
            )
            continue
        if isinstance(result, _ManagementReadTimeout):
            failures[surface_key] = _management_read_timeout_surface(
                dataset,
                snapshot_at=snapshot_at,
                message=(
                    f"{dataset} exceeded the Human Inbox surface budget; "
                    "completed contributors are returned as a partial result."
                ),
            )
            continue
        if isinstance(result, Exception):
            log.warning("bff.human_inbox contributor=%s failed: %r", dataset, result)
            failures[surface_key] = _human_inbox_read_error_surface(
                dataset,
                snapshot_at=snapshot_at,
            )
            continue
        value, surface = result
        loaded["surfaces"][surface_key] = surface
        if key == "sentinel_result":
            loaded["sentinel_available"], loaded["sentinel_records"] = value
        else:
            loaded[key] = list(value or [])

    items = _human_inbox_project_items(
        snapshot_at=snapshot_at,
        review_records=loaded["governance_review_records"],
        approval_records=loaded["approval_records"],
        intervention_records=loaded["intervention_records"],
        sentinel_records=loaded["sentinel_records"],
        persona_rows=loaded["persona_rows"],
        promotion_review_records=loaded["promotion_review_records"],
    )
    return items, loaded, failures


def _human_inbox_filter_items(
    items: List[Dict[str, Any]],
    *,
    source_type: Optional[str] = None,
    status: Optional[str] = None,
    priority: Optional[str] = None,
) -> List[Dict[str, Any]]:
    source_types = _human_inbox_csv_filter(source_type)
    statuses = _human_inbox_csv_filter(status)
    priorities = _human_inbox_csv_filter(priority)
    filtered = items
    if source_types:
        filtered = [
            item for item in filtered
            if str(item.get("source_type") or item.get("inboxType") or "").lower() in source_types
        ]
    if statuses:
        filtered = [
            item for item in filtered
            if str(item.get("status") or "").lower() in statuses
            or str(item.get("action_state") or "").lower() in statuses
        ]
    if priorities:
        filtered = [
            item for item in filtered
            if str(item.get("priority") or "").lower() in priorities
            or str(item.get("risk_level") or "").lower() in priorities
        ]
    return filtered


def _human_inbox_summary(items: List[Dict[str, Any]], returned_count: int) -> Dict[str, Any]:
    pending_items = [item for item in items if str(item.get("action_state") or "") == "pending"]
    by_type = _management_count_by(items, "inboxType")
    by_status = _management_count_by(items, "status")
    highest_risk_level = _highest_ranked_value(
        [str(item.get("riskLevel") or item.get("risk_level") or "") for item in items],
        _MANAGEMENT_RISK_LEVEL_ORDER,
    )
    return {
        "total": len(items),
        "total_items": len(items),
        "returned_items": returned_count,
        "pending_items": len(pending_items),
        "by_type": by_type,
        "by_status": by_status,
        "highest_risk_level": highest_risk_level,
        "governance_review_count": len([item for item in items if item.get("source_type") == "governance_review"]),
        "approval_count": len([item for item in items if item.get("source_type") == "approval"]),
        "intervention_count": len([item for item in items if item.get("source_type") == "intervention"]),
        "sentinel_finding_count": len([item for item in items if item.get("source_type") == "sentinel_finding"]),
        "readiness_blocker_count": len([item for item in items if item.get("source_type") == "readiness_blocker"]),
        "critical_count": len([item for item in items if item.get("priority") == "critical"]),
        "high_count": len([item for item in items if item.get("priority") == "high"]),
    }


def _human_inbox_loaded_surface(
    *,
    snapshot_at: str,
    source: str,
    available: bool = True,
    has_data: Optional[bool] = None,
    empty_is_unavailable: bool = False,
    missing_message: Optional[str] = None,
) -> Dict[str, Any]:
    surface = dict(_surface_status())
    surface["source"] = source
    if not available or (empty_is_unavailable and has_data is False):
        surface["status"] = "unavailable"
        surface["source"] = "missing" if not available else source
        if missing_message:
            surface["message"] = missing_message
        surface.setdefault(
            "staleness",
            {"served_from": "unverifiable", "last_known_at": snapshot_at},
        )
    return surface


def _human_inbox_surfaces(
    *,
    snapshot_at: str,
    governance_review_records: List[Dict[str, Any]],
    approval_records: List[Dict[str, Any]],
    intervention_records: List[Dict[str, Any]],
    sentinel_available: bool,
    sentinel_records: List[Dict[str, Any]],
    persona_rows: List[Dict[str, Any]],
    promotion_review_records: List[Dict[str, Any]],
    source_types: Optional[set[str]] = None,
    surface_failures: Optional[Dict[str, Dict[str, Any]]] = None,
    loaded_surfaces: Optional[Dict[str, Dict[str, Any]]] = None,
) -> Dict[str, Any]:
    include_all = not source_types
    failures = surface_failures or {}
    provenance = loaded_surfaces or {}
    contributor_surfaces: Dict[str, Dict[str, Any]] = {}

    if include_all or "governance_review" in source_types:
        contributor_surfaces["governance_review_queue"] = failures.get(
            "governance_review_queue"
        ) or provenance.get("governance_review_queue") or _human_inbox_loaded_surface(
            snapshot_at=snapshot_at,
            source="read_store",
            has_data=bool(governance_review_records),
            empty_is_unavailable=True,
            missing_message="Governance review queue has no readable source records.",
        )
    if include_all or "approval" in source_types:
        contributor_surfaces["approval_queue"] = failures.get(
            "approval_queue"
        ) or provenance.get("approval_queue") or _human_inbox_loaded_surface(
            snapshot_at=snapshot_at,
            source="read_store",
            has_data=bool(approval_records),
            empty_is_unavailable=True,
            missing_message="Approval queue has no readable source records.",
        )
    if include_all or "intervention" in source_types:
        local_intervention_ids = {
            str(record.get("intervention_id") or record.get("id") or "")
            for record in _V5_INTERVENTIONS_STORE
            if isinstance(record, dict)
        }
        has_local_intervention = any(
            str(record.get("intervention_id") or record.get("id") or "") in local_intervention_ids
            for record in intervention_records
        )
        contributor_surfaces["v5_interventions"] = failures.get(
            "v5_interventions"
        ) or provenance.get("v5_interventions") or _human_inbox_loaded_surface(
            snapshot_at=snapshot_at,
            source="bff_local_registry" if has_local_intervention else "read_store",
            has_data=bool(intervention_records),
            empty_is_unavailable=True,
            missing_message="V5 interventions have no readable source records.",
        )
    if include_all or "sentinel_finding" in source_types:
        contributor_surfaces["sentinel_findings"] = failures.get(
            "sentinel_findings"
        ) or provenance.get("sentinel_findings") or _human_inbox_loaded_surface(
            snapshot_at=snapshot_at,
            source="read_store" if sentinel_available else "missing",
            available=sentinel_available,
            has_data=bool(sentinel_records),
            missing_message="Sentinel findings have no readable source records.",
        )
    if include_all or "readiness_blocker" in source_types:
        contributor_surfaces["persona_readiness"] = failures.get(
            "persona_readiness"
        ) or provenance.get("persona_readiness") or _human_inbox_loaded_surface(
            snapshot_at=snapshot_at,
            source="bff_composed",
            has_data=bool(persona_rows),
        )
    if include_all or "promotion_review" in source_types:
        contributor_surfaces["promotion_reviews"] = failures.get(
            "promotion_reviews"
        ) or provenance.get("promotion_reviews") or _human_inbox_loaded_surface(
            snapshot_at=snapshot_at,
            source="command_store",
            has_data=bool(promotion_review_records),
        )

    aggregate_surface = _aggregate_group_surface(
        "human_inbox",
        list(contributor_surfaces.values()),
        snapshot_at=snapshot_at,
        unavailable_message="Human inbox aggregate unavailable.",
        degraded_message="Human inbox aggregate is available, but one or more contributing surfaces are degraded.",
    )
    return {
        "human_inbox": aggregate_surface,
        **contributor_surfaces,
    }


def _human_inbox_payload_from_loaded(
    snapshot_at: str,
    *,
    items: List[Dict[str, Any]],
    sources: Dict[str, Any],
    source_types: Optional[set[str]],
    source_type: Optional[str] = None,
    status: Optional[str] = None,
    priority: Optional[str] = None,
    page_token: Optional[str] = None,
    page_size: Optional[int] = 20,
    surface_failures: Optional[Dict[str, Dict[str, Any]]] = None,
) -> Dict[str, Any]:
    filtered = _human_inbox_filter_items(
        items,
        source_type=source_type,
        status=status,
        priority=priority,
    )
    total = len(filtered)
    if page_size is None:
        page_items = filtered
        next_page_token = None
        returned_page_size = len(page_items)
    else:
        page_items, next_page_token = _page_slice(filtered, page_token, page_size)
        returned_page_size = page_size
    meta = _snapshot_meta(snapshot_at)
    meta["surfaces"] = _human_inbox_surfaces(
        snapshot_at=snapshot_at,
        governance_review_records=sources["governance_review_records"],
        approval_records=sources["approval_records"],
        intervention_records=sources["intervention_records"],
        sentinel_available=bool(sources["sentinel_available"]),
        sentinel_records=sources["sentinel_records"],
        persona_rows=sources["persona_rows"],
        promotion_review_records=sources["promotion_review_records"],
        source_types=source_types,
        surface_failures=surface_failures,
        loaded_surfaces=sources.get("surfaces"),
    )
    if surface_failures:
        meta["partial"] = True
        meta["degradation"] = {
            "reason": "one_or_more_human_inbox_contributors_incomplete",
            "contributors": sorted(surface_failures),
        }
    summary = _human_inbox_summary(filtered, len(page_items))
    canonical_page_items = _management_prune_camel_aliases(page_items)
    return {
        "data": {
            "id": "management-human-inbox",
            "items": canonical_page_items,
            "summary": summary,
        },
        "page_info": {
            "next_page_token": next_page_token,
            "total": total,
            "page_size": returned_page_size,
        },
        "meta": meta,
    }


def _human_inbox_payload(
    snapshot_at: str,
    *,
    identity: Optional[OperatorIdentity] = None,
    source_type: Optional[str] = None,
    status: Optional[str] = None,
    priority: Optional[str] = None,
    page_token: Optional[str] = None,
    page_size: Optional[int] = 20,
) -> Dict[str, Any]:
    source_types = _human_inbox_csv_filter(source_type)
    items, sources = _human_inbox_all_items(snapshot_at, identity=identity, source_types=source_types)
    return _human_inbox_payload_from_loaded(
        snapshot_at,
        items=items,
        sources=sources,
        source_types=source_types,
        source_type=source_type,
        status=status,
        priority=priority,
        page_token=page_token,
        page_size=page_size,
    )


async def _human_inbox_payload_bounded(
    snapshot_at: str,
    *,
    identity: OperatorIdentity,
    source_type: Optional[str] = None,
    status: Optional[str] = None,
    priority: Optional[str] = None,
    page_token: Optional[str] = None,
    page_size: Optional[int] = 20,
) -> tuple[
    Dict[str, Any],
    List[Dict[str, Any]],
    Dict[str, Any],
    Dict[str, Dict[str, Any]],
]:
    source_types = _human_inbox_csv_filter(source_type)
    items, sources, failures = await _human_inbox_all_items_bounded(
        snapshot_at,
        identity=identity,
        source_types=source_types,
    )
    payload = _human_inbox_payload_from_loaded(
        snapshot_at,
        items=items,
        sources=sources,
        source_types=source_types,
        source_type=source_type,
        status=status,
        priority=priority,
        page_token=page_token,
        page_size=page_size,
        surface_failures=failures,
    )
    return payload, items, sources, failures


def _human_inbox_detail_match(item: Dict[str, Any], item_id: str) -> bool:
    clean = str(item_id or "").strip()
    candidates = {
        str(item.get("id") or ""),
        str(item.get("inbox_id") or ""),
        str(item.get("source_id") or ""),
        str(item.get("approval_decision_id") or ""),
        str(item.get("intervention_id") or ""),
        str(item.get("review_item_id") or ""),
        str(item.get("finding_id") or ""),
        str(item.get("persona_id") or ""),
    }
    return clean in candidates


def _human_inbox_detail_source_types(item_id: str) -> Optional[set[str]]:
    clean = str(item_id or "").strip().lower()
    for prefix, source_type in (
        ("governance_review:", "governance_review"),
        ("approval:", "approval"),
        ("intervention:", "intervention"),
        ("sentinel_finding:", "sentinel_finding"),
        ("readiness_blocker:", "readiness_blocker"),
        ("promotion_review:", "promotion_review"),
    ):
        if clean.startswith(prefix):
            return {source_type}
    return None


def _hiq_backlog_filter_values(value: Optional[str], *, default: Optional[set[str]] = None) -> Optional[set[str]]:
    tokens = _split_csv_query(value)
    if not tokens:
        return set(default) if default is not None else None
    normalized = {token.strip().lower() for token in tokens if token.strip()}
    if not normalized or "all" in normalized:
        return None
    return normalized


def _hiq_backlog_target(record: Dict[str, Any], *, fallback_type: str, fallback_id: str) -> Dict[str, Any]:
    target_type = str(record.get("target_type") or record.get("targetType") or fallback_type).strip() or fallback_type
    target_id = str(
        record.get("target_id")
        or record.get("targetId")
        or record.get("runtime_id")
        or record.get("runtimeId")
        or record.get("persona_id")
        or record.get("personaId")
        or record.get("strategy_id")
        or record.get("strategyId")
        or fallback_id
    ).strip()
    return {"type": target_type, "id": target_id or None}


def _hiq_backlog_source_refs(record: Dict[str, Any], *, source_type: str, source_id: str) -> Dict[str, Any]:
    runtime_ids = [
        value
        for value in (
            record.get("runtime_id"),
            record.get("runtimeId"),
        )
        if value
    ]
    persona_ids = [
        value
        for value in (
            record.get("persona_id"),
            record.get("personaId"),
        )
        if value
    ]
    strategy_ids = [
        value
        for value in (
            record.get("strategy_id"),
            record.get("strategyId"),
        )
        if value
    ]
    incident_ids = [
        value
        for value in (
            record.get("incident_id"),
            record.get("incidentId"),
        )
        if value
    ]
    return {
        "source_type": source_type,
        "source_id": source_id,
        "runtime_ids": runtime_ids,
        "persona_ids": persona_ids,
        "strategy_ids": strategy_ids,
        "incident_ids": incident_ids,
    }


def _hiq_backlog_intervention_item(
    record: Dict[str, Any],
    *,
    human_inbox_item: Optional[Dict[str, Any]] = None,
) -> Optional[Dict[str, Any]]:
    intervention_id = _management_record_id(record, "intervention_id", "id")
    if not intervention_id:
        return None
    status = str(record.get("status") or "pending").strip().lower() or "pending"
    kind = str(record.get("kind") or "hiq_sentinel").strip().lower() or "hiq_sentinel"
    priority = _human_inbox_priority(
        record.get("priority") or record.get("severity") or record.get("risk_level"),
        fallback="critical" if status == "pending" and kind == "hiq_sentinel" else "high",
    )
    action_state = "pending" if status in _HUMAN_INBOX_OPEN_INTERVENTION_STATUSES else "resolved"
    created_at = str(record.get("triggered_at") or record.get("created_at") or "").strip() or None
    updated_at = str(record.get("remediated_at") or record.get("updated_at") or created_at or "").strip() or None
    source_refs = _hiq_backlog_source_refs(record, source_type="intervention", source_id=intervention_id)
    human_inbox_id = f"intervention:{intervention_id}"
    allowed_actions = _management_json_clone(
        (human_inbox_item or {}).get("allowedActions")
        or (human_inbox_item or {}).get("allowed_actions")
        or record.get("allowedActions")
        or {}
    )
    if isinstance(allowed_actions, dict):
        allowed_actions.setdefault("canReview", True)
        allowed_actions.setdefault("canRemediate", status in _HUMAN_INBOX_OPEN_INTERVENTION_STATUSES)
        allowed_actions.setdefault("canDecide", status in _HUMAN_INBOX_OPEN_INTERVENTION_STATUSES)
    else:
        allowed_actions = {
            "canReview": True,
            "canRemediate": status in _HUMAN_INBOX_OPEN_INTERVENTION_STATUSES,
            "canDecide": status in _HUMAN_INBOX_OPEN_INTERVENTION_STATUSES,
        }
    return {
        "id": f"hiq-backlog-intervention-{intervention_id}",
        "backlog_id": f"hiq-backlog-intervention-{intervention_id}",
        "source_type": "intervention",
        "source_id": intervention_id,
        "human_inbox_id": human_inbox_id,
        "kind": kind,
        "status": status,
        "action_state": action_state,
        "priority": priority,
        "risk_level": str(record.get("risk_level") or priority).strip().lower(),
        "severity": record.get("severity") or priority,
        "title": record.get("title") or f"{kind.replace('_', ' ').title()} intervention",
        "summary": record.get("description") or "HIQ intervention is waiting for operator action.",
        "created_at": created_at,
        "updated_at": updated_at,
        "target": _hiq_backlog_target(record, fallback_type="Intervention", fallback_id=intervention_id),
        "triggered_by": record.get("triggered_by"),
        "correlation_id": record.get("correlation_id"),
        "source_refs": source_refs,
        "links": {
            "source": f"/bff/v5/interventions/{intervention_id}",
            "human_inbox": f"/bff/management/human-inbox/{human_inbox_id}",
        },
        "allowed_actions": allowed_actions,
    }


def _hiq_backlog_sentinel_item(record: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    finding_id = _management_record_id(
        record,
        "finding_id",
        "sentinel_finding_id",
        "incident_id",
        "id",
    )
    if not finding_id:
        return None
    status = str(record.get("status") or "open").strip().lower() or "open"
    kind = str(record.get("kind") or "hiq_sentinel").strip().lower() or "hiq_sentinel"
    priority = _human_inbox_priority(
        record.get("priority") or record.get("severity") or record.get("risk_level"),
        fallback="high",
    )
    action_state = "pending" if status in _HIQ_BACKLOG_DEFAULT_STATUSES else "resolved"
    created_at = str(
        record.get("created_at")
        or record.get("triggered_at")
        or record.get("opened_at")
        or record.get("timestamp")
        or ""
    ).strip() or None
    updated_at = str(record.get("updated_at") or record.get("resolved_at") or created_at or "").strip() or None
    source_refs = _hiq_backlog_source_refs(record, source_type="sentinel_finding", source_id=finding_id)
    return {
        "id": f"hiq-backlog-sentinel-{finding_id}",
        "backlog_id": f"hiq-backlog-sentinel-{finding_id}",
        "source_type": "sentinel_finding",
        "source_id": finding_id,
        "kind": kind,
        "status": status,
        "action_state": action_state,
        "priority": priority,
        "risk_level": str(record.get("risk_level") or priority).strip().lower(),
        "severity": record.get("severity") or priority,
        "title": record.get("title") or f"{kind.replace('_', ' ').title()} finding",
        "summary": record.get("description") or record.get("summary") or "Sentinel finding is waiting for HIQ review.",
        "created_at": created_at,
        "updated_at": updated_at,
        "target": _hiq_backlog_target(record, fallback_type="SentinelFinding", fallback_id=finding_id),
        "source_refs": source_refs,
        "links": {
            "source": f"/bff/v5/sentinel/findings/{finding_id}",
            "human_inbox": "/bff/management/human-inbox",
        },
        "allowed_actions": {
            "canReview": True,
            "canOpenIntervention": False,
            "canRemediate": False,
        },
    }


def _hiq_backlog_item_matches(
    item: Dict[str, Any],
    *,
    source_types: Optional[set[str]],
    statuses: Optional[set[str]],
    priorities: Optional[set[str]],
    kinds: Optional[set[str]],
    q: str,
) -> bool:
    if source_types and str(item.get("source_type") or "").lower() not in source_types:
        return False
    if statuses:
        item_statuses = {
            str(item.get("status") or "").lower(),
            str(item.get("action_state") or "").lower(),
        }
        if not item_statuses.intersection(statuses):
            return False
    if priorities:
        item_priorities = {
            str(item.get("priority") or "").lower(),
            str(item.get("risk_level") or "").lower(),
            str(item.get("severity") or "").lower(),
        }
        if not item_priorities.intersection(priorities):
            return False
    if kinds and str(item.get("kind") or "").lower() not in kinds:
        return False
    needle = q.strip().lower()
    if needle:
        target = item.get("target") if isinstance(item.get("target"), dict) else {}
        haystack = " ".join(
            str(value or "")
            for value in (
                item.get("id"),
                item.get("source_type"),
                item.get("source_id"),
                item.get("kind"),
                item.get("status"),
                item.get("priority"),
                item.get("title"),
                item.get("summary"),
                target.get("type"),
                target.get("id"),
            )
        ).lower()
        if needle not in haystack:
            return False
    return True


def _hiq_backlog_sort_key(item: Dict[str, Any]) -> tuple[int, datetime, str]:
    return (
        _HUMAN_INBOX_PRIORITY_RANK.get(str(item.get("priority") or "unknown").lower(), 0),
        _audit_datetime(item.get("created_at") or item.get("updated_at")) or datetime.min.replace(tzinfo=timezone.utc),
        str(item.get("id") or ""),
    )


def _management_hiq_backlog_response(
    *,
    source_type: Optional[str],
    status: Optional[str],
    kind: Optional[str],
    priority: Optional[str],
    q: str,
    page_token: Optional[str],
    page_size: int,
    human_inbox_items: Optional[List[Dict[str, Any]]] = None,
    human_inbox_sources: Optional[Dict[str, Any]] = None,
    human_inbox_failures: Optional[Dict[str, Dict[str, Any]]] = None,
    human_inbox_source_types: Optional[set[str]] = None,
) -> Dict[str, Any]:
    snapshot_at = utc_now()
    source_types = _hiq_backlog_filter_values(source_type)
    statuses = _hiq_backlog_filter_values(status, default=_HIQ_BACKLOG_DEFAULT_STATUSES)
    priorities = _hiq_backlog_filter_values(priority)
    kinds = _hiq_backlog_filter_values(kind, default=_HIQ_BACKLOG_DEFAULT_KINDS)

    if human_inbox_items is None or human_inbox_sources is None:
        human_inbox_items, inbox_sources = _human_inbox_all_items(snapshot_at)
    else:
        inbox_sources = human_inbox_sources
    inbox_by_source_id = {
        str(item.get("source_id") or ""): item
        for item in human_inbox_items
        if str(item.get("source_type") or "") == "intervention" and item.get("source_id")
    }

    if human_inbox_sources is None:
        intervention_records = _v5_intervention_records()
        available_sentinel_findings, sentinel_findings = read_store.list_sentinel_findings()
    else:
        intervention_records = list(inbox_sources.get("intervention_records") or [])
        available_sentinel_findings = bool(inbox_sources.get("sentinel_available"))
        sentinel_findings = list(inbox_sources.get("sentinel_records") or [])
    items: List[Dict[str, Any]] = []
    for record in intervention_records:
        projected = _hiq_backlog_intervention_item(
            record,
            human_inbox_item=inbox_by_source_id.get(str(record.get("intervention_id") or record.get("id") or "")),
        )
        if projected is not None:
            items.append(projected)
    for record in sentinel_findings:
        projected = _hiq_backlog_sentinel_item(record)
        if projected is not None:
            items.append(projected)

    filtered = [
        item
        for item in items
        if _hiq_backlog_item_matches(
            item,
            source_types=source_types,
            statuses=statuses,
            priorities=priorities,
            kinds=kinds,
            q=q,
        )
    ]
    filtered.sort(key=_hiq_backlog_sort_key, reverse=True)
    total = len(filtered)
    page_items, next_page_token = _page_slice(filtered, page_token, page_size)

    source_counts = _management_count_by(filtered, "source_type")
    status_counts = _management_count_by(filtered, "status")
    kind_counts = _management_count_by(filtered, "kind")
    priority_counts = _management_count_by(filtered, "priority")
    latest_at = filtered[0].get("created_at") if filtered else None
    pending_count = len([item for item in filtered if item.get("action_state") == "pending"])
    summary = {
        "backlog_count": total,
        "returned_backlog_count": len(page_items),
        "intervention_count": source_counts.get("intervention", 0),
        "sentinel_finding_count": source_counts.get("sentinel_finding", 0),
        "pending_count": pending_count,
        "critical_count": priority_counts.get("critical", 0),
        "high_count": priority_counts.get("high", 0),
        "by_source_type": source_counts,
        "by_status": status_counts,
        "by_kind": kind_counts,
        "by_priority": priority_counts,
        "latest_at": latest_at,
        "policy": "read_only_hiq_backlog",
        "basis": "composed_from_v5_interventions_sentinel_findings_and_human_inbox",
    }

    human_inbox_surfaces = _human_inbox_surfaces(
        snapshot_at=snapshot_at,
        governance_review_records=inbox_sources["governance_review_records"],
        approval_records=inbox_sources["approval_records"],
        intervention_records=inbox_sources["intervention_records"],
        sentinel_available=bool(inbox_sources["sentinel_available"]),
        sentinel_records=inbox_sources["sentinel_records"],
        persona_rows=inbox_sources["persona_rows"],
        promotion_review_records=inbox_sources.get("promotion_review_records", []),
        source_types=human_inbox_source_types,
        surface_failures=human_inbox_failures,
        loaded_surfaces=inbox_sources.get("surfaces"),
    )
    if human_inbox_sources is not None:
        intervention_surface = human_inbox_surfaces["v5_interventions"]
        sentinel_surface = human_inbox_surfaces["sentinel_findings"]
    else:
        intervention_source = "bff_local_registry" if _V5_INTERVENTIONS_STORE else None
        intervention_surface = _dataset_surface_status(
            "v5_interventions",
            snapshot_at=snapshot_at,
            source=intervention_source or _dataset_source_after_read("v5_interventions"),
        )
        incidents_source = _dataset_source_after_read("incidents")
        if incidents_source != "missing":
            sentinel_surface = _dataset_surface_status(
                "incidents",
                snapshot_at=snapshot_at,
                source=incidents_source,
            )
        else:
            sentinel_surface = _dataset_surface_status(
                "sentinel_findings",
                snapshot_at=snapshot_at,
                source=(
                    _dataset_source_after_read("sentinel_findings")
                    if available_sentinel_findings
                    else "missing"
                ),
            )
    hiq_surface = _aggregate_group_surface(
        "hiq_backlog",
        [
            intervention_surface,
            sentinel_surface,
            human_inbox_surfaces["human_inbox"],
        ],
        snapshot_at=snapshot_at,
        unavailable_message="HIQ backlog aggregate unavailable.",
        degraded_message="HIQ backlog is available, but one or more contributing surfaces are degraded.",
    )
    data = {
        "id": "management-hiq-backlog",
        "items": page_items,
        "summary": summary,
        "policy": "read_only_hiq_backlog",
    }
    return {
        "data": data,
        "page_info": {
            "next_page_token": next_page_token,
            "total": total,
            "page_size": page_size,
        },
        "meta": {
            **_snapshot_meta(snapshot_at),
            "surfaces": {
                "hiq_backlog": hiq_surface,
                "v5_interventions": intervention_surface,
                "sentinel_findings": sentinel_surface,
                **human_inbox_surfaces,
            },
            "composition_sources": [
                "GET /bff/v5/interventions",
                "GET /bff/v5/sentinel/findings",
                "GET /bff/management/human-inbox",
            ],
            "policy": "read_only_hiq_backlog",
            "filters": {
                "source_type": source_type,
                "status": status,
                "kind": kind,
                "priority": priority,
                "q": q,
            },
        },
    }


def _intervention_stream_filter_values(value: Optional[str]) -> Optional[set[str]]:
    if not value:
        return None
    tokens = {token.strip().lower() for token in value.split(",") if token.strip()}
    if not tokens or "all" in tokens:
        return None
    return tokens


def _intervention_stream_time(record: Dict[str, Any]) -> Optional[str]:
    value = _management_first_non_empty(
        record.get("occurred_at"),
        record.get("occurredAt"),
        record.get("triggered_at"),
        record.get("triggeredAt"),
        record.get("created_at"),
        record.get("createdAt"),
        record.get("updated_at"),
        record.get("updatedAt"),
        record.get("timestamp"),
    )
    return str(value).strip() if value not in (None, "") else None


def _intervention_stream_persona_id(record: Dict[str, Any]) -> Optional[str]:
    metadata = record.get("metadata") if isinstance(record.get("metadata"), dict) else {}
    audit_context = record.get("audit_context") if isinstance(record.get("audit_context"), dict) else {}
    value = _management_first_non_empty(
        record.get("persona_id"),
        record.get("personaId"),
        metadata.get("persona_id"),
        metadata.get("personaId"),
        audit_context.get("persona_id"),
        audit_context.get("personaId"),
    )
    if value not in (None, ""):
        return str(value).strip()
    target_type = str(record.get("target_type") or record.get("targetType") or "").strip().lower()
    target_id = str(record.get("target_id") or record.get("targetId") or "").strip()
    if target_type == "persona" and target_id:
        return target_id
    return None


def _intervention_stream_source_refs(
    record: Dict[str, Any],
    *,
    intervention_id: str,
    persona_id: Optional[str],
    source_dataset: str,
) -> Dict[str, Any]:
    runtime_ids = [
        str(value)
        for value in (
            record.get("runtime_id"),
            record.get("runtimeId"),
        )
        if value
    ]
    persona_ids = [
        str(value)
        for value in (
            record.get("persona_id"),
            record.get("personaId"),
            persona_id,
        )
        if value
    ]
    strategy_ids = [
        str(value)
        for value in (
            record.get("strategy_id"),
            record.get("strategyId"),
        )
        if value
    ]
    incident_ids = [
        str(value)
        for value in (
            record.get("incident_id"),
            record.get("incidentId"),
        )
        if value
    ]
    return {
        "source_dataset": source_dataset,
        "intervention_ids": [intervention_id],
        "runtime_ids": sorted(set(runtime_ids)),
        "persona_ids": sorted(set(persona_ids)),
        "strategy_ids": sorted(set(strategy_ids)),
        "incident_ids": sorted(set(incident_ids)),
    }


def _intervention_stream_target(record: Dict[str, Any], *, intervention_id: str) -> Dict[str, Any]:
    return _hiq_backlog_target(record, fallback_type="Intervention", fallback_id=intervention_id)


def _intervention_stream_record_event(record: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    intervention_id = _management_record_id(record, "intervention_id", "id")
    if not intervention_id:
        return None
    status = _management_normalized_status(record)
    kind = str(record.get("kind") or record.get("type") or "intervention").strip().lower() or "intervention"
    occurred_at = _intervention_stream_time(record)
    persona_id = _intervention_stream_persona_id(record)
    priority = _human_inbox_priority(
        record.get("priority") or record.get("severity") or record.get("risk_level"),
        fallback="medium",
    )
    target = _intervention_stream_target(record, intervention_id=intervention_id)
    source_refs = _intervention_stream_source_refs(
        record,
        intervention_id=intervention_id,
        persona_id=persona_id,
        source_dataset="v5_interventions",
    )
    event_id = f"intervention-stream-{intervention_id}-{status}"
    return {
        "id": event_id,
        "event_id": event_id,
        "event_type": f"intervention.{status}",
        "event_source": "v5_interventions",
        "source_type": "intervention",
        "source_dataset": "v5_interventions",
        "intervention_id": intervention_id,
        "persona_id": persona_id,
        "runtime_id": record.get("runtime_id") or record.get("runtimeId"),
        "strategy_id": record.get("strategy_id") or record.get("strategyId"),
        "kind": kind,
        "status": status,
        "priority": priority,
        "risk_level": str(record.get("risk_level") or priority).strip().lower(),
        "severity": record.get("severity") or priority,
        "occurred_at": occurred_at,
        "created_at": record.get("created_at") or record.get("createdAt") or occurred_at,
        "updated_at": record.get("updated_at") or record.get("updatedAt") or occurred_at,
        "actor": record.get("triggered_by") or record.get("actor") or record.get("owner"),
        "title": record.get("title") or f"{kind.replace('_', ' ').title()} intervention",
        "summary": record.get("description") or record.get("summary") or "Intervention event projected from v5 interventions.",
        "target": target,
        "source_refs": source_refs,
        "links": {
            "source": f"/bff/v5/interventions/{intervention_id}",
            "human_inbox": f"/bff/management/human-inbox/intervention:{intervention_id}",
        },
    }


def _intervention_stream_audit_event(event: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if _governance_ledger_audit_source_type(event) != "intervention":
        return None
    audit_context = event.get("audit_context") if isinstance(event.get("audit_context"), dict) else {}
    metadata = event.get("metadata") if isinstance(event.get("metadata"), dict) else {}
    target_type = str(event.get("target_type") or event.get("targetType") or "").strip()
    intervention_id = str(
        _management_first_non_empty(
            audit_context.get("intervention_id"),
            audit_context.get("interventionId"),
            metadata.get("intervention_id"),
            metadata.get("interventionId"),
            event.get("intervention_id"),
            event.get("interventionId"),
            event.get("target_id") if target_type.lower() == "intervention" else None,
            event.get("entity_id") if target_type.lower() == "intervention" else None,
        )
        or ""
    ).strip()
    event_id = _management_record_id(event, "entry_id", "auditId", "id")
    if not event_id:
        return None
    if not intervention_id:
        intervention_id = event_id
    status = str(event.get("outcome") or event.get("status") or "recorded").strip().lower() or "recorded"
    action_type = str(event.get("action_type") or event.get("event_type") or "intervention.audit").strip()
    kind = str(audit_context.get("kind") or metadata.get("kind") or "intervention").strip().lower()
    persona_id = _intervention_stream_persona_id(event)
    occurred_at = _intervention_stream_time(event)
    source_refs = _intervention_stream_source_refs(
        event,
        intervention_id=intervention_id,
        persona_id=persona_id,
        source_dataset="governance_audit_events",
    )
    projected_id = f"intervention-stream-audit-{event_id}"
    return {
        "id": projected_id,
        "event_id": projected_id,
        "event_type": action_type,
        "event_source": "governance_audit_events",
        "source_type": "intervention",
        "source_dataset": "governance_audit_events",
        "intervention_id": intervention_id,
        "persona_id": persona_id,
        "kind": kind,
        "status": status,
        "priority": _human_inbox_priority(event.get("priority") or event.get("risk_level"), fallback="medium"),
        "risk_level": str(event.get("risk_level") or "medium").strip().lower(),
        "occurred_at": occurred_at,
        "created_at": occurred_at,
        "updated_at": occurred_at,
        "actor": event.get("actor"),
        "title": f"Intervention audit: {action_type}",
        "summary": audit_context.get("reason") or event.get("reason") or event.get("summary"),
        "target": {
            "type": target_type or "Intervention",
            "id": str(event.get("target_id") or event.get("entity_id") or intervention_id).strip(),
        },
        "source_refs": source_refs,
        "links": {
            "source": "/bff/audit",
            "intervention": f"/bff/v5/interventions/{intervention_id}",
        },
    }


def _intervention_stream_item_matches(
    item: Dict[str, Any],
    *,
    persona_ids: Optional[set[str]],
    statuses: Optional[set[str]],
    kinds: Optional[set[str]],
    q: str,
    window_start: datetime,
) -> bool:
    occurred_at = _audit_datetime(item.get("occurred_at") or item.get("occurredAt"))
    if occurred_at is not None and occurred_at < window_start:
        return False
    if persona_ids and str(item.get("persona_id") or item.get("personaId") or "").lower() not in persona_ids:
        return False
    if statuses and str(item.get("status") or "").lower() not in statuses:
        return False
    if kinds and str(item.get("kind") or "").lower() not in kinds:
        return False
    needle = q.strip().lower()
    if needle:
        target = item.get("target") if isinstance(item.get("target"), dict) else {}
        haystack = " ".join(
            str(value or "")
            for value in (
                item.get("id"),
                item.get("event_type"),
                item.get("event_source"),
                item.get("intervention_id"),
                item.get("persona_id"),
                item.get("runtime_id"),
                item.get("strategy_id"),
                item.get("kind"),
                item.get("status"),
                item.get("title"),
                item.get("summary"),
                target.get("type"),
                target.get("id"),
            )
        ).lower()
        if needle not in haystack:
            return False
    return True


def _intervention_stream_sort_key(item: Dict[str, Any]) -> tuple[datetime, str]:
    return (
        _audit_datetime(item.get("occurred_at") or item.get("occurredAt"))
        or datetime.min.replace(tzinfo=timezone.utc),
        str(item.get("id") or ""),
    )


def _management_intervention_stream_response(
    *,
    persona_id: Optional[str],
    status: Optional[str],
    kind: Optional[str],
    q: str,
    window_hours: int,
    page_token: Optional[str],
    page_size: int,
) -> Dict[str, Any]:
    snapshot_at = utc_now()
    snapshot_dt = _audit_datetime(snapshot_at) or datetime.now(timezone.utc)
    window_start_dt = snapshot_dt - timedelta(hours=window_hours)
    window_start_at = window_start_dt.isoformat().replace("+00:00", "Z")

    persona_ids = _intervention_stream_filter_values(persona_id)
    statuses = _intervention_stream_filter_values(status)
    kinds = _intervention_stream_filter_values(kind)

    intervention_records = _v5_intervention_records()
    audit_events = _list_governance_audit_events()
    events_by_id: Dict[str, Dict[str, Any]] = {}
    for record in intervention_records:
        item = _intervention_stream_record_event(record)
        if item:
            events_by_id[item["id"]] = item
    for event in audit_events:
        item = _intervention_stream_audit_event(event)
        if item:
            events_by_id.setdefault(item["id"], item)

    events = [
        item
        for item in events_by_id.values()
        if _intervention_stream_item_matches(
            item,
            persona_ids=persona_ids,
            statuses=statuses,
            kinds=kinds,
            q=q,
            window_start=window_start_dt,
        )
    ]
    events.sort(key=_intervention_stream_sort_key, reverse=True)
    for sequence, item in enumerate(events, start=1):
        item["stream_sequence"] = sequence

    total = len(events)
    page_items, next_page_token = _page_slice(events, page_token, page_size)
    persona_counts = _management_count_by(events, "persona_id")
    status_counts = _management_count_by(events, "status")
    kind_counts = _management_count_by(events, "kind")
    source_counts = _management_count_by(events, "event_source")
    latest_at = events[0].get("occurred_at") if events else None
    summary = {
        "event_count": total,
        "returned_event_count": len(page_items),
        "intervention_count": len(
            {
                str(item.get("intervention_id") or "")
                for item in events
                if str(item.get("intervention_id") or "").strip()
            }
        ),
        "persona_count": len([persona for persona in persona_counts if persona != "unknown"]),
        "window_hours": window_hours,
        "window_start_at": window_start_at,
        "window_end_at": snapshot_at,
        "latest_at": latest_at,
        "by_persona": persona_counts,
        "by_status": status_counts,
        "by_kind": kind_counts,
        "by_event_source": source_counts,
        "policy": "read_only_intervention_stream",
        "basis": "composed_from_v5_interventions_and_governance_audit_events",
    }

    intervention_source = "bff_local_registry" if _V5_INTERVENTIONS_STORE else None
    intervention_surface = _dataset_surface_status(
        "v5_interventions",
        snapshot_at=snapshot_at,
        source=intervention_source,
    )
    if intervention_records and intervention_surface.get("status") == "unavailable":
        intervention_surface = dict(_surface_status())
        intervention_surface["source"] = "service_store"
    audit_surface = _dataset_surface_status("governance_audit_events", snapshot_at=snapshot_at)
    if audit_events and audit_surface.get("status") == "unavailable":
        audit_surface = dict(_surface_status())
        audit_surface["source"] = "service_store"
    stream_surface = _aggregate_group_surface(
        "intervention_stream",
        [intervention_surface],
        snapshot_at=snapshot_at,
        unavailable_message="Intervention stream aggregate unavailable.",
        degraded_message="Intervention stream is available, but one or more contributing surfaces are degraded.",
    )
    data = {
        "id": "management-intervention-stream",
        "items": page_items,
        "summary": summary,
        "policy": "read_only_intervention_stream",
    }
    return {
        "data": data,
        "page_info": {
            "next_page_token": next_page_token,
            "total": total,
            "page_size": page_size,
        },
        "meta": {
            **_snapshot_meta(snapshot_at),
            "surfaces": {
                "intervention_stream": stream_surface,
                "v5_interventions": intervention_surface,
                "governance_audit_events": audit_surface,
            },
            "composition_sources": [
                "GET /bff/v5/interventions",
                "GET /bff/audit",
            ],
            "policy": "read_only_intervention_stream",
            "filters": {
                "persona_id": persona_id,
                "status": status,
                "kind": kind,
                "q": q,
                "window_hours": window_hours,
            },
        },
    }


_EVOLUTION_JOURNAL_REGISTERED_SEED_EXACT_IDS = {
    "87c655c3e3c9", "inc-87c655c3e3c9", "rb-001", "fo-001", "btc-drift",
    "inc-20260410-001", "inc-20260409-002", "pm-20260409-002",
    "plan-f-042", "artifact-042", "runtime-042", "binding-042",
}
# "evo-vslice-" and "ev-seed-" are registered seed *families* (see
# services/evolution/seed_data.py ev-seed-001..005) — any id in a family is
# seed-derived, unlike the one-off exact ids above.
_EVOLUTION_JOURNAL_REGISTERED_SEED_PREFIXES = ("evo-vslice-", "ev-seed-")


def _evolution_journal_is_registered_seed_id(value: Any) -> bool:
    normalized = str(value or "").strip().lower()
    if not normalized:
        return False
    if normalized in _EVOLUTION_JOURNAL_REGISTERED_SEED_EXACT_IDS:
        return True
    return any(
        normalized.startswith(prefix)
        for prefix in _EVOLUTION_JOURNAL_REGISTERED_SEED_PREFIXES
    )


_EVOLUTION_JOURNAL_TYPE_ALIASES = {
    "decision": "evolution_decision",
    "evolution": "evolution_decision",
    "evolution_decision": "evolution_decision",
    "evolution_decisions": "evolution_decision",
    "mutation": "mutation_review",
    "mutation_review": "mutation_review",
    "mutation_reviews": "mutation_review",
    "postmortem": "postmortem",
    "postmortems": "postmortem",
    "rollback": "rollback",
    "rollbacks": "rollback",
    "freeze": "freeze_order",
    "freeze_order": "freeze_order",
    "freeze_orders": "freeze_order",
}


# Typed lineage namespaces for the ?persona= filter. Two entities can share
# the same raw string id in different namespaces (e.g. a runtime_id and an
# unrelated artifact target_id both equal to "same-token") — matching must
# stay scoped to the field/target-type that produced the id, never a single
# flattened id blob.
_EVOLUTION_JOURNAL_REFERENCE_FIELD_CATEGORY = {
    "artifact_id": "artifact",
    "persona_id": "persona",
    "runtime_id": "runtime",
    "runtime_binding_id": "binding",
    "persona_capital_binding_id": "binding",
    "incident_id": "incident",
    "incident_ref": "incident",
    "linked_incident_id": "incident",
    "capital_pool_id": "pool",
    "pool_id": "pool",
    "plan_id": "plan",
    "deployment_plan_id": "plan",
}
_EVOLUTION_JOURNAL_TARGET_TYPE_CATEGORY = {
    "persona": "persona",
    "runtime": "runtime",
    "binding": "binding",
    "runtime_binding": "binding",
    "persona_capital_binding": "binding",
    "plan": "plan",
    "deployment_plan": "plan",
    "pool": "pool",
    "capital_pool": "pool",
    "candidate_artifact": "artifact",
    "artifact": "artifact",
    "incident": "incident",
}


def _evolution_journal_csv_filter(value: Optional[str]) -> Optional[set[str]]:
    if not value:
        return None
    requested = {part.strip().lower() for part in value.split(",") if part.strip()}
    return requested or None


def _evolution_journal_type_filter(value: Optional[str]) -> Optional[set[str]]:
    requested = _evolution_journal_csv_filter(value)
    if not requested:
        return None
    return {
        _EVOLUTION_JOURNAL_TYPE_ALIASES.get(entry_type, entry_type)
        for entry_type in requested
    }


def _evolution_journal_status(record: Dict[str, Any]) -> str:
    return str(
        _management_first_non_empty(
            record.get("status"),
            record.get("decision_state"),
            record.get("state"),
            "unknown",
        )
        or "unknown"
    ).strip().lower()


def _evolution_journal_timestamp(record: Dict[str, Any]) -> str:
    return str(
        _management_first_non_empty(
            record.get("updated_at"),
            record.get("updatedAt"),
            record.get("published_at"),
            record.get("completed_at"),
            record.get("executed_at"),
            record.get("initiated_at"),
            record.get("issued_at"),
            record.get("created_at"),
            record.get("createdAt"),
            record.get("triggered_at"),
        )
        or ""
    )


def _evolution_journal_target(
    *,
    target_type: Any = None,
    target_id: Any = None,
    target_version: Any = None,
    incident_id: Any = None,
    runtime_id: Any = None,
    artifact_id: Any = None,
) -> Dict[str, Any]:
    resolved_type = str(
        _management_first_non_empty(
            target_type,
            "incident" if incident_id else None,
            "runtime" if runtime_id else None,
            "artifact" if artifact_id else None,
        )
        or ""
    ).strip()
    resolved_id = _management_first_non_empty(target_id, incident_id, runtime_id, artifact_id)
    return {
        "type": resolved_type or None,
        "id": resolved_id,
        "version": target_version,
    }


def _evolution_journal_base_item(
    *,
    entry_type: str,
    source_id: str,
    title: str,
    summary: str,
    status: str,
    created_at: Any = None,
    updated_at: Any = None,
    occurred_at: Any = None,
    risk_level: Any = None,
    action_type: Any = None,
    target: Optional[Dict[str, Any]] = None,
    route: Optional[str] = None,
    bff_detail_path: Optional[str] = None,
) -> Dict[str, Any]:
    journal_id = f"{entry_type}:{source_id}"
    return {
        "id": journal_id,
        "journal_id": journal_id,
        "entryType": entry_type,
        "entry_type": entry_type,
        "source_id": source_id,
        "title": title,
        "summary": summary,
        "status": status,
        "risk_level": risk_level,
        "action_type": action_type,
        "target": target or {},
        "created_at": created_at,
        "updated_at": updated_at,
        "occurred_at": occurred_at or updated_at or created_at,
        "route": route,
        "bff_detail_path": bff_detail_path,
    }


def _evolution_journal_decision_item(decision: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    decision_id = _management_record_id(decision, "decision_id", "id", "evolution_decision_id")
    if not decision_id:
        return None
    status = _evolution_journal_status(decision)
    title = str(
        _management_first_non_empty(
            decision.get("title"),
            f"{str(decision.get('action_type') or 'Evolution').replace('_', ' ').title()} decision",
        )
    )
    summary = str(
        _management_first_non_empty(
            decision.get("summary"),
            decision.get("notes"),
            decision.get("rationale"),
            (decision.get("risk_assessment") or {}).get("risk_summary")
            if isinstance(decision.get("risk_assessment"), dict)
            else None,
            "Evolution decision recorded.",
        )
    )
    item = _evolution_journal_base_item(
        entry_type="evolution_decision",
        source_id=decision_id,
        title=title,
        summary=summary,
        status=status,
        created_at=decision.get("created_at"),
        updated_at=decision.get("updated_at"),
        occurred_at=_evolution_journal_timestamp(decision),
        risk_level=decision.get("risk_level"),
        action_type=decision.get("action_type"),
        target=_evolution_journal_target(
            target_type=decision.get("target_type"),
            target_id=_management_first_non_empty(decision.get("target_id"), decision.get("artifact_id")),
            target_version=decision.get("target_version") or decision.get("artifact_version"),
            incident_id=decision.get("incident_ref") or decision.get("linked_incident_id"),
        ),
        route=f"/management/evolution-journal?decision={decision_id}",
        bff_detail_path=f"/api/v1/evolution-decisions/{decision_id}",
    )
    item["decision"] = json.loads(json.dumps(decision))
    item["record"] = item["decision"]
    return item


def _evolution_journal_mutation_review_item(
    decision: Dict[str, Any],
    *,
    identity: OperatorIdentity,
    snapshot_at: str,
) -> Optional[Dict[str, Any]]:
    decision_id = _management_record_id(decision, "decision_id", "id", "evolution_decision_id")
    if not decision_id:
        return None
    if not any(
        decision.get(field) is not None
        for field in (
            "approval_decision_id",
            "proposed_changes",
            "risk_assessment",
            "required_approvals",
            "review_chain",
            "threshold_snapshots",
        )
    ):
        return None

    _, approval_decision, linked_incident, linked_postmortem = _mutation_review_inputs(decision_id)
    projection = _mutation_review_projection(
        decision,
        approval_decision=approval_decision,
        linked_incident=linked_incident,
        linked_postmortem=linked_postmortem,
        identity=identity,
        snapshot_at=snapshot_at,
    )
    # Preserve metadata/provenance/origin from the source decision
    for field in ("metadata", "provenance", "origin"):
        if field in decision and field not in projection:
            projection[field] = decision[field]

    item = _evolution_journal_base_item(
        entry_type="mutation_review",
        source_id=decision_id,
        title=f"Mutation review: {decision_id}",
        summary=str((projection.get("proposed_changes") or {}).get("summary") or decision.get("rationale") or ""),
        status=str(projection.get("decision_state") or "unknown").lower(),
        created_at=projection.get("created_at"),
        updated_at=decision.get("updated_at"),
        occurred_at=_evolution_journal_timestamp(decision),
        risk_level=projection.get("risk_level"),
        action_type=projection.get("action_type"),
        target=_evolution_journal_target(
            target_type=projection.get("target_type"),
            target_id=projection.get("target_id"),
            target_version=projection.get("target_version"),
        ),
        route=f"/management/evolution-journal?mutation_review={decision_id}",
        bff_detail_path=f"/api/v1/operator/mutation-review/{decision_id}",
    )
    item["mutationReview"] = json.loads(json.dumps(projection))
    item["mutation_review"] = item["mutationReview"]
    item["record"] = item["mutationReview"]
    return item


