def _persona_catalog_fallback_record(persona_id: str) -> Optional[Dict[str, Any]]:
    """Resolve a Fleet-visible persona when the direct detail store misses it."""
    clean_id = str(persona_id or "").strip()
    if not clean_id:
        return None
    for candidate in read_store.list_personas(include_market_persona_defaults=True):
        candidate_id = str(candidate.get("persona_id") or candidate.get("id") or "").strip()
        if candidate_id == clean_id:
            return dict(candidate)
    return None


def _persona_catalog_fallback_surface(snapshot_at: str) -> Dict[str, Any]:
    return {
        "status": "degraded",
        "source": "persona_catalog_list_fallback",
        "note": (
            "Resolved from the governed Persona catalog used by Persona Fleet because "
            "the direct detail store did not return this list-visible identity."
        ),
        "staleness": {
            "served_from": "persona_catalog_list_fallback",
            "last_known_at": snapshot_at,
        },
        "observed_time": snapshot_at,
        "freshness": "persona_catalog_list_fallback",
        "coverage": 1.0,
        "missing_bindings": False,
    }


def _persona_provisioning_authoritative_meta(raw: Mapping[str, Any]) -> Dict[str, Any]:
    metadata = raw.get("metadata")
    metadata = metadata if isinstance(metadata, Mapping) else {}
    readback = metadata.get("provisioning_authoritative_readback")
    readback = readback if isinstance(readback, Mapping) else {}
    schedule = readback.get("first_evaluation_schedule")
    schedule = schedule if isinstance(schedule, Mapping) else {}
    runtime_binding = readback.get("runtime_binding")
    runtime_binding = runtime_binding if isinstance(runtime_binding, Mapping) else {}
    paper_worker = readback.get("paper_worker")
    paper_worker = paper_worker if isinstance(paper_worker, Mapping) else {}

    result: Dict[str, Any] = {
        "available": bool(readback),
        "observed_at": readback.get("observed_at"),
    }
    if runtime_binding:
        result["runtime_binding"] = {
            "runtime_binding_id": (
                runtime_binding.get("runtime_binding_id")
                or runtime_binding.get("binding_id")
                or runtime_binding.get("id")
            ),
            "runtime_id": runtime_binding.get("runtime_id"),
            "plan_id": runtime_binding.get("plan_id"),
            "status": runtime_binding.get("status") or runtime_binding.get("state"),
        }
    if paper_worker:
        result["paper_worker"] = {
            "session_id": paper_worker.get("session_id") or paper_worker.get("id"),
            "runtime_id": paper_worker.get("runtime_id"),
            "runtime_binding_id": (
                paper_worker.get("runtime_binding_id")
                or paper_worker.get("binding_id")
            ),
            "status": paper_worker.get("status"),
            "last_heartbeat_at": paper_worker.get("last_heartbeat_at"),
        }
    if schedule:
        result["first_evaluation_schedule"] = {
            "persona_id": schedule.get("persona_id"),
            "workflow_id": schedule.get("workflow_id"),
            "registered": schedule.get("registered"),
            "job_id": schedule.get("job_id"),
            "job_name": schedule.get("job_name"),
            "request_id": schedule.get("request_id"),
            "runtime_id": schedule.get("runtime_id"),
            "runtime_binding_id": schedule.get("runtime_binding_id"),
            "capital_pool_id": schedule.get("capital_pool_id"),
            "persona_capital_binding_id": schedule.get("persona_capital_binding_id"),
        }
    return result


@app.get("/bff/personas/{persona_id}")
async def bff_get_persona(
    persona_id: str,
    authorization: Optional[str] = Header(default=None),
):
    """BFF: persona detail."""
    identity = _extract_identity(authorization)
    _require_read_role(identity)
    snapshot_at = utc_now()
    caller_tenant = str(_bff_me_tenant_payload(identity, requested_tenant=None)["id"])
    overlay = _PERSONA_BFF_OVERLAY.get(persona_id)
    if overlay and str(overlay.get("tenantId") or "") != caller_tenant:
        overlay = None
    raw = read_store.get_persona(persona_id)
    if raw:
        record_tenant = _persona_record_tenant_id(raw)
        if record_tenant and record_tenant != caller_tenant:
            raw = None
            overlay = None
    detail_surface = None
    if not raw and not overlay:
        raw = _persona_catalog_fallback_record(persona_id)
        if raw and _persona_record_tenant_id(raw) not in {"", caller_tenant}:
            raw = None
        if raw:
            detail_surface = _persona_catalog_fallback_surface(snapshot_at)
    if not raw and not overlay:
        raise _bff_error(
            404, ErrorCode.RESOURCE_NOT_FOUND,
            "Persona not found",
            f"Persona {persona_id} does not exist",
        )
    base = raw or {"persona_id": persona_id, "name": (overlay or {}).get("name")}
    dto = await asyncio.to_thread(
        lambda: _project_persona_dto(
            base,
            overlay=overlay,
            routed_strategies=_routed_strategies_for_persona(persona_id),
        )
    )
    containment = read_store.get_persona_containment(persona_id)
    if containment:
        containment_state = str(containment.get("containment_state") or "frozen")
        dto["containment_state"] = containment_state
        dto["containmentState"] = containment_state
        dto["frozen"] = containment_state == "frozen"
        dto["containment"] = containment
    meta = _read_surface_meta(
        "personas", "persona_detail",
        snapshot_at=snapshot_at,
        surface=detail_surface,
    )
    if containment:
        meta.setdefault("surfaces", {})["containment"] = _dataset_surface_status(
            "containments",
            snapshot_at=snapshot_at,
            has_data=True,
        )
    return {
        "data": dto,
        "meta": meta,
    }


_PERSONA_PATCH_SERVER_MANAGED_FIELDS = frozenset({
    "owner",
    "state",
    "status",
    "lifecycle_state",
    "lifecycleState",
    "lifecycleStatus",
    "paper_runtime_state",
    "paperRuntimeState",
    "runtime_id",
    "runtimeId",
    "runtime_binding_id",
    "runtimeBindingId",
    "capital_mode",
    "capitalMode",
    "deployment_stage",
    "deploymentStage",
    "created_by",
    "createdBy",
    "actor_id",
    "actorId",
    "availableActions",
})


@app.patch("/bff/personas/{persona_id}")
async def bff_patch_persona(
    persona_id: str,
    payload: Dict[str, Any] = Body(...),
    authorization: Optional[str] = Header(default=None),
    idempotency_key: Optional[str] = Header(default=None, alias="Idempotency-Key"),
    x_idempotency_key: Optional[str] = Header(default=None, alias="X-Idempotency-Key"),
):
    """BFF: patch persona fields through the BFF read store."""
    identity = _extract_identity(authorization)
    _require_operator_role(identity)
    _reject_body_idempotency_key(payload)
    managed_fields = sorted(_PERSONA_PATCH_SERVER_MANAGED_FIELDS.intersection(payload))
    if managed_fields:
        raise _bff_error(
            422,
            ErrorCode.VALIDATION_FAILED,
            "Persona lifecycle and ownership fields are server-managed",
            f"Client PATCH cannot mutate: {', '.join(managed_fields)}",
            precondition_failed=managed_fields[0],
            suggestion="Use the governed Persona action or promotion workflow.",
        )
    resolved_key = _resolve_final_idempotency_key(idempotency_key, x_idempotency_key)
    raw = read_store.get_persona(persona_id)
    overlay = _PERSONA_BFF_OVERLAY.get(persona_id)
    caller_tenant = str(_bff_me_tenant_payload(identity, requested_tenant=None)["id"])
    raw_tenant = _persona_record_tenant_id(raw) if raw else ""
    overlay_tenant = str((overlay or {}).get("tenantId") or "")
    if raw and raw_tenant not in {"", caller_tenant}:
        raw = None
        overlay = None
    if overlay and overlay_tenant != caller_tenant:
        overlay = None
    if raw and not raw_tenant and overlay is None:
        # Tenantless legacy catalog rows may remain readable, but mutation is
        # fail-closed until an authoritative tenant owner exists.
        raw = None
    if not raw and not overlay:
        raise _bff_error(
            404, ErrorCode.RESOURCE_NOT_FOUND,
            "Persona not found",
            f"Persona {persona_id} does not exist",
        )
    cache_key = ":".join(
        ("persona-patch", caller_tenant, identity.operator_id, resolved_key)
    )
    request_hash = _stable_json_hash(
        {
            "route": "PATCH /bff/personas/{persona_id}",
            "tenant_id": caller_tenant,
            "operator_id": identity.operator_id,
            "id": persona_id,
            "payload": payload,
        }
    )
    cached = _strategy_persona_idempotency_check(cache_key, request_hash)
    if cached is not None:
        return cached
    snapshot_at = utc_now()
    base = dict(overlay) if overlay else {}
    if not base:
        routed = _routed_strategies_for_persona(persona_id)
        base = _project_persona_dto(raw or {"persona_id": persona_id}, routed_strategies=routed)
    for field in (
        "name", "risk",
        "archetype", "routedStrategies", "successRate",
    ):
        if field in payload:
            base[field] = payload[field]
    if "risk" in payload:
        base["risk"] = _normalize_risk_level(payload["risk"])
    base["updatedAt"] = snapshot_at
    base["id"] = persona_id
    base["tenantId"] = caller_tenant
    existing_metadata = dict(raw.get("metadata") if isinstance(raw, dict) and isinstance(raw.get("metadata"), dict) else {})
    canonical_lifecycle = str(
        (raw or {}).get("lifecycle_state")
        or (raw or {}).get("state")
        or "draft"
    )
    update_metadata: Dict[str, Any] = {
        "success_rate": float(base.get("successRate") or 0.0),
    }
    update_metadata["openclaw_agent_reconcile"] = _openclaw_agent_reconcile_request(
        {
            "id": persona_id,
            "persona_id": persona_id,
            "name": str(base.get("name") or persona_id),
            "mandate": str(base.get("archetype") or existing_metadata.get("archetype") or "generalist"),
            "strategy_family": str(base.get("archetype") or existing_metadata.get("archetype") or "generalist"),
            "lifecycle_state": canonical_lifecycle,
            "metadata": {
                **existing_metadata,
                **update_metadata,
                "owner": str(existing_metadata.get("owner") or identity.operator_id),
                "archetype": str(base.get("archetype") or "generalist"),
                "risk_level": str(base.get("risk") or "low"),
            },
        },
        reason="persona_updated",
    )
    persona_record = read_store.update_persona(
        persona_id,
        name=str(base.get("name") or persona_id),
        actor_id=str(existing_metadata.get("owner") or identity.operator_id),
        updated_at=snapshot_at,
        archetype=str(base.get("archetype") or "generalist"),
        # Lifecycle is controller-owned.  Omitting it makes update_persona
        # re-read and preserve the latest canonical value, avoiding a stale
        # overlay racing paper_running/provisioning_failed reconciliation.
        lifecycle_state=None,
        risk_level=str(base.get("risk") or "low"),
        metadata=update_metadata,
    )
    if persona_record is not None:
        routed = _routed_strategies_for_persona(persona_id)
        base = _project_persona_dto(
            persona_record,
            overlay={
                "routedStrategies": int(base.get("routedStrategies") or routed),
                "successRate": float(base.get("successRate") or 0.0),
                "tenantId": caller_tenant,
            },
            routed_strategies=routed,
        )
    _PERSONA_BFF_OVERLAY[persona_id] = deepcopy(base)
    result = {"data": deepcopy(base), "meta": {"snapshot_at": snapshot_at}}
    _STRATEGY_PERSONA_BFF_IDEMPOTENCY[cache_key] = {
        "request_hash": request_hash,
        "result": deepcopy(result),
    }
    return result


def _ensure_persona_exists(persona_id: str) -> None:
    if (
        read_store.get_persona(persona_id)
        or persona_id in _PERSONA_BFF_OVERLAY
        or _persona_catalog_fallback_record(persona_id)
    ):
        return
    raise _bff_error(
        404, ErrorCode.RESOURCE_NOT_FOUND,
        "Persona not found",
        f"Persona {persona_id} does not exist",
    )


@app.get("/bff/personas/{persona_id}/route-policy")
async def bff_get_persona_route_policy(
    persona_id: str,
    authorization: Optional[str] = Header(default=None),
):
    """BFF: persona route policy."""
    identity = _extract_identity(authorization)
    _require_read_role(identity)
    _ensure_persona_exists(persona_id)
    snapshot_at = utc_now()
    policy = None
    fetcher = getattr(read_store, "get_route_policy_for_persona", None)
    if callable(fetcher):
        policy = fetcher(persona_id)
    if not policy:
        consult_policy = None
        consult_fetcher = getattr(read_store, "get_persona_consult_policy", None)
        if callable(consult_fetcher):
            consult_policy = consult_fetcher(persona_id)
        policy = {
            "personaId": persona_id,
            "version": "v1",
            "rules": [],
            "consult_policy": consult_policy,
        }
    return {
        "data": policy,
        "meta": _read_surface_meta(
            "personas", "persona_route_policy",
            snapshot_at=snapshot_at,
        ),
    }


@app.get("/bff/personas/{persona_id}/runtime-profile")
async def bff_get_persona_runtime_profile(
    persona_id: str,
    authorization: Optional[str] = Header(default=None),
):
    """BFF: persona OpenClaw runtime profile contract."""
    identity = _extract_identity(authorization)
    _require_read_role(identity)
    _ensure_persona_exists(persona_id)
    snapshot_at = utc_now()
    persona = read_store.get_persona(persona_id) or {"persona_id": persona_id}
    route_policy = None
    fetcher = getattr(read_store, "get_route_policy_for_persona", None)
    if callable(fetcher):
        route_policy = fetcher(persona_id)
    try:
        profile = build_persona_runtime_profile(
            persona,
            route_policy=route_policy if isinstance(route_policy, dict) else None,
        ).to_dict()
    except ValueError as exc:
        raise _bff_error(
            422,
            ErrorCode.VALIDATION_FAILED,
            "Invalid persona runtime profile",
            str(exc),
        ) from exc
    return {
        "data": profile,
        "meta": _read_surface_meta(
            "personas", "persona_runtime_profile",
            snapshot_at=snapshot_at,
        ),
    }


