    _require_read_role(identity)

    snapshot_at = utc_now()
    surface = _dataset_surface_status("runtime_bindings", snapshot_at=snapshot_at)
    clean_id = runtime_id.strip()
    binding = read_store.get_runtime_binding_by_runtime_id(clean_id)
