_SENTINEL_HEALTH_FINDING_KIND = "persona_health"
_SENTINEL_FINDING_KINDS = {
    "hiq_sentinel",
    "risk_breach",
    "strategy_drift",
    "loop_anomaly",
    _SENTINEL_HEALTH_FINDING_KIND,
}
_SENTINEL_FINDING_STATUSES = {"open", "resolved", "dismissed", "escalated"}
_SENTINEL_FINDING_SEVERITIES = {"critical", "high", "medium", "low"}


# ---------------------------------------------------------------------------
# Sentinel rule engine — HealthReasonCode coverage
# (Card P2-16 / Pack D §D-SentinelRules; see BFF_WRITE_GAP_SPEC §4.)
#
# Every persona HealthReasonCode below ``healthy`` maps to a Sentinel rule that
# emits one open finding per (persona, reason).  This closes the gap where
# degraded personas (e.g. ``persona_lifecycle_not_active`` +
# ``no_runtime_binding``) produced zero Sentinel findings.  This is rule-engine
# coverage layered onto the existing incident-derived findings; it is not a new
# endpoint.  Severity uses the canonical sentinel severity vocabulary
# (critical/high/medium/low); ``severity_bucket`` carries the Pack D
# info/warn/alert tier the FE timeline groups on.
# ---------------------------------------------------------------------------
_SENTINEL_HEALTH_REASON_RULES: Dict[str, Dict[str, str]] = {
    "persona_lifecycle_not_active": {
        "severity": "medium",
        "bucket": "info",
        "label": "Persona lifecycle not active",
    },
    "no_runtime_binding": {
        "severity": "medium",
        "bucket": "info",
        "label": "Persona has no runtime binding",
    },
    "runtime_status_attention": {
        "severity": "medium",
        "bucket": "warn",
        "label": "Runtime binding status needs attention",
    },
    "negative_pnl": {
        "severity": "high",
        "bucket": "warn",
        "label": "Persona telemetry shows negative PnL",
    },
    "active_incident": {
        "severity": "critical",
        "bucket": "alert",
        "label": "Persona has an active incident",
    },
    "drawdown_threshold": {
        "severity": "critical",
        "bucket": "alert",
        "label": "Persona breached drawdown threshold",
    },
}


def _health_reason_sentinel_findings(
    *,
    kind: Optional[str] = None,
    status: Optional[str] = None,
    severity: Optional[str] = None,
) -> List[Dict[str, Any]]:
    """Run the HealthReasonCode rule engine over the persona fleet.

    Applies one rule per HealthReasonCode (Card P2-16): every persona reason
    below ``healthy`` emits an open ``persona_health`` finding so degraded
    personas surface in the Sentinel timeline.  Health is read from the same
    projection that powers the persona-fleet surface
    (``_project_persona_fleet_item``) so the rule engine never drifts from the
    health computation clients already see.

    The optional ``kind``/``status``/``severity`` arguments mirror the
    findings-list filters and are applied in-line so callers do not double
    filter.  All findings are kind ``persona_health`` and status ``open``, so a
    filter that excludes that class short-circuits the (relatively expensive)
    fleet projection.
    """
    if kind is not None and kind.lower() != _SENTINEL_HEALTH_FINDING_KIND:
        return []
    if status is not None and status.lower() != "open":
        return []
    severity_filter = severity.lower() if severity is not None else None

    personas = _list_persona_records()
    if not personas:
        return []
    runtime_bindings = list(read_store.list_runtime_bindings() or [])
    incidents = list(read_store.list_incidents() or [])
    evolution_decisions = list(read_store.list_evolution_decisions() or [])

    findings: List[Dict[str, Any]] = []
    for persona in personas:
        item = _project_persona_fleet_item(
            persona,
            all_runtime_bindings=runtime_bindings,
            all_incidents=incidents,
            all_evolution_decisions=evolution_decisions,
        )
        persona_id = str(item.get("id") or "").strip()
        if not persona_id:
            continue
        health = item.get("health") or {}
        persona_name = str((item.get("persona") or {}).get("name") or persona_id)
        for reason in health.get("reasons") or []:
            rule = _SENTINEL_HEALTH_REASON_RULES.get(reason)
            if rule is None:
                continue
            if severity_filter is not None and rule["severity"] != severity_filter:
                continue
            findings.append(
                {
                    "id": f"sentinel-health-{persona_id}-{reason}",
                    "kind": _SENTINEL_HEALTH_FINDING_KIND,
                    "status": "open",
                    "severity": rule["severity"],
                    "severity_bucket": rule["bucket"],
                    "title": f"{rule['label']}: {persona_name}",
                    "health_reason": reason,
                    "rule_id": f"health-reason:{reason}",
                    "persona_id": persona_id,
                    "derived_from_persona_id": persona_id,
                    "health_status": health.get("status"),
                    "health_score": health.get("score"),
                }
            )
    return findings


@app.get("/bff/v5/sentinel/findings")
async def bff_v5_sentinel_findings_list(
    kind: Optional[str] = Query(default=None, description="Filter by kind: hiq_sentinel, risk_breach, strategy_drift, loop_anomaly"),
    status: Optional[str] = Query(default=None, description="Filter by status: open, resolved, dismissed, escalated"),
    severity: Optional[str] = Query(default=None, description="Filter by severity: critical, high, medium, low"),
    authorization: Optional[str] = Header(default=None),
):
    """
    GET /bff/v5/sentinel/findings — list sentinel findings from the read surface store.

    Optional query filters:
      ?kind=hiq_sentinel|risk_breach|strategy_drift|loop_anomaly
      ?status=open|resolved|dismissed|escalated
      ?severity=critical|high|medium|low

    Returns source-aware list response.  When the source is missing the items
    list is empty and meta.surfaces.sentinel_findings.source is 'missing'.
    """
    identity = _extract_identity(authorization)
    _require_read_role(identity)

    if kind is not None and kind.lower() not in _SENTINEL_FINDING_KINDS:
        raise _bff_error(
            400,
            ErrorCode.VALIDATION_FAILED,
            f"Invalid kind '{kind}'. Must be one of: {', '.join(sorted(_SENTINEL_FINDING_KINDS))}",
            "Unknown sentinel finding kind filter value",
        )
    if status is not None and status.lower() not in _SENTINEL_FINDING_STATUSES:
        raise _bff_error(
            400,
            ErrorCode.VALIDATION_FAILED,
            f"Invalid status '{status}'. Must be one of: {', '.join(sorted(_SENTINEL_FINDING_STATUSES))}",
            "Unknown sentinel finding status filter value",
        )
    if severity is not None and severity.lower() not in _SENTINEL_FINDING_SEVERITIES:
        raise _bff_error(
            400,
            ErrorCode.VALIDATION_FAILED,
            f"Invalid severity '{severity}'. Must be one of: {', '.join(sorted(_SENTINEL_FINDING_SEVERITIES))}",
            "Unknown sentinel finding severity filter value",
        )

    available, records = read_store.list_sentinel_findings(
        kind=kind,
        status=status,
        severity=severity,
    )
    records = list(records)

    # Sentinel rule engine: layer HealthReasonCode coverage on top of the
    # incident-derived findings so degraded personas surface (Card P2-16).
    health_findings = _health_reason_sentinel_findings(
        kind=kind,
        status=status,
        severity=severity,
    )
    if health_findings:
        existing_ids = {str(r.get("id")) for r in records}
        records.extend(f for f in health_findings if str(f.get("id")) not in existing_ids)
        available = True

    src_dataset = "sentinel_findings" if available and read_store.dataset_source("incidents") == "missing" else "incidents"
    source = None if available else "missing"
    return _sem_final_list_response(records, dataset=src_dataset, surface_key="sentinel_findings", source=source)


# -- V5 Loop inventory -------------------------------------------------------

def _loop_inventory_response_meta(payload: Dict[str, Any]) -> Dict[str, Any]:
    meta = dict(payload.get("meta") or {})
    surfaces = meta.setdefault("surfaces", {})
    surface = surfaces.setdefault("loop_inventory", {})
    surface.update(
        {
            "truth_level": "registry_metadata",
            "registry_ref": "docs/deployment/loop-catalog.registry.json",
            "note": "Static loop catalog read model; live_status is false unless live evidence is present.",
        }
    )
    meta["catalog"] = loop_inventory_meta()
    payload["meta"] = meta
    return payload


def _loop_health_store_records(
    tenant_id: str,
    environment: str,
) -> Tuple[bool, List[Dict[str, Any]], str]:
    available, records = read_store.list_loop_health_records()
    source = read_store.dataset_source("loop_health") if available else "missing"
    scoped_records = [
        record
        for record in records
        if isinstance(record, dict)
        and str(record.get("tenant_id") or "").strip() == tenant_id
        and str(record.get("environment") or "").strip() == environment
    ]
    return bool(available and scoped_records), scoped_records, source


def _authenticated_loop_truth_scope(
    identity: OperatorIdentity,
    *,
    requested_tenant: Optional[str],
    requested_environment: Optional[str],
) -> Tuple[str, str]:
    """Resolve a fail-closed tenant/environment key for controller truth."""

    tenant_defaults = _identity_claim_strings(
        identity,
        ["tenant_id", "tenantId", "tenant.id", "tid", "org_id"],
    )
    allowed_tenants = _dedupe_nonblank_strings(
        [
            *_identity_claim_strings(
                identity,
                [
                    "allowed_tenants",
                    "allowedTenants",
                    "tenant_ids",
                    "tenantIds",
                    "tenants",
                ],
            ),
            *tenant_defaults,
        ]
    )
    clean_requested_tenant = str(
        _resolve_param(requested_tenant) or ""
    ).strip()
    default_tenant = next(
        (tenant for tenant in tenant_defaults if tenant != "*"),
        next((tenant for tenant in allowed_tenants if tenant != "*"), ""),
    )
    effective_tenant = clean_requested_tenant or default_tenant
    if not effective_tenant:
        raise _bff_error(
            403,
            ErrorCode.FORBIDDEN,
            "Controller truth requires an authenticated tenant scope",
            "Authenticated identity does not declare a concrete tenant",
            precondition_failed="tenant_scope",
        )
    if "*" not in allowed_tenants and effective_tenant not in allowed_tenants:
        raise _bff_error(
            403,
            ErrorCode.FORBIDDEN,
            "Tenant access denied",
            "Requested controller truth tenant is outside the authenticated scope",
            precondition_failed="tenant_scope",
            details_extra={
                "tenantId": effective_tenant,
                "allowedTenantIds": allowed_tenants,
            },
        )

    deployed_environment = str(os.environ.get("PANTHEON_ENV", "dev")).strip()
    clean_requested_environment = str(
        _resolve_param(requested_environment) or ""
    ).strip()
    effective_environment = clean_requested_environment or deployed_environment
    allowed_environments = _identity_claim_strings(
        identity,
        ["environment", "environments", "allowed_environments", "allowedEnvironments"],
    )
    if allowed_environments:
        environment_allowed = (
            "*" in allowed_environments
            or effective_environment in allowed_environments
        )
    else:
        environment_allowed = effective_environment == deployed_environment
    if not effective_environment or not environment_allowed:
        raise _bff_error(
            403,
            ErrorCode.FORBIDDEN,
            "Environment access denied",
            "Requested controller truth environment is outside the authenticated deployment scope",
            precondition_failed="environment_scope",
            details_extra={
                "environment": effective_environment,
                "allowedEnvironments": allowed_environments
                or [deployed_environment],
            },
        )
    return effective_tenant, effective_environment


def _loop_health_response_meta(
    payload: Dict[str, Any],
    *,
    health_records_available: bool,
    health_record_count: int,
    accepted_controller_health_record_count: int,
    health_source: str,
    tenant_id: str,
    environment: str,
) -> Dict[str, Any]:
    meta = dict(payload.get("meta") or {})
    snapshot_at = meta.get("snapshot_at") or utc_now()
    item_count = len(payload.get("items") or ([payload.get("data")] if isinstance(payload.get("data"), dict) else []))
    registry_surface = {
        "status": "ok",
        "source": "bff_local_registry",
        "truth_level": "registry_metadata",
        "registry_ref": "docs/deployment/loop-catalog.registry.json",
        "note": "Static loop catalog supplies loop ids, owners, maturity, and expected controller contracts.",
    }
    snapshot_surface = _dataset_surface_status(
        "loop_health",
        snapshot_at=snapshot_at,
        source=health_source if health_records_available else "missing",
    )
    if item_count and accepted_controller_health_record_count >= item_count:
        loop_health_surface = {
            "status": "ok",
            "source": "bff_composed",
            "truth_level": "controller_snapshot",
            "note": "Composed from loop catalog plus controller health records.",
        }
    elif accepted_controller_health_record_count:
        loop_health_surface = {
            "status": "degraded",
            "source": "bff_composed",
            "truth_level": "partial_controller_snapshot",
            "note": "Some loops lack accepted current controller health records; registry metadata remains visible without live liveness claims.",
            "staleness": {"served_from": "mixed", "last_known_at": snapshot_at},
        }
    else:
        loop_health_surface = {
            "status": "degraded",
            "source": "bff_composed",
            "truth_level": "registry_metadata",
            "note": "Controller health snapshots are unavailable; BFF is serving registry truth without claiming live liveness.",
            "staleness": {"served_from": "registry_only", "last_known_at": snapshot_at},
        }
    surfaces = meta.setdefault("surfaces", {})
    surfaces["loop_health"] = loop_health_surface
    surfaces["loop_inventory"] = registry_surface
    surfaces["loop_health_snapshots"] = snapshot_surface
    catalog_meta = loop_inventory_meta()
    meta["catalog"] = catalog_meta
    meta["truth_labels"] = truth_label_payload()
    meta["truth_source_policy"] = {
        "accepted_live_source_types": ["live_truth"],
        "non_live_source_types": ["seed_fixture", "snapshot", "registry", "scheduled"],
        "note": "Operator panels must display seed, fixture, snapshot, registry, and scheduled truth separately from accepted live truth.",
    }
    meta["coverage"] = {
        "loop_count": item_count,
        "canonical_loop_count": catalog_meta["inventory_counts"]["canonical_loop_count"],
        "composite_overlay_count": catalog_meta["inventory_counts"]["composite_overlay_count"],
        "inventory_entry_count": catalog_meta["inventory_counts"]["inventory_entry_count"],
        "controller_health_record_count": accepted_controller_health_record_count,
        "raw_health_record_count": health_record_count,
        "controller_health_records_available": health_records_available,
        "accepted_controller_health_records_available": bool(
            accepted_controller_health_record_count
        ),
    }
    meta["scope"] = {
        "tenant_id": tenant_id,
        "environment": environment,
        "source": "authenticated_identity_and_deployment_scope",
    }
    payload["meta"] = meta
    return payload


